(window.GIM_TS=window.GIM_TS||{})["Shabbat.9"]={"from":216,"a":[["\u0003בר קשא\u0004 \u0005[פקיד אחד]\u0006 יהודי ב\u0003פומבדיתא דטרקיה חיויא\u0004 \u0005[שהכישו נחש],\u0006 \u0003הוה תליסר חמרי חיורתא\u0004 \u0005[היו שלוש עשרה אתונות לבנות]\u0006 \u0003בפומבדיתא, קרעינהו לכולהו, ואישתכחו\u0004 \u0005[קרעו את כולן, ונמצאו]\u0006 \u0003טריפה. הואי חדא בההוא גיסא\u0004 \u0005[היתה\u0006 עוד \u0005אחת בצד אחר]\u0006 של \u0003פומבדיתא\u0004 ו\u0003עד דאזלי מייתי לה\u0004 \u0005[שהלכו להביא אותה]\u0006 \u0003אכלה אריה. אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי:\u0004 כיון שאירעו בו מקרים אלה \u0003דילמא חיויא דרבנן טרקיה, דלית ליה אסותא\u0004 \u0005[שמא נחש של חכמים נשכו, ואין לו רפואה],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004חופר גומץ בו יפול \u0003ופרץ גדר ישכנו נחש\"\u0004 (קהלת י, ח), כלומר, שמא פרץ גדר גזירת חכמים וכעונש על כך נשכו הנחש, ולנשיכה זו לא תימצא תרופה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 \u0003רבי, דכי נח נפשיה\u0004 \u0005[שכאשר נחה נפשו,\u0006 מת\u0005]\u0006 \u0003רב, גזר רב יצחק בר ביסנא דליכא דלימטייה אסא וגידמי לבי הילולא בטבלא\u0004 \u0005[שלא יביאו הדס וענפים\u0006 של דקל \u0005לבית חתונה ב\u0006ליווי \u0005פעמונים],\u0006 \u0003ואזל איהו אמטי אסא וגידמי לבי הילולא בטבלא, טרקיה חיויא\u0004 \u0005[והלך הוא\u0006 ו\u0005הביא הדס וענפים\u0006 של דקל \u0005לבית החתונה בפעמונים. הכישו הנחש].\u0006 \u0003ו\u0004מסופר שאכן לבסוף \u0003מית\u0004 \u0005[ומת]\u0006 אותו פקיד.","ועוד בענין נחשים, סכנתם, ודרכי ההתנהגות איתם: \u0003האי מאן דכרכיה חיויא\u0004 \u0005[מי שנכרך עליו נחש]\u0006 — \u0003לינחות למיא וליסחוף דיקולא ארישא ולהדקיה מיניה\u0004 \u0005[יירד למים וישים סל על ראשו ויעבירנו,\u0006 לנחש, \u0005ממנו]\u0006 לאט לאט אל הסל, \u0003וכי סליק עילויה\u0004 — \u0003לישדיה למיא וליסלוק וליתי\u0004 \u0005[וכאשר עולה\u0006 הנחש \u0005עליו,\u0006 על הסל — \u0005יזרקנו למים ויעלה ויצא].\u0006 \u0003האי מאן דמיקני ביה חיויא\u0004 \u0005[מי שמקנא בו,\u0006 כועס עליו ה\u0005נחש]\u0006 ורודף אחריו, \u0003אי איכא חבריה בהדיה\u0004 \u0005[אם יש חבירו אתו]\u0006 — \u0003לירכביה\u0004 \u0005[ירכיבנו]\u0006 עליו \u0003ארבע גרמידי\u0004 \u0005[אמות],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 אינו יכול או ש\u0003לא\u0004 עזר הדבר — \u0003לישואר נגרא\u0004 \u0005[יקפוץ\u0006 מעבר \u0005לתעלה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 עדיין \u0003לא\u0004 נפתר הדבר — \u0003ליעבר נהרא\u0004 \u0005[שיעבור נהר],\u0006 \u0003ובליליא\u0004 — \u0003לותביה לפוריא\u0004 \u0005[ובלילה\u0006 — \u0005ישים מיטתו]\u0006 על \u0003ארבעה חביתא\u0004 \u0005[חביות],\u0006 \u0003וניגני בי כוכבי, וליתי\u0004 \u0005[ויישן\u0006 בחוץ \u0005בין,\u0006 תחת, \u0005הכוכבים, ויביא]\u0006 \u0003ארבעה שונרי\u0004 \u0005[חתולים]\u0006 \u0003וליסרינהו\u0004 \u0005[ויקשרם]\u0006 \u0003בארבעה כרעי דפורייה\u0004 \u0005[רגלי המיטה],\u0006 \u0003וליתי שחפי ולישדי התם, דכי שמע קלי אכלי ליה\u0004 \u0005[ויביא קיסמים וענפים ויזרקם שם, שכאשר יישמע קולו\u0006 של הנחש זוחל עליהם \u0005יאכלו אותו\u0006 החתולים\u0005].\u0006 \u0003האי מאן דרהיט אבתריה\u0004 \u0005[מי ש\u0006הנחש \u0005רץ אחריו]\u0006 — \u0003לירהיט בי חלתא\u0004 \u0005[ירוץ בין החולות],\u0006 שבהם אין הנחש מסוגל למהר בריצה, כאדם.","\u0003האי איתתא דחזיא חיויא\u0004 \u0005[אותה אשה הרואה נחש],\u0006 \u0003ולא ידעה אי יהיב דעתיה עילוה, אי לא יהיב דעתיה עילוה\u0004 \u0005[ואינה יודעת אם נותן דעתו עליה, או לא נותן דעתו עליה],\u0006 \u0003תשלח מאנה ונשדייה קמיה\u0004 \u0005[תפשוט בגדה ותזרוק לפניו],\u0006 \u0003אי מכרך בהו\u0004 \u0005[אם נכרך בהם\u0006 הנחש\u0005]\u0006 סימן הוא ש\u0003דעתיה עילוה\u0004 \u0005[דעתו עליה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא\u0004 נכרך בהם — סימן הוא ש\u0003לא יהיב דעתיה עילוה\u0004 \u0005[נותן דעתו עליה].\u0006","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003תקנתה\u0004 שירפה ממנה \u0003— תשמש\u0004 עם בעלה \u0003קמיה\u0004 \u0005[בפניו].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 אם תשמש בפניו \u0003כל שכן דתקיף ליה יצריה\u0004 \u0005[שיתגבר בו יצרו],\u0006 \u0003אלא תשקול ממזיה ומטופרה ותשדי ביה\u0004 \u0005[תיקח משערה ומצפורניה, ותזרוק בו],\u0006 \u0003ותימא\u0004 \u0005[ותאמר לו]\u0006 בדרך לחש: \u0003\"דישתנא אנא\"\u0004 \u0005[\"נדה אני\"].\u0006 \u0003האי איתתא דעייל\u0004 \u0005[אשה שנכנס]\u0006 \u0003בה חיויא\u0004 \u0005[\u0006ה\u0005נחש],\u0006 \u0003ליפסעה ולתבוה אתרתי חביתא\u0004 \u0005[יפשקו רגליה ויעמידוה על שתי חביות],\u0006 \u0003וליתי בישרא שמנה ולישדי אגומרי\u0004 \u0005[ויביאו בשר שמן ויזרקוהו,\u0006 יניחוהו \u0005על גחלים],\u0006 \u0003וליתי אגנא דתחלי וחמרא ריחתנא ולותבו התם, וליטרוקינהו בהדי הדדי\u0004 \u0005[ויביאו קערת שחליים ויין ריחני ויעמידו שם, ויערבבום זה בזה],\u0006 \u0003ולינקוט צבתא\u0004 \u0005[ותחזיק\u0006 \u0003צבת] בידה, דכי מירח ריחא\u0004 — \u0003נפיק ואתי\u0004 \u0005[שכאשר מריח\u0006 הנחש \u0005ריח\u0006 — הוא \u0005יוצא ובא],\u0006 \u0003ולישקליה וליקלייה בנורא\u0004 \u0005[וייקחוהו וישרפוהו באש],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 ישרפוהו — \u0003הדר עילוה\u0004 \u0005[יחזור עליה].\u0006","שנינו במשנה שמותר לאכול בשבת את \u0003כל\u0004 מיני \u0003האוכלין\u0004 (מאכלים) לרפואה. ושאלו: לשון זה \u0003\"כל האוכלין\"\u0004 ששנינו \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות, את \u0005מה]?\u0006 ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003טחול ל\u0004רפואת ה\u0003שינים וכרשינין ל\u0004רפואת \u0003בני\u0004 ה\u0003מעיים,\u0004 אף שלא הכל רגילים באכילתם. עוד שנינו במשנה שאדם שותה בשבת את כל המשקים. ושואלים: לשון זה \u0003\"כל המשקין\" לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות, את \u0005מה]?\u0006 ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003מי צלפין\u0004 (מיץ של פרי הצלף) המעורב בחומץ. אמר ליה \u0005[לו]\u0006 \u0003רבינא לרבא: מהו\u0004 הדין האם מותר \u0003לשתות מי רגלים בשבת? אמר ליה\u0004 \u0005[לו]\u0006 רבא: הלא כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"כל המשקין שותה\", ומי רגלים לא שתו אינשי\u0004 \u0005[אין אנשים שותים],\u0006 ואינם בכלל משקה ואסור משום רפואה בשבת.","שנינו במשנה שאדם שותה בשבת את כל המשקים \u0003חוץ ממי דקלים. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא דין זה בגירסה שונה: \u0003\"מי דקרים\".\u0004 ומסבירים: \u0003מאן דתנא\u0004 \u0005[מי ששנה]\u0006 \u0003\"מי דקרים\",\u0004 כוונתו מפני \u0003שהם דוקרים את המרה, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003\"מי דקלים\"\u0004 כוונתו מפני \u0003שיוצאין מן שני דקלי\u0004 \u0005[דקלים].\u0006 וכדי להסביר \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003מי דקלים, אמר רבה בר ברונא: תרתי תלאי איכא במערבא, ונפקא עינא דמיא מבינייהו\u0004 \u0005[שני דקלים יש בארץ ישראל, ויוצא מעין של מים מביניהם].\u0006 \u0003כסא קמא\u0004 \u0005[\u0006שתיית \u0005כוס ראשונה]\u0006 מאותם מים — \u0003מרפי\u0004 \u0005[מרפה]\u0006 את המעיים, \u0003אידך\u0004 \u0005[האחרת,\u0006 השניה\u0005]\u0006 — \u0003משלשל, ואידך\u0004 \u0005[והאחרת,\u0006 השלישית\u0005]\u0006 — \u0003כי היכי דעיילי, הכי נפקי\u0004 \u0005[כמו שנכנסו\u0006 המים, \u0005כך\u0006 הם \u0005יוצאים].\u0006 \u0003אמר עולא: לדידי שתי שיכרא דבבלאי, ומעלי מינייהו\u0004 \u0005[אני שותה שיכר של בבליים, ו\u0006הוא \u0005מועיל מהם\u0006 לשלשול\u0005].\u0006 ומעירים: \u0003והוא\u0004 דווקא כשהשותה \u0003לא רגיל ביה ארבעין יומין\u0004 \u0005[בו\u0006 בשיכר \u0005ארבעים יום],\u0006 שאז משפיע הוא כך על הקיבה.","\u0003רב יוסף אמר:\u0004 מי דקרים הם \u0003זיתום המצרי\u0004 והוא עשוי \u0003תילתא שערי, ותילתא קורטמי, ותילתא מילחא\u0004 \u0005[שליש שעורים, ושליש כרכום, ושליש מלח].\u0006 \u0003רב פפא אמר: תילתא חיטי, ותילתא קורטמי, ותילתא מילחא וכמונא\u0004 \u0005[שליש חטים, ושליש כרכום, ושליש מלח וכמון]\u0006 \u0003וסימניך\u0004 שתזכור מי מהם אמר שזיתום עשוי משעורים — הסל שקרוי \u0003סיסאני\u0004 שיש במלה פעמיים את האות ס' לסימן: שרב יוסף שיש בשמו את האות ס' הוא שעורים (ולענין זה האות ש' היא כ־ס'). \u0003ושתי להו\u0004 \u0005[ושותה אותם]\u0006 \u0003בין דבחא לעצרתא\u0004 \u0005[פסח לעצרת,\u0006 שבועות\u0005],\u0006 \u0003דקמיט\u0004 \u0005[\u0006מי \u0005ש\u0006הוא \u0005עוצור\u0006 במיעיו\u0005]\u0006 — \u0003מרפי ליה\u0004 \u0005[מרפה אותו],\u0006 \u0003ודרפי\u0004 \u0005[ו\u0006מי \u0005ש\u0006הוא \u0005רפוי,\u0006 משולשל\u0005]\u0006 — \u0003קמיט ליה\u0004 \u0005[עוצר אותו].\u0006","\u0003ו\u0004עוד שנינו במשנה \u0003כוס עקרין.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003כוס עקרין\u0004 זו? \u0003אמר ר' יוחנן: לייתי מתקל זוזא קומא אלכסנדריא\u0004 \u0005[יביא משקל זוז קומוס אלכסנדרי],\u0006 \u0003ומתקל זוזא גביא גילא\u0004 \u0005[ומשקל זוז אלום],\u0006 \u0003ומתקל זוזא כורכמא רישקא, ולישחקינהו בהדי הדדי\u0004 \u0005[ומשקל זוז כרכום הגינה, וישחקם יחד].\u0006 \u0003לזבה\u0004 — ישקה \u0003תלתא בחמרא\u0004 \u0005[שלושה\u0006 מינים אלה \u0005ביין]\u0006 ותתרפא מהזוב, \u0003ולא מיעקרא\u0004 \u0005[תהיה עקרה].\u0006 \u0003לירקונא\u0004 \u0005[ל\u0006רפואת חולי \u0005ירקון]\u0006 — ישתה \u0003תרין בשיכרא, ומיעקר\u0004 \u0005[שנים\u0006 מהם \u0005בשיכר,\u0006 ואולם \u0005נעשה עקר].\u0006 אמרנו כי \u0003לזבה\u0004 ישקה \u0003תלתא בחמרא\u0004 \u0005[שלושה\u0006 מינים אלה \u0005ביין]\u0006 ותתרפא מהזוב, \u0003ולא מיעקרא\u0004 \u0005[תהיה עקרה].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועילה לה רפואה זו — \u0003לייתי תלתא\u0004 \u0005[יביא שלושה]\u0006"],["\u0003קפיזי שמכי פרסאי\u0004 \u0005[כלים מלאים בצלים פרסיים],\u0006 \u0003ונישלוק בחמרא, ונשקייה, ונימא\u0004 \u0005[ויבשל ביין, וישקה אותה, ויאמר]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך. ואי\u0004 \u0005[ואם]\u0006 אף זה \u0003לא\u0004 הועיל — \u0003לותבה\u0004 \u0005[יושיבנה]\u0006 על \u0003פרשת דרכים, ולינקטה כסא דחמרא\u0004 \u0005[ושתחזיק כוס יין]\u0006 \u0003בידה, וליתי איניש מאחורה וליבעתה, ולימא\u0004 \u0005[ויבוא אדם מאחוריה ויפחידנה, ויאמר]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך, ואי\u0004 \u0005[ואם]\u0006 גם זה \u0003לא\u0004 הועיל — \u0003ליתי בונא דכמונא ובונא דמוריקא ובונא דשבלילתא\u0004 \u0005[מלוא אגרוף כמון, ומלוא אגרוף\u0006 \u0003כרכום, ו\u0004\u0005מלוא אגרוף תלתן],\u0006 \u0003ונישלוק בחמרא, ונשקייה, ונימא\u0004 \u0005[ויבשל ביין, וישקה אותה, ויאמר ]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך. ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליתי שיתין שיעי דדנא, ולשפיה, ולימא\u0004 \u0005[שיביא ששים מגופות חבית וישרה אותן ויאמר]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך. ואי\u0004 \u0005[ואם]\u0006 גם זה \u0003לא\u0004 הועיל — \u0003ליתי פשטינא, ולישלוק בחמרא, ולשפיה, ונימא\u0004 \u0005[יביא עשב, ויבשל ביין, וישרה אותו, ויאמר]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך. ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליתי חרנוגא דהיגתא רומיתא, וליקלי, וליסבה בשחקי דכיתנא בקייטא ובשחקי דעמר גופנא בסיתוא\u0004 \u0005[יביא את\u0006 הצמח הטפיל \u0005על ההגה הרומאי, וישרפנו, וישים אותו,\u0006 את האפר, \u0005בבלאי בגד פשתן בקיץ ובבלאי בגד צמר גפן בחורף].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליכרי שבע בירי, וליקלי בהו שבישתא ילדה\u0004 \u0005[יכרה שבעה בורות וישרוף בהם זמורות צעירות]\u0006 של \u0003גפן ערלה, ולינקטה כסא דחמרא\u0004 \u0005[ויתן כוס יין]\u0006 \u0003בידה, ולוקמה מהא ולותבה אהא, ולוקמה מהא ולותבה אהא\u0004 \u0005[ויעמידה מ\u0006בור \u0005זה ויושיבוה בזה, ויעמידה מזה ויושיבוה בזה]\u0006 \u0003ואכל חדא וחדא לימא\u0004 \u0005[ועל כל אחד ואחד יאמר]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך. ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליתי סמידא, וליסכה מפלגא לתתאי, ולימא\u0004 \u0005[יביא סולת, ויסמוך אותה מחציה למטה, ויאמר]\u0006 \u0003לה: קום\u0004 \u0005[חדלי]\u0006 \u0003מזוביך. ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליתי ביעתא דנעמיתא, וליקלי, וליסבה בשחקי דכיתנא בקייטא ובשחקי דעמר גופנא בסיתוא\u0004 \u0005[יביא ביצת יען, וישרפנה, ויכניסנה בבלאי פשתן בקיץ ובבלאי צמר גפן בחורף].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 גם זה \u0003לא\u0004 הועיל — \u0003ליפתח\u0004 \u0005[יפתח]\u0006 \u0003לה חביתא דחמרא\u0004 \u0005[חבית יין]\u0006 \u0003לשמה,\u0004 עבורה, ותשתה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003לנקיט שערתא דמשתכחת בכפותא דכודנא חיורא\u0004 \u0005[שתחזיק שעורה הנמצאת בגללי פרדה לבנה],\u0006 \u0003אי נקטה חד יומא\u0004 \u0005[אם תחזיקנה יום אחד]\u0006 — \u0003פסקה תרי יומי\u0004 \u0005[תפסיק\u0006 את הזיבה, \u0003ואי נקטה תרי יומי\u0004 \u0005[ואם תחזיקנה יומיים]\u0006 — \u0003פסקה תלתא יומי\u0004 \u0005[תפסיק שלושה ימים],\u0006 \u0003ואי נקטה תלתא יומי\u0004 \u0005[ואם תחזיקנה שלושה ימים]\u0006 — \u0003פסקה\u0004 \u0005[תפסיק]\u0006 \u0003לעולם.\u0004","הזכרנו מקודם את הסגולה \u0003לירקונא\u0004 \u0005[ל\u0006רפואת חולי \u0005ירקון]\u0006 שישתה \u0003תרין בשיכרא\u0004 \u0005[שנים\u0006 מן הדברים המוזכרים שם \u0005בשכר],\u0006 \u0003ומיעקר\u0004 \u0005[וייעקר].\u0006 ואמרו: \u0003ואי לא\u0004 היו לו אותם דברים, קומוס אלכסנדרי, כרכום גינה ואלום, או שלא הואילו — \u0003לייתי רישא דשיבוטא דמילחא ולישלוק בשיכרא, ולישתי\u0004 \u0005[יביא ראש שיבוטה במלח ויבשלנו בשיכר, וישתה]\u0006 אותו משקה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003לייתי מוניני דקמצי\u0004 \u0005[יביא ציר חגבים]\u0006 וישתה ממנו. \u0003ואי ליכא מוניני דקמצי\u0004 \u0005[ואם אין ציר חגבים]\u0006 — \u0003לייתי מוניני דנקירי\u0004 \u0005[יביא ציר עופות קטנים],\u0006 \u0003וליעייליה לבי בני ולישפייה\u0004 \u0005[וייכנס לבית המרחץ וישפשף אותו\u0006 בו\u0005].\u0006 \u0003ואי ליכא בי בני\u0004 \u0005[ואם אין בית מרחץ]\u0006 — \u0003לוקמיה\u0004 \u0005[יעמידוהו]\u0006 \u0003בין תנורא לגודא\u0004 \u0005[התנור והקיר],\u0006 כדי שיזיע וייצא חוליו. \u0003אמר ר' יוחנן: הרוצה שיחממנו\u0004 לחולה זה — \u0003יקנחנו בסדינו\u0004 ויעטפנו בו יפה. \u0003רב אחא בר יוסף חש ביה\u0004 \u0005[חלה בה,\u0006 במחלה זו\u0005],\u0006 ו\u0003עבד ליה\u0004 \u0005[ועשה לו]\u0006 \u0003רב כהנא\u0004 רפואה זו, \u0003ואיתסי\u0004 \u0005[והתרפא].\u0006","ומוסיפים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועילה רפואה זו — \u0003ליתי תלתא קפיזי תמרי פרסייתא\u0004 \u0005[יביא שלוש מידות תמרים פרסיות],\u0006 \u0003ותלתא קפיזי דקירא דנישתרופי\u0004 \u0005[ושלוש מידות שעוה נוטפת],\u0006 \u0003ותלתא קפיזי אהלא תולענא\u0004 \u0005[ושלוש מידות אהל אדום],\u0006 \u0003ולישלוקינהו בשיכרא, ולישתי\u0004 \u0005[ויבשלם בשיכר, וישתה]\u0006 אותו משקה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועילה רפואה זו — \u0003ליתי עילא בר חמרא\u0004 \u0005[יביא עיר בן חמור],\u0006 \u0003וליגלח מציעתא דרישא, ולישביק ליה דמא מאפותיה, ולותביה ארישיה\u0004 \u0005[ויגלח\u0006 החולה \u0005את אמצע ראשו, ויקיז לו,\u0006 לחמור, \u0005דם ממצחו, וישים אותו על ראשו],\u0006 \u0003וליזהר מעיניה דלא ליסמי להו\u0004 \u0005[וייזהר מעיניו\u0006 שלא ייכנס הדם לתוכן כדי \u0005שלא יעוור אותו].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליתי רישא דברחא דמנח בכיבשא, ולישלוק בשיכרא, ולישתי\u0004 \u0005[יביא ראש איל המונח בכבישה,\u0006 כבוש, \u0005ויבשלנו בשיכר, וישתה]\u0006 משקה זה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועילה רפואה זו — \u0003ליתי\u0004 \u0005[יביא]\u0006 \u0003דבר אחר\u0004 (חזיר) \u0003חוטרנא\u0004 \u0005[מנומר],\u0006 \u0003וליקרעיה, ולותביה אליביה\u0004 \u0005[ויקרענו, ויניחנו על לבו].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועיל — \u0003ליתי כרתי מכבתותא דמישרי\u0004 \u0005[יביא כרישים מאמצע הערוגה],\u0006 שהם חריפים ביותר.","ומסופר: \u0003ההוא טייעא דחש ביה\u0004 \u0005[ערבי\u0006 \u0005אחד שחלה בו,\u0006 במחלת הירקון\u0005],\u0006 \u0003אמר ליה לגינאי\u0004 \u0005[לו לגנן]:\u0006 \u0003שקול גלימאי והב\u0004 \u0005[קח\u0006 את \u0005גלימתי ותן]\u0006 \u0003לי\u0004 תמורתה \u0003מישרא דכרתי\u0004 \u0005[ערוגת כרישים].\u0006 \u0003יהיב ליה\u0004 \u0005[נתן לו]\u0006 \u0003ואכלה. אמר ליה\u0004 \u0005[לו]\u0006 אותו ערבי לגנן: \u0003אושלן גלימיך ואיגני ביה קלי\u0004 \u0005[השאילני גלימתך ואישן בה מעט].\u0006 נתן לו ו\u0003איכרך גנא ביה\u0004 \u0005[התעטף וישן בה].\u0006 \u0003כד איחמם וקם, נפל פורתא פורתא מיניה\u0004 \u0005[כאשר התחמם ועמד\u0006 ממקומו, \u0005נפלו מעט מעט,\u0006 חתיכות חתיכות, \u0005ממנה],\u0006 וכך הערים אותו ערבי על הגנן שבסופו של דבר לא קבל מאומה.","מקודם הוזכר ש\u0003לירקונא\u0004 \u0005[ל\u0006רפואת חולי \u0005ירקון]\u0006 ישתה \u0003תרין בשיכרא, ומיעקר\u0004 \u0005[שנים\u0006 מן המינים \u0005בשיכר,\u0006 ואולם \u0005נעשה עקר].\u0006 ושואלים: \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 לגרום עקרות? והרי שנינו: \u0003מניין לסירוס באדם שהוא אסור\u0004 — \u0003תלמוד לומר: \"\u0004ומעוך וכתות ונתוק וכרות לא תקריבו לה' \u0003ובארצכם לא תעשו\"\u0004 (ויקרא כב, כד), ומשמעו — \u0003בכם לא תעשו,\u0004 אלו \u0003דברי ר' חנינא.\u0004 נמצא שאסור לגרום עקרות לאדם! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאסרו — הרי זה דווקא \u0003היכא דקא מיכוין\u0004 \u0005[במקום שהוא מתכוין]\u0006 לסירוס, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003מעצמו הוא\u0004 הסירוס נעשה, שנגרם אגב רפואת הירקון. וראיה שמותר באופן כזה, ש\u0003אמר ר' יוחנן: הרוצה שיסרס תרנגול\u0004 — \u0003יטול כרבלתו, ומסתרס מאליו,\u0004 נמצא שסירוס הבא מאליו — מותר. ודוחים: \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003רב אשי: רמות רוחא\u0004 (גאוה) \u0003הוא דנקיטא ליה\u0004 \u0005[היא שאוחזת בו,\u0006 בתרנגול\u0005]\u0006 כשיש לו כרבולת, ומשניטלה ממנו מתעצב ואינו משמש עוד, אבל אינו נעשה סריס ממש. \u0003אלא\u0004 יש לומר שרפואה זו מותרת רק ל\u0003סריס\u0004 שאין לחוש לעקרותו.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן:\u0004"],["\u0003הכל מודים במחמץ\u0004 את המנחה שבמקדש או עוסק בה ומשלים מלאכתה כשהחמיצה \u0003אחר מחמץ,\u0004 שאף שכבר היתה מחומצת \u0003— שהוא חייב\u0004 גם על חימוץ זה. \u0003שנאמר\u0004 בדבר זה: \u0003\"לא תאפה חמץ\"\u0004 (ויקרא ו, י), וגם: \u0003\"\u0004כל המנחה אשר תקריבו לה' \u0003לא תעשה חמץ\"\u0004 (ויקרא ב, יא), ובדרך מדרש ההלכה למדו שחייב על כל פעולה ופעולה במנחת חמץ. וכן הכל מודים \u0003במסרס אחר מסרס\u0004 — \u0003שהוא חייב, שנאמר \"ומעוך וכתות ונתוק וכרות\u0004 לא תקריבו לה' ובארצכם לא תעשו\u0003\"\u0004 (ויקרא כב, כד), ולכאורה, \u0003אם על כרות,\u0004 שרק נכרתו אצלו חוטי האשכים — \u0003חייב, על נתוק\u0004 שאשכיו נותקו לגמרי — \u0003לא כל שכן\u0004 שנחייבנו! \u0003אלא להביא\u0004 (ללמד) על ה\u0003נותק אחר כורת שהוא חייב.\u0004 נמצא שאף הגורם עקרות לסריס חייב! \u0003ואלא\u0004 יש לומר שהרפואה הגורמת עקרות הותרה \u0003בזקן,\u0004 שאינו מסוגל להוליד.","ומקשים: אף בזקן, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 על הרפואות להחזרת הכוח הרבייה: \u0003הן הן החזירוני לנערותי,\u0004 נמצא שאף הזקן מסוגל להוליד אם ישתמש בריפוי הראוי! \u0003אלא\u0004 יש לומר שסגולה זו נאמרה \u0003באשה\u0004 שאינה מצווה על פריה ורביה. ושואלים: \u0003ול\u0004שיטת \u0003ר' יוחנן בן ברוקא\u0004 ש\u0003אמר: על שניהם,\u0004 גם על הגבר וגם על האשה, \u0003הוא אומר : \"ויברך אותם אלהים ויאמר להם\u0004 אלהים \u0003פרו ורבו\u0004 ומלאו את הארץ וכבשוה\u0003\"\u0004 (בראשית א, כח) \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי לשיטה זו אף אשה מחוייבת לפרות ולרבות! ומתרצים: לשיטתו רפואה זו ראויה ל\u0003זקינה, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בעקרה,\u0004 שאף הוא מודה שבאשה שאינה מסוגלת ללדת אין איסור בגרימת עקרות.","\u0003החושש בשיניו\u0004 — \u0003לא יגמע בהן\u0004 בשבת \u0003את החומץ\u0004 לרפואה, \u0003אבל מטבל הוא\u0004 את מאכלו \u0003כדרכו\u0004 בחומץ ואוכלו, \u0003ו\u0004אף שבדרך זו מגיע החומץ לשיניו, מכל מקום \u0003אם נתרפא\u0004 — \u0003נתרפא. החושש במתניו\u0004 — \u0003לא יסוך\u0004 עליהם בשבת \u0003יין וחומץ,\u0004 לפי שכן סכים לרפואה, \u0003אבל סך הוא את השמן. ו\u0004אולם \u0003לא שמן וורד\u0004 שהוא יקר ביותר, ואין סכים אותו אלא לרפואה. ואולם \u0003בני מלכים סכין שמן ורד על מכותיהן\u0004 בשבת, \u0003שכן דרכן לסוך\u0004 שמן ורד להנאת סיכה \u0003בחול. ר' שמעון אומר: כל ישראל בני מלכים הם,\u0004 ומותר לכל לסוך בשבת בשמן ורד.","\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הקשה \u0005לו]\u0006 \u0003רב אחא אריכא\u0004 \u0005[הארוך]\u0006 ש\u0003הוא רב אחא בר פפא לר' אבהו: תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003החושש בשיניו\u0004 — \u0003לא יגמע בהן את החומץ. למימרא\u0004 \u0005[האם נאמר]\u0006 כי \u0003חומץ מעלי\u0004 \u0005[יפה]\u0006 \u0003לשינים?! והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"כחמץ לשנים וכעשן לעינים\u0004 כן העצל לשולחיו\u0003\"\u0004 (משלי י, כו)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי ניתן לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 שמשמע מהפסוק שאינו טוב לשיניים — הרי זה \u0003בקיוהא\u0004 \u0005[בחומץ]\u0006 של ה\u0003פרי,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שמשמע ממשנתנו שהוא טוב לשיניים — הרי זה \u0003בחלא\u0004 \u0005[בחומץ]\u0006 שביין \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003הא והא בחלא\u0004 \u0005[בזה ובזה\u0006 מדובר \u0005בחומץ\u0006 יין\u0005],\u0006 ויש לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהוא יפה לשיניים — הרי זה באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003מכה\u0004 בשינים, ואילו \u0003הא\u0004 \u0005[זו]\u0006 שמשמע מהפסוק שאינו טוב לשיניים — הרי זה באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003מכה.\u0004 ומסבירים: \u0003כאשר איכא\u0004 \u0005[יש]\u0006 \u0003מכה\u0004 — הריהו \u0003מסי\u0004 \u0005[מרפא],\u0006 ואם \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003מכה\u0004 — הריהו \u0003מרפי\u0004 \u0005[מרופף]\u0006 את השיניים.","שנינו במשנה: \u0003לא יגמע בהן,\u0004 בשיניו \u0003את החומץ\u0004 בשבת. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 זה ששנינו שלא יגמע בהן חומץ בשבת הכוונה היא ש\u0003לא יגמע ופולט, אבל מגמע ובולע! אמר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן\u0006 את הדין ב\u0005משנתנו],\u0006 ב\u0003מגמע ופולט תנן\u0004 \u0005[שנינו].\u0006 \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שאסרה המשנה ב\u0003מגמע ובולע,\u0004 עדיין יש לחלק ולומר כי \u0003כאן\u0004 בברייתא שהתירה לגמוע חומץ מדובר — ב\u0003לפני טיבול\u0004 מאכלו בחומץ, שנראה שהוא גומע חומץ להנאה, ואילו \u0003כאן\u0004 במשנתנו מדובר — ב\u0003לאחר טיבול,\u0004 שניכר לכל שגומע משום רפואה.","ומקשים: \u0003ונימא\u0004 \u0005[ונאמר]:\u0006 \u0003מ\u0004אחר ש\u0003לפני טיבול שרי\u0004 \u0005[מותר]\u0006 — \u0003לאחר טיבול נמי שרי\u0004 \u0005[גם כן מותר].\u0006 \u0003דשמעינן ליה\u0004 \u0005[ששמענו אותו]\u0006 את \u0003רבא דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא מקבל\u0005]\u0006 את הנימוק \u0003\"הואיל\",\u0004 שדנו חכמים אם מותר לאדם לטבול עצמו בשבת, אף שיתכן לומר כי מאחר ובטהרתו הריהו כמתקן עצמו, ואמרו שבשבת מותר משום שנראה כרוחץ להנאתו, אבל ביום הכיפורים סברו לאסור, כיון שאסור לרחוץ להנאה.","ו\u0003אמר רבא: ליכא מידי\u0004 \u0005[אין דבר]\u0006 ש\u0003בשבת שרי\u0004 \u0005[מותר]\u0006 \u0003וביום הכפורים אסור,\u0004 ו\u0003הואיל\u0004 ו\u0003בשבת שרי\u0004 \u0005[מותר]\u0006 — \u0003ביום הכפורים נמי שרי\u0004 \u0005[גם כן מותר].\u0006 ואף שטעם ההיתר בשבת אינו קיים ביום הכיפורים, מכל מקום מתיר רבא מטעם \"הואיל\", שאין לחלק בתקנות חכמים וראוי להשוותן ככל האפשר. ואף כאן, אם מותר לגמוע חומץ לפני טיבול — לא יתכן שיאסר לאחר טיבול!","ועונים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא מהך\u0004 \u0005[מזה]\u0006 שאסר גמיעת חומץ. ומקשים: \u0003ממאי דמהך הדר ביה\u0004 \u0005[מנין שמזה חזר בו],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מ\u0004ההלכה \u0003ההיא\u0004 בענין טבילה ביום הכיפורים \u0003הדר ביה\u0004 \u0005[חזר בו]?\u0006 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל חייבי טבילות טובלין כדרכן, בין בתשעה באב בין ביום הכפורים,\u0004 וודאי תואמים דברי רבא לשיטת ברייתא זו.","שנינו במשנה שלדעת התנא קמא \u0003החושש במתניו\u0004 אסור לו לסוך שמן ורד על מכתו, ור' שמעון מתיר. \u0003אמר ר' אבא בר זבדא\u0004 שכך \u0003אמר רב: הלכה כ\u0004שיטת \u0003ר' שמעון.\u0004 ותוהים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 כי \u0003רב כ\u0004שיטת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שימי בר חייא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: האי מסוכרייא דנזייתא\u0004 \u0005[הבגד ששמים בברז החבית]\u0006"],["\u0003אסור להדוקיה ביומא טבא\u0004 \u0005[אסור להדקו ביום טוב]\u0006 מחמת איסור סחיטה. והלא ר' שמעון מתיר בדבר שאינו מתכוון! ומתרצים: \u0003ב\u0004הלכה \u0003ההיא אפילו ר' שמעון מודה\u0004 שאסור. ש\u0003אביי ורבא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\u0004מקרה של \u0003\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\".\u0004 שכל מלאכה, אף זו המותרת, שהתוצאה ההכרחית שלה היא מלאכה אסורה — אסור לעשותה בשבת אף לדעת ר' שמעון, וכיון שלא יתכן להכניס את הבגד בנקב החבית בלא לסחוט — אף ר' שמעון מודה שאסור.","ושבים ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חייא בר אשי\u0004 שכך \u0003אמר רב\u0004 במפורש: \u0003הלכה כ\u0004שיטת \u0003ר' יהודה, ורב חנן בר אמי אמר\u0004 בשם \u0003שמואל: הלכה כ\u0004שיטת \u0003ר' שמעון. ורב חייא בר אבין מתני לה\u0004 \u0005[שונה אותה]\u0006 מסורת \u0003בלא גברי\u0004 \u0005[\u0006שמות ה\u0005אנשים]\u0006 המוסרים את ההלכה בשם אחרים, אלא במישרין, \u0003רב אמר: הלכה כ\u0004שיטת \u0003ר' יהודה, ושמואל אמר: הלכה כ\u0004שיטת \u0003ר' שמעון! אלא אמר רבא: אני וארי שבחבורה תרגימנא\u0004 \u0005[פירשנו].\u0006 ומעירים דרך אגב: \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 \"הארי שבחבורה\" — \u0003ר' חייא בר אבין,\u0004 והוא ואני פירשנו: \u0003הלכה\u0004 היא אכן \u0003כ\u0004שיטת \u0003ר' שמעון, ולאו מטעמיה\u0004 \u0005[ו\u0006אולם \u0005לא מטעמו].\u0006","ומעתה באים לברר את הדברים: \u0003מאי\u0004 \u0005[מה]\u0006 בדיוק פירוש \u0003\"הלכה כ\u0004שיטת \u0003ר' שמעון ולאו מטעמיה\u0004 \u0005[ולא מטעמו]\u0006 \u0003\"? אילימא\u0004 \u0005[אם נאמר]\u0006 כי \u0003הלכה כ\u0004שיטת \u0003ר' שמעון דשרי\u0004 \u0005[שהתיר]\u0006 לסוך, \u0003ולאו מטעמיה\u0004 \u0005[ולא מטעמו],\u0006 ש\u0003אילו ר' שמעון סבר\u0004 \u0005[סבור]\u0006 כי שמן ורדים \u0003מסי\u0004 \u0005[מרפא],\u0006 \u0003ו\u0004אילו \u0003רב סבר\u0004 \u0005[סבור]\u0006 כי הוא \u0003לא מסי\u0004 \u0005[מרפא].\u0006 ולכן התיר לסוך בו בשבת, שאין בו משום רפואה. ואולם \u0003וסבר\u0004 \u0005[וכי סבור]\u0006 \u0003רב\u0004 כי שמן ורדים \u0003לא מסי\u0004 \u0005[מרפא]?\u0006 \u0003והא מדקתני\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו]\u0006 \u0003\"בני מלכים סכין על גבי מכותיהן שמן וורד\" מכלל\u0004 הדבר אתה למד \u0003דמסי\u0004 \u0005[ש\u0006הוא \u0005מרפא].\u0006 \u0003אלא\u0004 יש לומר: \u0003הלכה כ\u0004שיטת \u0003ר' שמעון\u0004 שהתיר, \u0003ולאו מטעמיה\u0004 \u0005[ולא מטעמו],\u0006 ש\u0003אילו ר' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003אף על גב דלא שכיח\u0004 \u0005[אף על פי שאינו מצוי]\u0006 שמן הורד במקומו של זה ודמיו יקרים, וכל הרואה שסך בו מבין שודאי לרפואה הוא עושה כן, מכל מקום \u0003שרי\u0004 \u0005[מותר].\u0006 \u0003ורב סבר\u0004 \u0005[סבור]:\u0006 \u0003אי שכיח\u0004 \u0005[אם\u0006 שמן הורד \u0005מצוי]\u0006 באותו מקום — \u0003אין\u0004 \u0005[כן],\u0006 מותר לו לסוך בו, \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא שכיח\u0004 \u0005[מצוי]\u0006 — \u0003לא. ובאתרא\u0004 \u0005[ובמקום]\u0006 של \u0003רב שכיח משחא דוורדא\u0004 \u0005[מצוי שמן ורד],\u0006 ולכן התיר רב לכל אדם לסוך בו בשבת, אבל במקום שאינו מצוי סבר כחכמים האוסרים.","","\u0003ואלו קשרים שחייבין עליהן\u0004 אם קושרים אותם בשבת: כגון \u0003קשר הגמלין וקשר הספנין\u0004 שהם קשרים של קיימא (המתקיימים), שעושים אותם כדי שישארו כך לעולם, \u0003וכשם שהוא חייב על קישורן\u0004 של אלה, \u0003כך הוא חייב על היתרן. ר' מאיר אומר,\u0004 כלל יש בדבר: \u0003כל קשר שהוא יכול להתירו באחת מידיו\u0004 — \u0003אין חייבין עליו\u0004 אם קשרו, שקשר רופף כזה אינו קרוי קשר של קיימא, אפילו נתכוון לכך.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003קשר הגמלין וקשר הספנין? אילימא קטרא דקטרי בזממא\u0004 \u0005[אם תאמר\u0006 שהוא \u0005הקשר שקושרים בחח]\u0006 שקושר בחח הגמל רצועה כדי למושכו בה, \u0003ו\u0004כן \u0003קטרא דקטרי באיסטרידא\u0004 \u0005[וקשר\u0006 חבל \u0005שקושרים בטבעת\u0006 הקבועה \u0005בחרטום הספינה]\u0006 לקושרה באמצעותו לחוף כדי שתעמוד במקומה. והלא \u0003האי\u0004 \u0005[זה]\u0006 \u0003קשר שאינו של קיימא\u0004 \u0005[קיום,\u0006 המתקיים\u0005]\u0006 \u0003הוא,\u0004 שהרי מתירים אותו מזמן לזמן! \u0003אלא\u0004 קשר הגמלים הוא \u0003קיטרא דזממא גופיה\u0004 \u0005[קשר החח עצמו],\u0006 הקשר שבו קושרים את החח אל הגמל, \u0003ו\u0004קשר הספנים \u0003דאיסטרידא גופה\u0004 \u0005[של טבעת הספינה עצמה],\u0006 הקשר שקושר את הטבעת לספינה, שאין מתירים קשרים אלה והם קשרים המתקיימים. שנינו במשנה ש\u0003ר' מאיר אומר\u0004 וקובע כלל: ש\u0003כל קשר\u0004 שיכולים להתירו ביד אחת אין חייבים עליו. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אחדבוי אחוי\u0004 \u0005[אחיו]\u0006 של \u0003מר אחא:\u0004 קשר \u0003עניבה ל\u0004שיטת \u0003ר' מאיר מהו\u0004 דינו, המותר לעשותו בשבת כשמהדקו כראוי, או לא? וצדדי הבעיה: האם \u0003טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' מאיר\u0004 הוא \u0003משום\u0004 ש\u0003יכול להתירו באחת מידיו הוא, והא נמי\u0004 \u0005[ו\u0006קשר עניבה \u0005זה\u0006 \u0005גם כן]\u0006 \u0003יכול להתירו,\u0004 ונמצא שאינה קשר יציב, \u0003או דילמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003ר' מאיר משום\u0004 שקשר הניתר ביד אחת הוא \u0003לא מיהדק\u0004 \u0005[מהודק]\u0006 דיו \u0003והא מיהדק\u0004 \u0005[וזה,\u0006 קשר עניבה, \u0005מתהדק].\u0006 שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","","\u0003יש לך קשרין שאין חייבין עליהן\u0004 כשעושה אותם בשבת בשוגג קרבן חטאת \u0003כ\u0004מו על \u0003קשר הגמלין, וכקשר הספנין,\u0004 אבל אסור מלכתחילה לעשותם, וכגון: \u0003קו‍שרת אשה מפתח חלוקה\u0004 ברצועות \u0003ו\u0004כן \u0003חוטי סבכה\u0004 שבראשה, \u0003ו\u0004כן שרוכים \u0003של פסקיא\u0004 (חגורה רחבה הנקשרת בשרוכים), \u0003ו\u0004כן קושרים \u0003רצועות\u0004 של \u0003מנעל ו\u0004של \u0003סנדל ו\u0004של \u0003נודות\u0004 (נאדות) \u0003יין ושמן, וקדירה של בשר\u0004 שקושרים בגד על פיה. \u0003ר' אליעזר בן יעקב אומר: קושרין\u0004 חבל לרוחב הפתח \u0003לפני הבהמה בשביל שלא תצא.\u0004","שואלים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה,\u0006 המשנה, \u0005קשה],\u0006 שכן מצד אחד \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 כי \u0003יש קשרין שאין חייבין עליהן כקשר הגמלין וכקשר הספנין,\u0004 ומשמע: \u0003חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא דליכא\u0004 \u0005[שאין]\u0006 בדבר, \u0003הא איסורא\u0004 \u0005[אבל איסור\u0006 שמדברי סופרים\u0005]\u0006 — \u0003איכא\u0004 \u0005[יש],\u0006 \u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003קו‍שרת אשה מפתח חלוקה,\u0004 ומשמע: \u0003אפילו לכתחילה\u0004 מותר! ומתרצים, \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 התנא \u0005במשנה\u0006\u0005]:\u0006 \u0003יש קשרין שאין חייבין עליהן\u0004 אם עשו אותם בשבת בשוגג, \u0003כקשר הגמלין וכקשר הספנין. ומאי ניהו\u0004 \u0005[ומה הם]\u0006 —"],["\u0003קיטרא דקטרי בזממא וקיטרא דקטרי באיסטרידא\u0004 \u0005[הקשר שקושרים בחח והקשר שקושרים בטבעת חרטום הספינה],\u0006 ובאלה \u0003חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא דליכא\u0004 \u0005[שאין]\u0006 \u0003הא איסורא\u0004 — \u0003איכא\u0004 \u0005[אבל איסור\u0006 — \u0005יש].\u0006 \u0003ויש שמותרין\u0004 בעשייה בשבת \u0003לכתחילה, ומאי ניהו\u0004 \u0005[ומה הם]\u0006 — האשה ש\u0003קושרת מפתחי חלוקה.\u0004","שנינו במשנה שאשה יכולה לקשור בשבת \u0003מפתח חלוקה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמותר, הלא קשר זה עשוי להתירו ואינו של קיימא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא לאופן \u0003דאית ליה תרי דשי\u0004 \u0005[שיש לו,\u0006 לפתח \u0005שני דשים]\u0006 וקושרים בשניהם יחד. \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003חדא מינייהו בטולי מבטיל\u0004 \u0005[אחד מהם בטל\u0006 משימוש\u0005]\u0006 כיון שיכולה לפשוט הבגד אף אם תתיר רק אחד מהם, וממילא נחשב זה שבטל כקשר של קיימא, ומאחר ואיננו יודעים איזהו ייאסרו שניהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ששניהם אינם נחשבים כקבועים.","\u0003ו\u0004עוד שנינו במשנה שאשה יכולה לקשור בשבת \u0003חוטי סבכה.\u0004 ושואלים: הלא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמותר לקושרם! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא לאופן \u0003דרויחא\u0004 \u0005[שמרווחת]\u0006 \u0003לה\u0004 הקשירה. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מישלף שלפא לה\u0004 \u0005[\u0006נוהגת היא \u0005לחלוץ אותה]\u0006 ולהשאיר את הקשר קבוע, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003אשה חסה על שערה\u0004 וחוששת שייתלש בדרך זו \u0003ומישרא שריא לה\u0004 \u0005[ו\u0006לכן \u0005מתירה אותה,\u0006 את הסבכה\u0005].\u0006","שנינו במשנה: \u0003ו\u0004מתירים לקשור בשבת \u0003רצועות מנעל וסנדל. איתמר\u0004 \u0005[נאמר]\u0006 ששנו בברייתא במקום אחר: מי ש\u0003התיר\u0004 בשוגג בשבת \u0003רצועות מנעל וסנדל, תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 שהעושה כן \u0003חייב חטאת. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 שהוא \u0003פטור\u0004 מחטאת \u0003אבל אסור\u0004 לו לעשות כך מלכתחילה. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מותר לכתחילה.\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003מנעל\u0004 על ענין \u0003מנעל,\u0004 וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003סנדל\u0004 על ענין \u0003סנדל.\u0004","ומתרצים: מענין \u0003מנעל\u0004 על ענין \u0003מנעל לא קשיא\u0004 \u0005[קשה],\u0006 שכן אפשר לומר כי \u0003הא דקתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]\u0006 בה ש\u0003חייב חטאת\u0004 — מדברת \u0003בדאושכפי\u0004 \u0005[ב\u0006קשר \u0005הסנדלרים],\u0006 שהם קושרים במנעל קשר קבוע שלא יינתק. וברייתא זו ששנינו בה ש\u0003פטור אבל אסור\u0004 — מדברת \u0003בדרבנן\u0004 \u0005[ב\u0006מנעל \u0005של חכמים],\u0006 כשלעתים הם מתירים את קשר הרצועה, וברייתא זו ששנינו בה ש\u0003מותר לכתחלה\u0004 מדברת \u0003ב\u0004מנעל של \u0003בני\u0004 העיר \u0003מחוזא\u0004 המקפידים בלבושיהם ורצועות מנעליהם עשויות להיפתח ולהיקשר בכל יום.","וכן מענין \u0003סנדל\u0004 על ענין \u0003סנדל לא קשיא\u0004 \u0005[קשה],\u0006 שכן ניתן לחלק ולומר כי \u0003הא דקתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]\u0006 בה ש\u0003חייב חטאת\u0004 — מדברת \u0003בדטייעי דקטרי אושכפי\u0004 \u0005[ב\u0006סנדלי ה\u0005ערבים שקושרים הסנדלרים]\u0006 בהם קשר קבוע. וברייתא זו ששנינו בה ש\u0003פטור אבל אסור\u0004 — מדברת \u0003בדחומרתא דקטרי אינהו\u0004 \u0005[ברצועות שקושרים הם,\u0006 שאר בני האדם\u0005].\u0006 וברייתא זו ששנינו בה ש\u0003מותר לכתחילה\u0004 — מדברת \u0003בסנדל דנפקי ביה בי תרי\u0004 \u0005[שיוצאים בו שנים]\u0006 לסירוגין, וכל אחד מהם מתירו וקושרו לפי מידתו \u0003כ\u0004סנדלו של \u0003רב יהודה.\u0004 וכפי שמסופר ש\u0003רב יהודה אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב סלא חסידא הוה ליה ההוא זוגא דסנדלי\u0004 \u0005[היו לו זוג סנדלים],\u0006 \u0003זמנין דנפיק ביה איהו, זימנין נפיק ביה ינוקיה\u0004 \u0005[פעמים שיצא בהם הוא,\u0006 ו\u0005פעמים יצא בו ילדו].\u0006 \u0003אתא לקמיה\u0004 \u0005[הגיע\u0006 רב יהודה \u0005לפני]\u0006 \u0003אביי,\u0004 ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לאביי: \u0003כהאי גונא מאי\u0004 \u0005[באופן כזה מהו]\u0006 הדין, האם יכול אני לקשור את רצועותי בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003חייב חטאת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003השתא\u0004 \u0005[עכשיו]\u0006 אפילו אם פסק דינו הוא ש\u0003פטור אבל אסור קא קשיא\u0004 \u0005[היה קשה]\u0006 \u0003לי,\u0004 ואם כן \u0003\"חייב חטאת\" קאמרת\u0004 \u0005[אומר אתה]\u0006 \u0003לי?!\u0004 שאל אותו אביי: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אומר אתה כך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003משום\u0004 ש\u0003בחול\u0004 (ימות החול) \u0003נמי זימנין נפיקנא ביה אנא, זימנין נפיק ביה ינוקא\u0004 \u0005[גם כן פעמים יוצא בו אני, פעמים יוצא בו הילד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מותר\u0004 להתיר את רצועותיו \u0003לכתחילה.\u0004","מסופר כי \u0003ר' ירמיה הוה קאזיל בתריה\u0004 \u0005[היה הולך\u0006 בשבת \u0005אחרי]\u0006 \u0003ר' אבהו בכרמלית. איפסיק\u0004 \u0005[נפסקה]\u0006 ה\u0003רצועה דסנדליה\u0004 \u0005[של סנדלו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה לר' אבהו: \u0003מאי ניעבד לה\u0004 \u0005[מה נעשה לו\u0006 לסנדל\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אבהו: \u0003שקול גמי לח דחזי\u0004 \u0005[הראוי]\u0006 \u0003למאכל בהמה, וכרוך עילויה\u0004 \u0005[עליו,\u0006 על הסנדל\u0005]\u0006 להחזיקו. ומסופר עוד: \u0003אביי הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב יוסף\u0004 בשבת, \u0003איפסיק ליה\u0004 \u0005[נפסקה לו]\u0006 ה\u0003רצועה\u0004 של הסנדל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב יוסף: \u0003מאי איעביד ליה\u0004 \u0005[מה אעשה בו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שבקיה\u0004 \u0005[הניחנו]\u0006 ואל תטלטלו. אמר לו אביי: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 מקרה זה \u0003מ\u0004זה של \u0003ר' ירמיה?\u0004 ענה לו: \u0003התם\u0004 — \u0003לא מינטר, הכא\u0004 — \u0003מינטר\u0004 \u0005[שם\u0006 — \u0005לא\u0006 היה הסנדל \u0005נשמר. כאן\u0006 — \u0005נשמר\u0006 הוא\u0005].\u0006 אמר לו אביי: ובכל זאת \u0003והא מנא\u0004 \u0005[והרי\u0006 עדיין \u0005כלי]\u0006 \u0003הוא\u0004 ומותר אם כן לטלטלו בשבת, \u0003דאי בעינא הפיכנא ליה\u0004 \u0005[ש\u0006הרי \u0005אם אני רוצה אני\u0006 יכול \u0005להפוך אותו]\u0006 \u0003מ\u0004צד \u0003ימין ל\u0004צד \u0003שמאל,\u0004 ואפשר עדיין להשתמש בו. שכן בכל סנדל היו קבועות שתי רצועות, חיצונית ופנימית (מימין ומשמאל), ומשנפסקה החיצונית אף שבדרך כלל שוב אין הסנדל ראוי לשימוש כיון שאין דרך בני אדם לקושרו בפנימית, מכל מקום עדיין יכול הוא לנעול את של ימין בשמאלו ואת של שמאל בימינו ובכך להפוך את מקום השרוכים, שהרצועה שהיתה קודם לכן פנימית נעשית עתה חיצונית! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מ\u0004מה ש\u0003מתרץ ר' יוחנן אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003ר' יהודה,\u0004 וכפי שיבואר, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003הלכה כ\u0004שיטת \u0003ר' יהודה,\u0004 ומכאן אפשר להסיק שסנדל אינו נחשב כלי אם הופכים אותו.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה הלכה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סנדל\u0004 טמא \u0003שנפסקו שתי אזניו\u0004 המחזיקות את הרצועות, \u0003או שתי תרסיותיו\u0004 (רצועות הסנדל. גאונים) \u0003או שניטל כל הכף\u0004 (הסוליה) \u0003שלו\u0004 — \u0003טהור,\u0004 ששוב אינו כלי. אבל אם נפסקה רק \u0003אחת מאזניו או אחת מתרסיותיו, או שניטל\u0004 רק \u0003רוב הכף שלו\u0004 — עדיין הוא \u0003טמא. ר' יהודה אומר:\u0004 אם \u0003נפסקה\u0004 התרסית ה\u0003פנימית\u0004 — \u0003טמא,\u0004 שאפשר עוד להשתמש בחיצונה. ואם נפסקה \u0003החיצונה\u0004 — \u0003טהור. ואמר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: כמחלוקת לענין טומאה כך מחלוקת לענין שבת,\u0004 אם מותר או אסור ללכת בסנדל כזה. \u0003אבל לא לענין חליצה.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בבעיה זו: \u0003ר' יוחנן אליבא דמאן\u0004 \u0005[כשיטתו של מי]\u0006 הוא סבור? \u0003אילימא אליבא דרבנן\u0004 \u0005[אם תאמר כשיטת חכמים]\u0006 ונפרש כך: \u0003מ\u0004מה ש\u0003לענין טומאה מנא הוי\u0004 \u0005[כלי הוא]\u0006 — \u0003לענין שבת נמי מנא הוי\u0004 \u0005[גם כן כלי הוא],\u0006 \u0003אבל לא לחליצה, דלאו מנא\u0004 \u0005[ש\u0006בעניינה \u0005לא כלי]\u0006 \u0003הוא, והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלצה\u0004 כשהיתה נעל \u0003של שמאל ב\u0004רגל \u0003ימין\u0004 — \u0003חליצתה כשרה.\u0004 והרי שאף במינעל הפוך אפשר לחלוץ, ואין לומר שסנדל כגון זה אינו כלי ראוי לחליצה! \u0003ואלא\u0004 יש לומר שאמר ר' יוחנן דבריו \u0003אליבא\u0004 \u0005[כשיטת]\u0006 \u0003ר' יהודה,\u0004 והתכוון: \u0003מ\u0004מה ש\u0003לענין טומאה לאו מנא\u0004 \u0005[לא כלי]\u0006 \u0003הוא, לענין שבת נמי לאו מנא\u0004 \u0005[גם כן לא כלי]\u0006 \u0003הוא, אבל לא לחליצה\u0004 שבעניינה \u0003מנא\u0004 \u0005[\u0006ל\u0005כלי],\u0006 מנעל ראוי, \u0003הוא\u0004 נחשב.","ומקשים: \u0003אימר דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 שאם \u0003חלצה\u0004 נעל \u0003של שמאל ב\u0004רגל \u0003ימין חליצתה כשרה,\u0004 הרי זה דווקא \u0003היכא דלמילתיה מנא\u0004 \u0005[היכן שלעניינו כלי]\u0006 \u0003הוא,\u0004 שהרי לענין חליצה ראוי הסנדל אף לרגל שמאל, ואולם \u0003הכא למילתיה לאו מנא\u0004 \u0005[כאן\u0006 אפילו לענין שבת וטומאה \u0005לצורכו לא כלי]\u0006 \u0003הוא, דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר' יהודה: נפסקה\u0004 רצועת הסנדל \u0003החיצונה\u0004 — \u0003טהור. אלמא\u0004 \u0005[מכאן]\u0006 שר' יהודה סבור כי \u0003לאו מנא\u0004 \u0005[לא כלי]\u0006 \u0003הוא!\u0004 ונמצא שקשים דברי ר' יוחנן לפי כל שיטה. ומתרצים: \u0003לעולם\u0004 תאמר שדבריו \u0003אליבא\u0004 \u0005[כשיטת]\u0006 \u0003ר' יהודה\u0004 הם, ואולם \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 שאמר ר' יוחנן: \u0003וכן לחליצה. והא קמשמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע,\u0006 חידש \u0005לנו]:\u0006 \u0003דכי אמרינן\u0004 \u0005[שכאשר אנו אומרים]\u0006 שאם \u0003חלצה\u0004 נעל \u0003של שמאל בשל ימין\u0004 ש\u0003חליצתה כשרה\u0004 — הרי זה דווקא \u0003היכא\u0004 \u0005[היכן,\u0006 במקום\u0005]\u0006"],["\u0003דלמילתיה מנא\u0004 \u0005[שלעניינו כלי]\u0006 \u0003הוא, אבל הכא\u0004 — \u0003למילתיה לאו מנא\u0004 \u0005[כאן\u0006 — גם \u0005לעניינו לא כלי]\u0006 \u0003הוא.\u0004","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך],\u0006 שהלכה כדברי רב יהודה האומר שאם נפסקה הרצועה החיצונית הסנדל טהור? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: הלכה כסתם משנה, ותנן\u0004 \u0005[ושנויה\u0006 משנה\u0005]:\u0006 \u0003סנדל\u0004 שהיה טמא במדרס הזב \u0003שנפסקה אחת מאזניו ותיקנה\u0004 — עדיין \u0003טמא מדרס,\u0004 שאוזן שנפסקה אינה פוסלת את הסנדל משימוש ועדיין כלי גמור הוא, \u0003נפסקה\u0004 האוזן ה\u0003שניה ותיקנה\u0004 — \u0003טהור מלטמא מדרס,\u0004 שכן בניתוק שתי אוזניו בטל מלהיות עוד כלי ונטהר \u0003אבל\u0004 עדיין \u0003טמא\u0004 הוא מחמת \u0003מגע מדרס,\u0004 שכיון שבפועל יש בו רק אוזן אחת קרועה עדיין כלי הוא והרי יש בו עוד אפשרות לקבל טומאה, ונחשב כאילו קיבל טומאה מעצמו במצבו הקודם. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר כי \u0003לא שנא\u0004 הדין לענין זה בין את נקרעה הרצועה ה\u0003פנימית ולא שנא\u0004 \u0005[שונה]\u0006 אם נקרעה הרצועה ה\u0003חיצונה,\u0004 ואוזן סנדל אחת שנפסקה אינה מבטלת אותו ונסתרו איפוא דברי ר' יוחנן!","ודוחים: \u0003לא,\u0004 המדובר במשנה הוא ב\u0003פנימית דוקא,\u0004 ובשנפסקה הפנימית אף לדעת רב יהודה הסנדל טמא\u0003.\u0004 ושואלים: \u0003אבל\u0004 אם נפסקה הרצועה ה\u0003חיצונה מאי\u0004 \u0005[מה]\u0006 דין הסנדל — \u0003טהור, אי הכי, אדתני\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה]\u0006 בהמשך הדברים: \u0003נפסקה\u0004 ה\u0003שניה ותיקנה\u0004 — \u0003טהור מן המדרס אבל טמא מגע מדרס, ניפלוג בדידה\u0004 \u0005[שיחלוק ב\u0006הלכה זו \u0005עצמה]\u0006 באופן זה: \u0003במה דברים אמורים\u0004 — \u0003שנפסקה\u0004 ה\u0003פנימית, אבל\u0004 אם נפסקה ה\u0003חיצונה\u0004 — \u0003טהור\u0004 הסנדל! \u0003אמר רב יצחק בן יוסף: תהא משנתנו\u0004 מתפרשת \u0003בסנדל שיש לו ארבע אזנים וארבע תרסיותים\u0004 ונפרש את האמור בה \"נפסקה שניה\" — אוזן חיצונית שניה. כדי ש\u0003לא לשבור\u0004 (לסתור) את \u0003דבריו של ר' יוחנן.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל מסר ש\u0003אמר רב חנן בר אבא\u0004 שכך \u0003אמר רב: הלכה כ\u0004שיטת \u0003ר' יהודה. ור' יוחנן אמר: אין הלכה כ\u0004שיטת \u0003ר' יהודה.\u0004 ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שאין הלכה כר' יהודה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מ\u0004מה ש\u0003מתרץ ר' יוחנן אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' יהודה, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003כ\u0004שיטת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא]!\u0006 ומתרצים: \u0003אמוראי נינהו\u0004 \u0005[אמוראים הם]\u0006 שנחלקו \u0003בדבר ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' יוחנן\u0004 נחלקו.","בהקשר עם ההלכה הקודמת מביאים, \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת כלים: \u0003כל כלי בעלי בתים\u0004 שנטמאו ולאחר מכן ניקבו, \u0003שיעורן\u0004 כדי להטהר בנקב \u0003כ\u0004גודל \u0003רמונים. בעי\u0004 \u0005[שאל]\u0006 \u0003חזקיה: ניקב\u0004 הכלי בחור שגודלו \u0003כמוציא זית וסתמו, וחזר וניקב\u0004 בצידו \u0003כמוציא זית וסתמו,\u0004 וכן הלאה \u0003עד שהשלימו\u0004 באותם נקבים \u0003ל\u0004כדי \u0003מוציא רימון, מהו\u0004 דינו? האם נאמר שבסך הכל הלא ניקב הכלי בכמוציא רימון וטהור, או כיון שלא היתה נקיבתו בבת אחת, ובכל פעם לא ניקב כשיעור עדיין טמא הוא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 תלמידו: \u0003רבי,\u0004 והלא \u0003שנית לנו\u0004 ש\u0003סנדל\u0004 טמא מדרס הזב \u0003שנפסקה אחת מאזניו ותיקנה\u0004 שעדיין הוא \u0003טמא מדרס. נפסקה\u0004 הרצועה ה\u0003שניה ותיקנה\u0004 — \u0003טהור מן המדרס, אבל טמא מגע מדרס. ואמרינן\u0004 \u0005[ואמרנו]\u0006 \u0003לך: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 דין ה\u0003ראשונה\u0004 שאם נקרעה עדיין הוא טמא — \u0003דהא קיימא\u0004 \u0005[שהרי\u0006 עדיין \u0005מצוייה]\u0006 ה\u0003שניה,\u0004 ואם כן כאשר נקרעה ה\u0003שניה נמי\u0004 \u0005[גם כן]\u0006 הרי \u0003מתקנה\u0004 \u0005[מתוקנת]\u0006 ה\u0003ראשונה\u0004 ורק אוזן אחת קרועה! ומדוע נטהר הסנדל ממדרס?","\u0003ואמרת לן עליה\u0004 \u0005[לנו על כך]\u0006 שטעם הטהרה הוא משום ש\u0003פנים חדשות באו לכאן.\u0004 שהסנדל שתיקנו את שתי אוזניו שוב אינו נחשב כסנדל הראשון, אלא כסנדל חדש, ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בכלי שניקב כמה פעמים ובכל פעם סתמו מחדש נאמר כי \u0003פנים חדשות באו לכאן\u0004 וייטהר.","התפעל חזקיה מר' יוחנן שפתר לו את השאלה מדבריו שלו, \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 ואמר: \u0003לית דין בר אינש\u0004 \u0005[אין זה בן אדם]\u0006 אלא מלאך. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאמר עליו: \u0003כגון דין בר אינש\u0004 \u0005[זה\u0006 הוא \u0005אדם].\u0006 ובדומה קצת \u0003אמר ר' זירא אמר רבא בר זימונא: אם ראשונים בני מלאכים\u0004 — \u0003אנו בני אנשים. ואם ראשונים בני אנשים\u0004 — \u0003אנו כחמורים. ולא כחמורו של ר' חנינא בן דוסא ושל ר' פנחס בן יאיר\u0004 שהראו בינה יתירה \u0003אלא כשאר חמורים\u0004 רגילים.","\u0003ו\u0004עוד שנינו במשנה שקשרי \u0003נודות\u0004 (נאדות) \u0003יין ושמן\u0004 אינם נחשבים כקשרים של קיימא ומותר לעשותם בשבת. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 המשנה לומר זאת אלא לאופן מיוחד וכגון \u0003דאית ליה תרתי אוני\u0004 \u0005[שיש לו\u0006 לנאד \u0005שתי אוזניים,\u0006 פתחים\u0005],\u0006 שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003חדא מינייהו בטולי מבטל לה\u0004 \u0005[אחת מהן מבטל אותה]\u0006 ורוצה שהקשר בה יהא קשר קבוע, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כך.","עוד שנינו במשנה שאף מותר לקשור בגד על \u0003קדירה של בשר\u0004 לכסותה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 המשנה לומר זאת אלא לאופן מיוחד וכגון \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 לקדירה \u0003שלאכא\u0004 \u0005[שרוך]\u0006 הקושר פתח נוסף שיש בה בקדירה זו, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי מאחר ובדרך כלל די בפתח אחד ולכן \u0003בטולי מבטל לה\u0004 \u0005[מבטל\u0006 הוא \u0005אותו,\u0006 את הקשר שבקדירה\u0005]\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","עוד שנינו במשנה ש\u0003ר' אליעזר בן יעקב אומר\u0004 ש\u0003קושרה\u0004 לחבל בשבת לפני הבהמה לרוחב הפתח בשביל שלא תצא. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 ומדוע לא יותר לו לעשות כן? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא לאופן \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 לאותו פתח \u0003תרתי איסרי\u0004 \u0005[שני קשרים],\u0006 ומכיון שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006"],["\u0003חדא מינייהו בטולי מבטיל\u0004 \u0005[אחד מהם\u0006 מן הקשרים \u0005בטל\u0006 משימוש\u0005]\u0006 ויוציא את הבהמה בדוחק רק אחרי התרת קשר אחד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ששניהם נחשבים כקשר שאינו של קיימא, ומותר. \u0003אמר רב יוסף\u0004 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: הלכה\u0004 בענין זה \u0003כ\u0004שיטת \u0003ר' אליעזר בן יעקב. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: מאחר שפוסק אתה שכך \u0003הלכה,\u0004 אם כן \u0003מכלל\u0004 הדברים ניתן להבין \u0003דפליגי\u0004 \u0005[שנחלקו]\u0006 עליו חכמים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לך מינה\u0004 \u0005[ממנה,\u0006 מזה\u0005]?\u0006 הרי בין שנחלקו ובין שלא נחלקו הלכה כמותו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: וכי תנהג כך ש\u0003גמרא גמור זמורתא\u0004 \u0005[\u0006ש\u0005תלמד למודך\u0006 ו\u0005זמר]\u0006 \u0003תהא\u0004 בחזרה על דברים בלא לחקור את יסודותיהם?!","\u0003קושרין\u0004 בשבת \u0003דלי בפסקיא\u0004 (חגורה) שבודאי לא ישאירנה קשורה בדלי ואין זה איפוא קשר של קיימא, \u0003אבל לא בחבל. ר' יהודה מתיר.\u0004 ו\u0003כלל אמר ר' יהודה: כל קשר שאינו של קיימא\u0004 — \u0003אין חייבין עליו.\u0004","שנינו במשנה שלדעת התנא קמא אסור לקשור בשבת דלי בחבל, ור' יהודה מתיר. ושואלים: \u0003חבל דמאי\u0004 \u0005[של מה]?\u0006 כלומר, באיזה חבל מדובר כאן? \u0003אי לימא\u0004 \u0005[אם תאמר]\u0006 שמדובר ב\u0003חבל דעלמא\u0004 \u0005[סתם],\u0006 כיצד \u0003ר' יהודה מתיר?\u0004 והלא \u0003קשר של קיימא הוא! אלא\u0004 יש לומר שמדובר לא בחבל סתם אלא ב\u0003חבל דגרדי\u0004 \u0005[של אורג],\u0006 שהאורג צריך לו למלאכתו ויתירנו לאחר השבת. ושואלים: \u0003למימרא דרבנן סברי גזרינן\u0004 \u0005[האם נאמר שחכמים סבורים\u0006 כי \u0005גוזרים אנו]\u0006 ב\u0003חבל דגרדי אטו\u0004 \u0005[של אורג משום]\u0006 \u0003חבל דעלמא\u0004 \u0005[סתם],\u0006 \u0003ור' יהודה סבר לא גזרינן\u0004 \u0005[סבור\u0006 כי \u0005איננו\u0006 \u0005גוזרים]?\u0006","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו בברייתא: \u0003חבל דלי שנפסק\u0004 בשבת \u0003— לא יהא קושרו\u0004 בקשר רגיל \u0003אלא עונבו. ור' יהודה אומר: כורך עליו פונדא\u0004 (איזור חלול) \u0003או פסקיא\u0004 (חגורה), \u0003ובלבד שלא יענבנו.\u0004","ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 עצמו, שבברייתא שנינו שהוא גוזר על עניבה משום קשירה, ובמשנה אינו גוזר בקשירת חבלים וכן \u0003קשיא דרבנן אדרבנן\u0004 \u0005[קשה מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים],\u0006 שבברייתא אינם גוזרים ובמשנה שנינו שהם גוזרים גזירה.","ומתרצים: \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים אינו קשה],\u0006 וטעם ההבדל: \u0003חבל בחבל\u0004 — \u0003מיחלף\u0004 \u0005[מתחלף],\u0006 וכיון שדומים הם — גזרו גם בחבל גרדי, שאם נתיר בו יבואו לטעות ולהורות היתר גם בחבל רגיל. אבל \u0003עניבה בקשירה\u0004 — \u0003לא מיחלפא\u0004 \u0005[אינה מתחלפת]\u0006 ולכן לא גזרו איסור בעניבה. וכן מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[אינו קשה],\u0006 שכן יש לחלק ולומר כי \u0003התם\u0004 \u0005[שם]\u0006 שאסר — הרי זה \u0003לא משום דמיחלפא\u0004 \u0005[שמתחלפת]\u0006 \u0003עניבה בקשירה, אלא\u0004 לדעתו \u0003עניבה גופה קשירה\u0004 גמורה \u0003היא\u0004 ואסורה מעיקר הדין, ולא משום גזירה.","\u0003אמר ר' אבא\u0004 שכך \u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: מביא אדם\u0004 בשבת \u0003חבל מתוך ביתו, וקושרו\u0004 בקצה אחד \u0003בפרה ו\u0004בקצה אחר \u0003באבוס,\u0004 ואין זה נחשב כקשר של קיימא, שכן ודאי יתיר את החבל. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אחא אריכא\u0004 \u0005[הארוך,\u0006 הגבוה\u0005]\u0006 ש\u0003הוא ר' אחא בר פפא לר' אבא,\u0004 והלא שנינו במפורש בברייתא: \u0003חבל שבאיבוס\u0004 — \u0003קושרו בפרה, ושבפרה\u0004 — \u0003קושרו באיבוס, ובלבד שלא יביא חבל מתוך ביתו ויקשור בפרה ובאיבוס!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 שהתירו — מדובר ב\u0003חבל דגרדי\u0004 \u0005[של אורג]\u0006 שודאי יתירנו.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: כלי קיואי\u0004 (אורג) \u0003מותר לטלטלן בשבת. בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב יהודה: כובד העליון וכובד התחתון\u0004 שבנול האורגים \u0003מהו\u0004 דינם, האם גם הם בכלל היתר זה? ולא השיב תשובה ברורה אלא \u0003אין ולאו ורפיא בידיה\u0004 \u0005[כן ולא ורפה\u0006 התשובה \u0005בידו].\u0006 ואולם \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003אמר רב נחמן\u0004 שכך \u0003אמר שמואל: כלי קיואי מותר לטלטלן בשבת,\u0004 ו\u0003אפילו\u0004 את ה\u0003כובד העליון וכובד התחתון, אבל לא את העמודים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי שנא\u0004 \u0005[מה שונים]\u0006 ה\u0003עמודים\u0004 ש\u0003לא\u0004 יטלטלם? \u0003אילימא דקעביד\u0004 \u0005[אם נאמר\u0006 משום \u0005ש\u0006הוא \u0005עושה]\u0006 \u0003גומות\u0004 כשהוא חולץ את העמוד מן הקרקע, הלא \u0003גומות ממילא קא הויין\u0004 \u0005[מעצמן הן נעשות]\u0006 ובדבר זה אין איסור, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הטומן לפת וצנונות תחת הגפן, אם מקצת עליו\u0004 של הירק הטמון \u0003מגולין\u0004 — \u0003אינו חושש לא משום כלאים\u0004 של ירק בגפן, \u0003ולא משום שביעית,\u0004 שאסור לזרוע בשנה זו, \u0003ולא משום מעשר\u0004 שיצטרך לחזור ולעשר את הירקות לאחר הוצאתן שנית, לפי שטמינה מעין זו אינה נחשבת כזריעה, \u0003ו\u0004כן \u0003ניטלין בשבת.\u0004 נמצא אם כן שאין אוסרים בכך משום עשיית גומא!","וענה לו: אין להשוות בין המקרים, שכן \u0003בשדה\u0004 — \u0003לא אתי לאשוויי\u0004 \u0005[יבוא להשוות,\u0006 ליישר\u0005]\u0006 \u0003גומות,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 שהגומות נעשות \u0003בבית\u0004 — יש לחשוש שמא \u0003אתי לאשוויי\u0004 \u0005[יבוא להשוות,\u0006 ליישר\u0005]\u0006 את ה\u0003גומות,\u0004 ומשום כך אסרו. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' יוחנן מר' יהודה בר ליואי: כלי קיואי, כגון כובד העליון וכובד התחתון, מהו\u0004 הדין לענין ההיתר \u0003לטלטלן בשבת? אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה: \u0003אין מטלטלין.\u0004 ושאלו: \u0003מה טעם\u0004 הדבר? אמר לו: \u0003לפי שאין ניטלין\u0004 אף בחול, שהם כבדים ביותר וקבועים ובטלים למקומם, ולכן לא התירו את טלטולם בשבת.","\u0003מקפלין את הכלים\u0004 (הבגדים) לאחר שהפשיטום \u0003אפילו ארבעה ו\u0004כן \u0003חמשה פעמים, ומציעין את המטות מלילי שבת לשבת. אבל לא משבת למוצאי שבת,\u0004 שאין עושים בשבת כל מעשה שהוא הכנה לצורך יום חול. \u0003ר' ישמעאל אומר: מקפלין את הכלים, ומציעין את המטות מיום הכיפורים לשבת\u0004 אם חל יום הכיפורים ביום שישי. \u0003וחלבי\u0004 הקרבנות שהוקרבו ב\u0003שבת קריבין ביום הכיפורים, אבל לא של יום הכיפורים בשבת\u0004 שקדושת שבת גדולה מקדושת יום הכפורים. ואילו \u0003ר' עקיבא אומר: לא של שבת קריבין ביום הכיפורים, ולא של יום הכיפורים קריבין בשבת.\u0004","\u0003אמרי דבי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: לא שנו\u0004 שמותר לקפל בשבת את הבגדים \u0003אלא באדם אחד, אבל בשני בני אדם\u0004 — \u0003לא,\u0004 ששניים המקפלים הריהם כמתקנים את הכלי בקיפולם. \u0003ובאדם אחד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שמותר \u0003אלא ב\u0004בגדים \u0003חדשים,\u0004 שאף בלי קיפול ראויים הם ללבישה, \u0003אבל בישנים\u0004 — \u0003לא\u0004 יקפל. \u0003וחדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[שמותר]\u0006 לקפלם \u0003אלא בלבנים, אבל בצבועים\u0004 — \u0003לא. ולא אמרן\u0004 \u0005[אמרנו]\u0006 שמותר לו לקפל \u0003בשבת בגדים לבנים חדשים אלא\u0004 כ\u0003שאין לו\u0004 בגדים \u0003להחליף, אבל\u0004 אם \u0003יש לו\u0004 בגדים אחרים \u0003להחליף\u0004 — \u0003לא\u0004 יקפל את אלו.","ובתוספתא \u0003תנא\u0004 \u0005[שנינו]:\u0006 בני הבית \u0003של בית רבן גמליאל לא היו מקפלים\u0004 אפילו \u0003כלי לבן שלהן, מפני שהיה להן\u0004 אחרים \u0003להחליף.\u0004 אגב דברים אלה הביאו מה ש\u0003אמר רב הונא: אם יש לו להחליף\u0004 בגדים חדשים בשבת — \u0003יחליף, ואם אין לו להחליף\u0004 — \u0003ישלשל\u0004 (יאריך) \u0003בבגדיו\u0004 לפני השבת, כדי שיתהדר לכבוד שבת. \u0003מתקיף לה\u0004 \u0005[הקשה על כך]\u0006 \u0003רב ספרא: והא מיתחזי כרמות רוחא\u0004 \u0005[והרי נראה\u0006 בכך \u0005כגסות הרוח].\u0006 ומשיבים: \u0003כיון\u0004 שב\u0003כל יומא\u0004 \u0005[יום]\u0006 הוא \u0003לא קעביד\u0004 \u0005[עושה]\u0006 כך, \u0003והאידנא\u0004 \u0005[ועכשיו],\u0006 בשבת \u0003הוא דקא עביד\u0004 \u0005[שעושה]\u0006 כך — \u0003לא מיתחזי כרמות רוחא\u0004 \u0005[נראה\u0006 הדבר \u0005כגסות הרוח]\u0006 אלא ככבוד השבת.","ובענין זה מביאים ממה ששנינו, נאמר: \"אם תשיב משבת רגליך עשות חפצך ביום קדשי וקראת לשבת עונג לקדוש ה' מכובד \u0003וכבדתו מעשות דרכיך\u0004 ממצוא חפצך ודבר דבר\" (ישעיהו נח, יג) ודרשו בדברים \u0003\"וכבדתו\"\u0004 — \u0003שלא יהא מלבושך של שבת כמלבושך של חול. וכי הא\u0004 \u0005[וכמו זה]\u0006 ש\u0003ר' יוחנן קרי למאניה \"מכבדותי\"\u0004 \u0005[\u0006היה \u0005קורא לבגדיו \"כבודי\"],\u0006 ונמצא שיש דרך כבוד בלבוש מתאים. והמשך \u0003הפסוק \"מעשות דרכיך\"\u0004 משמעו — \u0003שלא יהא הילוכך של שבת כהילוכך של חול. \"ממצוא חפצך\"\u0004 — \u0003חפציך\u0004 (ענייניך) שלך \u0003אסורין\u0004 להתעסק ולדבר בהם בשבת, ואולם \u0003חפצי שמים\u0004 (של מצוה) — \u0003מותרין. \"ודבר דבר\"\u0004 —"],["\u0003שלא יהא דבורך של שבת כדבורך של חול,\u0004 שלא ידבר בענייני עסקיו. ואולם רק ב\u0003דבור\u0004 אמרו ש\u0003אסור,\u0004 אולם \u0003הרהור\u0004 — \u0003מותר.\u0004 ואומרים: \u0003בשלמא כולהו\u0004 \u0005[נניח\u0006 ל\u0005כולם]\u0006 — \u0003לחיי\u0004 \u0005[בסדר],\u0006 ומובנים הם, ואולם \u0003\"שלא יהא הילוכך של שבת כהילוכך של חול\" מאי היא\u0004 \u0005[מה הוא]\u0006 \"הילוך של חול\"? ומשיבים: \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב הונא\u0004 שכך \u0003אמר רב, ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אבא\u0004 שכך \u0003אמר רב הונא: היה מהלך בשבת ופגע\u0004 (נפגש) \u0003באמת המים\u0004 וצריך לעוברה, \u0003אם\u0004 צרה היא התעלה ו\u0003יכול להניח את רגלו\u0004 ה\u0003ראשונה\u0004 מעבר לתעלה \u0003קודם שתעקר\u0004 ה\u0003שניה\u0004 ממקומה — \u0003מותר, ואם לאו\u0004 \u0005[לא],\u0006 שצריך לקפוץ — \u0003אסור.\u0004 והוא הילוך שאינו של שבת.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא:\u0004 אחר שאמרנו שלא יהא הילוכך של שבת כהילוכך של חול, וזהו הילוך של חול, אם כן הפוגע באמת מים בשבת \u0003היכי ליעביד\u0004 \u0005[כיצד יעשה]\u0006 לעבור לצד השני אם לא יקפוץ? אם \u0003ליקף\u0004 \u0005[יקיף]\u0006 את התעלה — \u0003קמפיש בהילוכא\u0004 \u0005[הריהו מרבה בהילוך],\u0006 וטורח טירחה יתירה בשבת. ואם \u0003ליעבר\u0004 \u0005[יעבור]\u0006 בתעלה — \u0003זימנין דמיתווסן מאני מיא, ואתי\u0004 \u0005[פעמים שנספגים בגדיו מים, ויבוא]\u0006 \u0003לידי סחיטה.\u0004 ואם כן מה יעשה? \u0003אלא, בהא\u0004 \u0005[ב\u0006מקרה \u0005זה]\u0006 \u0003כיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעבור באופן אחר — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר\u0005].\u0006 \u0003אלא\u0004 יש לומר כי הילוך של חול הוא בפסיעה גסה. \u0003כדבעא מיניה\u0004 \u0005[כפי ששאל ממנו]\u0006 \u0003רבי מר' ישמעאל בר' יוסי: מהו\u0004 הדין לענין \u0003לפסוע פסיעה גסה\u0004 (פסיעות גדולות) \u0003בשבת?\u0004 ולזה נתכוונו כשאמרו \"הילוכך של חול\". \u0003אמר לו\u0004 ר' ישמעאל: \u0003וכי ב\u0004ימות ה\u0003חול מי\u0004 \u0005[האם]\u0006 \u0003הותרה\u0004 פסיעה גסה? \u0003שאני אומר: פסיעה גסה נוטלת אחד מחמש מאות ממאור עיניו של אדם.\u0004 ומעירים: \u0003ומהדר ליה בקידושא דבי שמשי\u0004 \u0005[ומוחזרת לו\u0006 ראיית העינים \u0005בקידוש ליל שבת].\u0006","ועוד \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבי מר' ישמעאל בר' יוסי: מהו\u0004 הדין לענין \u0003לאכול אדמה\u0004 כרפואה \u0003בשבת? אמר ליה\u0004 \u0005[לו]\u0006 ר' ישמעאל: \u0003וכי ב\u0004ימות ה\u0003חול מי\u0004 \u0005האם\u0006 \u0003הותרה\u0004 אכילת אדמה? \u0003שאני אומר: אף בחול אסור, מפני שהוא מלקה\u0004 (מזיק). \u0003אמר ר' אמי: כל האוכל מעפרה של בבל\u0004 — \u0003כאילו אוכל מבשר אבותיו\u0004 שנקברו באדמתה. \u0003ויש אומרים: כאילו אוכל שקצים ורמשים, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003\"וימח את כל היקום\u0004 אשר על פני האדמה מאדם עד בהמה עד רמש ועד עוף השמים ויימחו מן הארץ\u0003\"\u0004 (בראשית ז, כג), ונבלות הרמשים עדיין על אדמתה.","וכפי ש\u0003אמר ריש לקיש: למה נקרא שמה\u0004 של בבל \u0003\"שנער\"\u0004 — לפי \u0003שכל מתי\u0004 ה\u0003מבול ננערו לשם.\u0004 ו\u0003אמר ר' יוחנן: למה נקרא שמה\u0004 של בבל \u0003\"מצולה\"\u0004 — \u0003שכל מתי\u0004 ה\u0003מבול נצטללו לשם.\u0004 ושואלים: אמרנו ש\u0003יש אומרים\u0004 שהאוכל מעפרה של בבל הריהו \u0003כאילו אוכל שקצים ורמשים, והא\u0004 \u0005[והרי]\u0006 \u0003ודאי איתמחויי איתמחו\u0004 \u0005[והרי ודאי\u0006 נרקבו \u0005ונמחו],\u0006 וכיון שנמחו שוב אין בהם משום איסור! אלא, \u0003כיון דמלקי\u0004 \u0005[ש\u0006האדמה \u0005מזיקה]\u0006 \u0003גזרו ביה רבנן\u0004 \u0005[בה חכמים]\u0006 שלא יאכלוה, ולא משום איסור שקצים. \u0003דהא ההוא גברא\u0004 \u0005[שהרי\u0006 ראינו מעשה ב\u0005אדם אחד]\u0006 ש\u0003אכל גרגישתא\u0004 \u0005[אדמה]\u0006 לרפואה, \u0003ואכל\u0004 גם \u0003תחלי\u0004 \u0005[שחליים],\u0006 ונקלטו השחליים באדמה שבמעיו והחלו לצמוח, \u0003וקדחו ליה תחליה בלביה, ומית\u0004 \u0005[ונקבו לו השחליים בלבו, ומת].\u0006","ועוד לענין שבת: יעצה נעמי לרות \u0003\"ורחצת וסכת ושמת שמלתיך\u0004 עליך וירדת הגורן אל תודעי לאיש עד כלותו לאכול ולשתות\u0003\"\u0004 (רות ג, ג), \u0003אמר ר' אלעזר: אלו בגדים של שבת\u0004 שאמרה לה ללבוש לכבוד המאורע. וכיון שהוזכר ענין זה מביאים עוד מדברי ר' אלעזר שדרש על מה שנאמר \u0003\"תן לחכם ויחכם עוד\u0004 הודע לצדיק ויוסף לקח\u0003\"\u0004 (משלי ט, ט). \u0003אמר ר' אלעזר: זו רות המואביה ושמואל הרמתי\u0004 שקיבלו עצה והוסיפו עליה בחכמה.","ומפרטים: \u0003רות, דאילו\u0004 (שכן) \u0003נעמי קאמרה\u0004 \u0005[אמרה]\u0006 \u0003לה \"ורחצת וסכת ושמת שמלתיך עליך וירדת הגרן\", ואילו בדידה כתיב\u0004 \u0005[בה\u0006 ברות עצמה \u0005נאמר\u0006\u0005]:\u0006 \u0003\"ותרד הגרן\"\u0004 (רות ג, ו) \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"ותעש ככל אשר צותה חמותה\",\u0004 שהחליטה לסוך בגורן ולא ברחוב, שלא יפגשו בה אנשים בדרכה ויחשדו בה. וב\u0003שמואל, דאילו עלי קאמר ליה\u0004 \u0005[אמר לו]\u0006 \u0003\"\u0004ויאמר עלי לשמואל לך \u0003שכב והיה אם יקרא אליך ואמרת דבר ה' כי שמע עבדך\"\u0004 (שמואל א' ג, ט) \u0003ואילו בדידיה כתיב ביה\u0004 \u0005[בו\u0006 עצמו \u0005נאמר בו]:\u0006 \u0003\"ויבא ה' ויתיצב ויקרא כפעם בפעם שמואל שמואל ויאמר שמואל דבר כי שמע עבדך\"\u0004 (שמואל א' ג, י), \u0003ולא\u0004 הוסיף ו\u0003אמר \"דבר ה'\"\u0004לפי שנזהר להניח שה' מדבר עמו עד שידע בבירור דבר זה.","כיון שהוזכר עניינה של רות מביאים עוד מדרשי כתובים במגילת רות. נאמר: \u0003\"ותלך ותבא ותלקט בשדה\u0004 אחרי הקוצרים\u0003\"\u0004 (רות ב, ג) \u0003אמר ר' אלעזר:\u0004 פסוק זה מלמד \u0003שהלכה ובאת\u0004 (באה), \u0003הלכה ובאת, עד שמצאה בני אדם המהוגנין לילך עמהם.\u0004 נאמר עוד: \u0003\"ויאמר בעז לנערו הנצב על הקוצרים למי הנערה הזאת\"\u0004 (רות ב, ה). והדבר תמוה: \u0003וכי דרכו של בעז לשאול בנערה? אמר ר' אלעזר: דבר חכמה\u0004 ותורה \u0003ראה בה,\u0004 ומשום כך שאל עליה. שכן \u0003שני שבלין\u0004 — \u0003לקטה, שלשה שבלין\u0004 — \u0003אינה\u0004 (לא) \u0003לקטה,\u0004 שנהגה כהלכה, ששלוש שבלים המונחות כאחת אין דינן כלקט, והן שייכות לבעל השדה.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]:\u0006 \u0003דבר צניעות ראה בה\u0004 בזמן הלקיטה, שראה שהיא לוקטת שבלים \u0003עומדות\u0004 — ב\u0003מעומד,\u0004 ושבלים \u0003נופלות\u0004 — ב\u0003מיושב,\u0004 ואינה מתכופפת לקחתן משום צניעות. עוד נאמר: \u0003\"\u0004ויאמר בועז אל רות הלא שמעת בתי אל תלכי ללקוט בשדה אחר וגם לא תעבורי מזה \u0003וכה תדבקין עם נערתי\"\u0004 (רות ב, ח). ואף זה תמוה: \u0003וכי דרכו של בעז לדבק עם הנשים? אמר ר' אלעזר: כיון דחזא\u0004 \u0005[שראה]\u0006 \u0003\"ותשק ערפה לחמותה ורות דבקה בה\"\u0004 (רות א, יד) \u0003אמר:\u0004 אשה כזאת \u0003שרי לאידבוקי\u0004 \u0005[מותר לדבוק]\u0006 \u0003בה.\u0004","עוד נאמר: \u0003\"ויאמר לה בעז לעת האכל גשי הלם\u0004 ואכלת מן הלחם וטבלת פתך בחומץ ותשב מצד הקוצרים ויצבוט לה קלי ותאכל ותשבע ותותר\u0003\"\u0004 (רות ב, יד). ופירש ו\u0003אמר ר' אלעזר: רמז רמז לה,\u0004 שכיון בדבריו לדבר נבואה: \u0003עתידה מלכות בית דוד לצאת ממך, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בו: \u0003\"הלם\", שנאמר: \"ויבא המלך דוד וישב לפני ה' ויאמר מי אנכי אדני אלהים ומי ביתי כי הבאתני עד הלם\"\u0004 (שמואל ב' ז, יח). על מה שנאמר \u0003\"וטבלת פתך בחמץ\"\u0004 (רות ב, יד) \u0003אמר ר' אלעזר: מכאן שהחמץ יפה לשרב.\u0004","\u0003ר' שמואל בר נחמני אמר:\u0004 בדבריו \u0003רמז רמז לה\u0004 ש\u0003עתיד בן לצאת ממך שמעשיו קשין כחומץ, ומנו\u0004 \u0005[ומי הוא]\u0006 — המלך \u0003מנשה. \"ותשב מצד הקצרים\"\u0004 — \u0003אמר ר' אלעזר: מצד הקוצרים ולא בתוך הקוצרים, רמז רמז לה שעתידה מלכות בית דוד שתתחלק\u0004 ולא יהיו בניה תמיד במרכז כל ישראל. עוד נאמר שם: \"ויצבט לה קלי ותאכל ותשבע ותותר\".","ומפרשים: \u0003\"ויצבט לה קלי ותאכל\"\u0004 — אף הוא נתפרש כדבר נבואה. \u0003אמר ר' אלעזר: \"ותאכל\"\u0004 — נתקיים בבני בניה \u0003בימי דוד, \"ותשבע\"\u0004 — \u0003בימי שלמה, \"ותתר\"\u0004 — \u0003בימי חזקיה. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 פירוש אחר: \u0003\"ותאכל\"\u0004 — \u0003בימי דוד ובימי שלמה, \"ותשבע\"\u0004 — \u0003בימי חזקיה, \"ותתר\"\u0004 — \u0003בימי רבי.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אהוריריה\u0004 \u0005[שומר הסוסים]\u0006 של \u0003רבי הוה עתיר\u0004 \u0005[היה עשיר]\u0006 יותר \u0003משבור מלכא\u0004 \u0005[מלך\u0006 פרס\u0005].\u0006 \u0003במתניתא תנא\u0004 \u0005[בברייתא שנו]\u0006 \u0003\"ותאכל\"\u0004 — \u0003בעולם הזה, \"ותשבע\"\u0004 — \u0003לימות המשיח, \"ותתר\"\u0004 — \u0003לעתיד לבא.\u0004","הוזכר קודם שר' יוחנן היה קורא לבגדיו \"כבוד\". ומביאים את מה שפירשו את הכתוב המדבר במפלת מלך אשור: \u0003\"\u0004לכן ישלח האדון ה' צבאות במשמניו רזון \u0003ותחת כבדו יקד יקד כיקוד אש\"\u0004 (ישעיה י, טז). \u0003אמר ר' יוחנן \"ותחת כבדו\", ו\u0004אולם \u0003לא כבדו ממש.\u0004 ומפרשים: \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שהוא \u0003קרי למאניה \"מכבדותי\"\u0004 \u0005[\u0006היה \u0005קורא לבגדיו \"מכבדי\"],\u0006 והכוונה אם כן שנשרף גופם של חילות מלך אשור, אבל בדרך נס לא נשרפו בגדיהם.","\u0003ר' אלעזר אומר: \"ותחת כבדו\"\u0004 משמעו — \u0003תחת כבודו ממש.\u0004 כלומר, שנשרף גופם ממש, שלדעתו \"תחת\" משמעו — במקום, כלומר, במקום כבודו שהוא הגוף תהיה כלייה מוחלטת, שתהא שם שריפה אשר תכלהו. \u0003ר' שמואל בר נחמני אמר: \"תחת כבדו\"\u0004 משמעו — תחת בשרו, והיא שריפה \u0003כשריפת בני אהרן. מה להלן\u0004 בשריפת בני אהרן היתה זו \u0003שריפת נשמה ו\u0004ה\u0003גוף\u0004 נותר \u0003קיים, אף כאן שריפת נשמה וגוף קיים.\u0004","\u0003אמר ר' אחא בר אבא\u0004 שכך \u0003אמר ר' יוחנן:\u0004"],["\u0003מניין לשנוי בגדים,\u0004 שנחשב לדרך כבוד, \u0003מן התורה, ש\u0004כן \u0003נאמר: \"ופשט את בגדיו ולבש בגדים אחרים\u0004 והוציא את הדשן אל מחוץ למחנה אל מקום טהור\u0003\"\u0004 (ויקרא ו, ד). \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, לימדך תורה דרך ארץ: בגדים שבישל בהן קדירה לרבו,\u0004 מאחר ובישול היא עבודה המביאה ללכלוך בגדים — \u0003אל ימזוג בהן כוס לרבו\u0004 כשהוא משמשו שימוש של כבוד.","\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: גנאי הוא לתלמיד חכם שיצא במנעלים המטולאים לשוק.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אחא בר חנינא נפיק\u0004 \u0005[יצא]\u0006 במנעלים מטולאים! \u0003אמר ר' אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן:\u0004 אסרו רק בנעליים המטולאות \u0003בטלאי על גב טלאי.\u0004","\u0003ואמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: כל תלמיד חכם שנמצא רבב\u0004 (כתם שומן) \u0003על בגדו\u0004 — נחשב כ\u0003חייב מיתה, ש\u0004כן \u0003נאמר: \"כל משנאי אהבו מות\"\u0004 (משלי ח, לו), ואמרו חכמים: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003משנאי אלא \"משניאי\",\u0004 כלומר, אלה הגורמים להשניא את התורה על הבריות הרי זה כאילו \"אהבו מות\" — שחייבים מיתה. \u0003רבינא אמר:\u0004 לא רבב נאמר אלא \u0003רבד\u0004 (כתם דם) (ר\"ח) \u0003איתמר\u0004 \u0005[נאמר],\u0006 שיש בכך גנאי גדול יותר. ומוסיפים: \u0003ולא פליגי\u0004 \u0005[נחלקו]\u0006 להלכה, אלא \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שצריך להזהר בכל כתם — הרי זה \u0003בגלימא,\u0004 שהיא בגד עליון, ו\u0003הא\u0004 \u0005[זה]\u0006 ששנינו שיש להזהר בכתם דם — הרי זה \u0003בלבושא\u0004 \u0005[בלבוש\u0006 תחתון\u0005],\u0006 שיש להיזהר בכתם דם, שיש בו גנאי אבל בשאר כתמים אין להקפיד בו כל כך.","\u0003ו\u0004מעין זה \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כאשר הלך עבדי ישעיהו ערום ויחף\u0004 שלוש שנים\u0003\"\u0004 (ישעיהו כ, ג), שאין לפרש כמשמעו, אלא \u0003\"ערום\"\u0004 — שלבש \u0003בגדים בלואים, \"ויחף\"\u0004 — \u0003במנעלים המטולאים.\u0004","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003רבב\u0004 של שומן \u0003על המרדע\u0004 של חמור \u0003— חוצץ,\u0004 ואם הוא טמא — אין הטבילה מועילה לו עד שיוסר הרבב. \u0003רבן שמעון בן גמליאל אומר:\u0004 רבב חוצץ דווקא כשגודלו מגיע \u0003עד\u0004 כגודל \u0003איסר האיטלקי\u0004 ולא בפחות מזה. \u0003ועל הבגדים,\u0004 אם היה בהם כתם שומן \u0003מצד אחד\u0004 — \u0003אינו חוצץ,\u0004 אבל אם היה הרבב גדול עד שעבר הכתם \u0003משני צדדין\u0004 — \u0003חוצץ. ר' יהודה אומר משום\u0004 (בשם) \u0003ר' ישמעאל: אף מצד אחד חוצץ.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' שמעון בן לקיש מר' חנינא:\u0004 רבב שעל \u0003מרדעת,\u0004 האם \u0003מצד אחד\u0004 אמרו שהרבב חוצץ בו \u0003או משני צדדין? אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003זו\u0004 במפורש \u0003לא שמעתי,\u0004 ואולם \u0003כיוצא בה שמעתי. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 באותה משנה ש\u0003ר' יוסי אומר:\u0004 בגד \u0003של בנאין\u0004 — יש בו חציצה כשהכתם \u0003מצד אחד, ושל בור\u0004 (עם הארץ) שאינו מקפיד בנקיונו — כשהכתם \u0003משני\u0004 ה\u0003צדדין. ו\u0004בודאי \u0003לא תהא מרדעת\u0004 של חמור \u0003חשובה מבגדו של עם הארץ.\u0004","ומעירים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"בנאין\"\u0004 המוזכרים כאן? \u0003אמר ר' יוחנן: אלו תלמידי חכמים שעוסקין בבנינו של עולם כל ימיהן. ו\u0004בהקשר לכך \u0003אמר ר' יוחנן: איזהו תלמיד חכם\u0004 שאמרו \u0003שמחזירין לו אבידה בטביעות העין,\u0004 כלומר, שאם אמר שהוא מכיר במציאה שהיא שלו שמחזירים לו את החפץ גם אם אין בו סימנים — \u0003זה המקפיד על חלוקו\u0004 (בגדו הפנימי) \u0003להופכו,\u0004 כדי שלא ייראו התפירות הגסות, שנוהג בכל דרכיו כתלמיד חכם אף בהקפדה על נקיון וסדר (מהרש\"א). \u0003ו\u0004אגב כך מוסיפים מה ש\u0003אמר ר' יוחנן: איזהו תלמיד חכם שממנין אותו פרנס על הציבור\u0004 — \u0003זה ששואלין אותו דבר הלכה בכל מקום ואומר,\u0004 ובקיאות זו שאמרו — בכל המסכתות, \u0003ואפילו במסכת כלה\u0004 שהיא המסכת הנלמדת ברבים באותה עת, ואין אנשים רגילים בה.","\u0003ואמר ר' יוחנן: איזהו תלמיד חכם שבני עירו מצווין לעשות לו מלאכתו\u0004 — \u0003זה שמניח חפצו ועוסק בחפצי שמים,\u0004 וראוי לציבור לסייע בידו. \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא לענין \u0003למיטרח בריפתיה\u0004 \u0005[לטרוח\u0006 ולעסוק \u0005בלחמו],\u0006 שראוי לסייע לו בצרכיו החיוניים. \u0003ואמר ר' יוחנן: איזהו\u0004 הנכלל בגדר \u0003\"תלמיד חכם\"\u0004 — \u0003כל ששואלין אותו הלכה בכל מקום, ואומרה.\u0004 ואומרים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006 למעשה\u0005]\u0006 — \u0003למנוייה\u0004 \u0005[ל\u0006ענין \u0005מינויו]\u0006 כ\u0003פרנס על הציבור; אי בחדא מסכתא\u0004 \u0005[אם\u0006 בקי כך \u0005במסכת אחת]\u0006 — ימנוהו \u0003באתריה\u0004 \u0005[במקומו],\u0006 \u0003אי בכוליה תנויה\u0004 \u0005[אם בכל לימודו]\u0006 — יעמידוהו \u0003בריש מתיבתא\u0004 \u0005[בראש הישיבה].\u0006","\u0003ר' שמעון בן לקיש אמר:\u0004 בגדי הבנאים האמורים במשנה \u0003אלו\u0004 הם \u0003כלים\u0004 (בגדים) \u0003האוליירין\u0004 (של בלנים) \u0003הבאין ממדינת הים,\u0004 שהכתם בהם ניכר, ומקפידים בנקיונם. ושואלים: \u0003למימרא דחיורי נינהו\u0004 \u0005[האם נאמר ש\u0006אלה \u0005לבנים הם]?\u0006 \u0003והאמר להו\u0004 \u0005[והרי אמר להם]\u0006 \u0003ר' ינאי לבניו: בני, אל תקברוני לא בכלים לבנים ולא בכלים שחורים,\u0004 לא ב\u0003לבנים\u0004 — \u0003שמא לא אזכה\u0004 בדיני \u0003ואהיה\u0004 בין הרשעים (הנידונים) \u0003כחתן בין אבלים.\u0004 ולא בבגדים \u0003שחורים\u0004 — \u0003שמא אזכה\u0004 ואהיה בין הצדיקים, \u0003ו\u0004אם אלבש שחורים \u0003אהיה כאבל בין חתנים. אלא\u0004 קברוני \u0003בכלים האוליירין הבאין ממדינת הים,\u0004 שאינם שחורים ואינם לבנים. \u0003אלמא, סומקי נינהו\u0004 \u0005[מכאן שאדומות הם\u0006 בגדים אלה\u0005]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 שניתן לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 שמשמע מדברי ר' ינאי שהם אדומים — הרי זה \u0003בגלימי\u0004 \u0005[בגלימות],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שמשמע מדברי ר' שמעון בן לקיש שהם לבנים — הרי זה \u0003בלבושי\u0004 \u0005[בלבוש\u0006 תחתון\u0005].\u0006","שנינו במשנה ש\u0003ר' ישמעאל אומר\u0004 ש\u0003מקפלין\u0004 את הכלים ומציעים את המיטות מיום כיפורים לשבת, ומקריבים ביום הכיפורים שחל ביום ראשון חלבים שנשארו מן הקרבנות שהוקרבו בשבת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: במה שנאמר \u0003\"עלת שבת בשבתו\u0004 על עולת התמיד ונסכה\u0003\"\u0004 (במדבר כח, י) \u0003לימד\u0004 הכתוב \u0003על חלבי שבת שקריבין ביום הכיפורים\u0004 שאף הוא נקרא \"שבת\", ודרש כאילו נכתב עולת שבת — בשבת אחרת. \u0003יכול אף\u0004 חלבים \u0003של יום הכיפורים\u0004 יהיו קרבים \u0003בשבת\u0004 — \u0003תלמוד לומר: \"בשבתו\",\u0004 למעט: ולא בשבת אחרת, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר:\u0004 במה שנאמר \u0003\"עלת שבת בשבתו\" לימד\u0004 הכתוב \u0003על חלבי שבת שקרבים ביום טוב\u0004 שלמחרתו. \u0003יכול אף\u0004 יהיו קרבים \u0003ביום הכפורים\u0004 שחל למחרת השבת — \u0003תלמוד לומר: \"בשבתו\"\u0004 — ולא באחרת.","\u0003כשתמצא לומר\u0004 ותדקדק בשיטות, הרי \u0003לדברי ר' ישמעאל נדרים ונדבות קריבין ביום טוב,\u0004 ועל סמך הנחה זו הוא אומר שאם נדרים שיכולים לדחות את הקרבתם לימות החול, קרבים בכל זאת ביום טוב, ודאי שיקריבו חלבי שבת ביום טוב שלמחרתו, \u0003וכי איצטריך קרא\u0004 \u0005[וכאשר נצרך המקרא]\u0006 לרבות — הרי זה \u0003ל\u0004התיר הקרבת חלבים של שבת ב\u0003יום הכפורים\u0004 למחרתו. ואילו \u0003לדברי ר' עקיבא נדרים ונדבות אין קרבין ביום טוב, ו\u0004לכן \u0003כי איצטריך קרא\u0004 \u0005[כאשר נצרך הכתוב]\u0006 הרי זה \u0003למישרא\u0004 \u0005[להתיר]\u0006 את הקרבת חלבי שבת \u0003ביום טוב\u0004 שלמחרתו, אבל ביום הכיפורים — אסור. \u0003אמר ר' זירא:\u0004"],["\u0003כי הוינא\u0004 \u0005[כאשר הייתי]\u0006 \u0003בבבל הוה אמרי\u0004 \u0005[אמרתי]:\u0006 \u0003הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]\u0006 בה ש\u0003יום הכפורים שחל להיות\u0004 ב\u0003ערב שבת\u0004 — \u0003לא היו תוקעין\u0004 בו כדרך שתוקעים בכל ערב שבת להודיע על כניסת השבת, \u0003ו\u0004אם חל יום הכפורים \u0003במוצאי שבת\u0004 — \u0003לא היו מבדילין\u0004 בין קדושת שבת ויום הכיפורים, ברייתא זו \u0003דברי הכל היא. כי סליקנא להתם, אשכחיתיה\u0004 \u0005[כאשר עליתי לשם,\u0006 לארץ ישראל \u0005מצאתי]\u0006 את \u0003יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי דיתיב וקאמר\u0004 \u0005[שיושב ואומר]:\u0006 ברייתא זו כשיטת \u0003ר' עקיבא היא,\u0004 שמשווה את קדושת יום הכפורים לקדושת שבת, \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר ששיטת \u0003ר' ישמעאל\u0004 היא, \u0003כיון\u0004 ש\u0003אמר\u0004 ר' ישמעאל ש\u0003חלבי שבת קריבין ביום הכיפורים,\u0004 אם כן \u0003ליתקע, כי היכי דליהוי ידעי\u0004 \u0005[שיתקע, כדי שיהיו יודעים]\u0006 הכהנים ש\u0003חלבי\u0004 יום ה\u0003שבת קריבין ביום הכיפורים\u0004 ומותר להם להתחיל להקריב אותם (רה\"ג). \u0003ואמינא ליה אנא\u0004 \u0005[ואמרתי אני לו]:\u0006 מכאן אין להביא ראיה כיון ש\u0003כהנים זריזין הן,\u0004 ואנו סומכים על כך שהם יודעים מעצמם, ואין צורך לתקוע עבורם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי: מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 לענין זה \u0003כהנים זריזין הן? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלש\u0004 תקיעות היו תוקעים במקדש בערב שבת כדי \u0003להבטיל את העם ממלאכה,\u0004 ו\u0003שלש\u0004 נוספות \u0003להבדיל בין קודש לחול.\u0004 הרי שאף הכהנים צריכים לתקיעות להודיע להם על כניסת ויציאת השבת! ומשיבים: \u0003כ\u0004שם ש\u0003אמר אביי\u0004 בענין אחר שעשו דברים \u0003לשאר עמא\u0004 \u0005[לשאר העם]\u0006 ש\u0003בירושלים,\u0004 ואם כן \u0003הכא נמי\u0004 \u0005[גם כאן]\u0006 בענין התקיעות כי עשו כן \u0003ל\u0004צורך \u0003שאר עמא\u0004 \u0005[העם]\u0006 ש\u0003בירושלים.\u0004","ושואלים: מכל מקום \u0003וליתקע, כי היכי דלידעי דשרי\u0004 \u0005[ושיתקעו, כדי שידעו שמותר]\u0006 \u0003בקניבת ירק\u0004 (הסרת ראשי העלים מן הירקות) \u0003מן המנחה ולמעלה\u0004 ביום הכיפורים. שהתירו ביום הכיפורים משעה מסויימת ואילך לקנוב את הירק עבור הסעודה שלאחר הצום, מה שאין כן בשבת שאסור לעשות כל מלאכה עבור ימי החול. \u0003אמר רב יוסף: לפי שאין דוחין שבות להתיר,\u0004 שאף שאין התקיעה מלאכה גמורה מכל מקום אסורה היא משום שבות בשבת וביום הכפורים, ואין דוחים שבות זו כדי להתיר דברים.","\u0003ורב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: שבות קרובה\u0004 כתקיעה להתיר במלאכה מיד — \u0003התירו, שבות רחוקה\u0004 כקניבת הירק שהותרה רק מן המנחה ולמעלה שעות רבות לאחר כניסת יום הכיפורים — \u0003לא התירו\u0004 (ר\"ח).","ושואלים: \u0003ו\u0004כי \u0003שבות קרובה התירו? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003יום טוב שחל להיות\u0004 ב\u0003ערב שבת\u0004 — \u0003תוקעין\u0004 להודיע שנכנסה השבת, \u0003ולא מבדילין\u0004 על היין, כיון שקדושת שבת יתירה על קדושת יום טוב. ואם חל יום טוב ב\u0003מוצאי שבת\u0004 — \u0003מבדילין\u0004 בין קדושת שבת וקדושת יום טוב \u0003ולא תוקעין. ואמאי\u0004 \u0005[ומדוע]\u0006 לא יתקעו? \u0003ליתקע, כי היכי דלידעי דשרי\u0004 \u0005[שיתקע\u0006 עם כניסת החג, \u0005כדי שידעו שמותר]\u0006 \u0003בשחיטה לאלתר\u0004 \u0005[מיד]\u0006 בחג, מה שלא הותר לעשות כן בשבת! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 שיש להסביר \u0003כ\u0004דרך שפירש \u0003רב יוסף\u0004 שאין דוחים שבות כדי להתיר בעשיית מלאכה.","כיון שהוזכר היתר קניבת ירק ביום הכיפורים, מביאים מה ש\u0003אמר ר' זירא\u0004 שכך \u0003אמר רב הונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אבא\u0004 שכך \u0003אמר רב הונא: יום הכפורים שחל להיות בשבת\u0004 — \u0003אסור בקניבת ירק. אמר רב מנא, תנא\u0004 \u0005[שנינו]\u0006 בברייתא: \u0003מנין ליום הכפורים שחל להיות בשבת שאסור בקניבת ירק\u0004 — \u0003תלמוד לומר: \"שבתון\u0004 שבת קודש לה'\u0003\"\u0004 (שמות טז, כג), ומשמעו שיש חובת \u0003שבות,\u0004 כלומר, לשבות ביום זה. ו\u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004עשיית \u0003מלאכה\u0004 ממש — \u0003והכתיב\u0004 \u0005[ו\u0006הלא כבר \u0005נאמר]\u0006 במפורש: \u0003\"\u0004ויום השביעי שבת לה' אלהיך \u0003לא תעשה כל מלאכה\"\u0004 (שמות כ, י)! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר הדבר לגבי \u0003קניבת ירק,\u0004 שאף היא שאינה מלאכה גמורה אסורה בשבת משום מצוות שבתון! ומסיימים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כדבריך.","ובניגוד לכך \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: יום הכפורים שחל להיות בשבת\u0004 — \u0003מותר בקניבת ירק. מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא שהובאה מקודם: \u0003מנין ליום הכפורים שחל להיות בשבת שאסור בקניבת ירק\u0004 — \u0003תלמוד לומר: \"שבתון\u0004 שבת קודש לה'\u0003\"\u0004 (שמות כ,י), ומשמעו שיש חובת \u0003שבות.\u0004 ו\u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004עשיית \u0003מלאכה\u0004 ממש — \u0003והכתיב\u0004 \u0005[ו\u0006הלא כבר \u0005נאמר]\u0006 במפורש: \u0003\"\u0004ויום השביעי שבת לה' אלהיך \u0003לא תעשה כל מלאכה \"! אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר הדבר לגבי \u0003קניבת ירק,\u0004 שאף היא שאינה מלאכה גמורה אסורה בשבת משום מצוות שבתון! ומשיבים: אכן \u0003לא\u0004 ניתן לפרש כך, אלא \u0003לעולם\u0004 נפרש \"שבתון\" בשבת \u0003למלאכה,\u0004 שיש מצוות עשה לשבות בשבת, ואף שנאמר במפורש \"ויום השביעי שבת לה' אלהיך לא תעשה כל מלאכה\", מכל מקום בא ביטוי זה להוסיף \u0003ולעבור עליה\u0004 \u0005[עליו]\u0006 שהוא עובר על כל מלאכה בשבת \u0003ב\"עשה\"\u0004 (שבתון) \u0003ו\u0004ב\u0003\"לא תעשה\u0004\".","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: יום הכפורים שחל להיות בשבת\u0004"],["\u0003מותר בקניבת ירק. ואמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: יום כיפורים שחל להיות ב\u0004ימות ה\u0003חול\u0004 — \u0003מפצעין\u0004 (מפצחים) \u0003באגוזים ומפרכסין\u0004 (מוציאים את הגרעינים) \u0003ברימונים מן המנחה ולמעלה\u0004 לפי שאין בכך מלאכה של ממש ו\u0003מפני עגמת נפש,\u0004 שאם לא ידע שיש אוכל מוכן במוצאי החג יהיה לו צער יותר בשעות הצום האחרונות (רז\"ה). מסופר: \u0003דבי\u0004 \u0005[\u0006בני \u0005בית]\u0006 \u0003רב יהודה מקנבי כרבא\u0004 \u0005[היו קונבים כרוב].\u0006 \u0003דבי\u0004 \u0005[\u0006בני \u0005בית]\u0006 \u0003רבה גרדי קארי\u0004 \u0005[היו גורדים דלעת].\u0006 \u0003כיון דחזא\u0004 \u0005[שראה]\u0006 רבה \u0003דהוו קא מחרפי\u0004 \u0005[שהיו מקדימים\u0006 לקנוב\u0005]\u0006 עוד לפני המנחה \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אתא איגרתא ממערבא משמיה\u0004 \u0005[באה איגרת\u0006 מכתב \u0005ממערב,\u0006 מארץ ישראל, \u0005משמו]\u0006 של \u0003ר' יוחנן דאסיר\u0004 \u0005[שאסור].\u0006","","\u0003כל כתבי הקדש מצילין אותן\u0004 בשבת \u0003מפני הדליקה, בין שקורין בהן,\u0004 כגון ספרי התורה והנביאים הנקראים בציבור, \u0003ובין שאין קורין בהן,\u0004 כספרי הכתובים. \u0003אף על פי שכתובים בכל לשון\u0004 ולדעת חכמים שונים אין קוראים באלה ברבים, מכל מקום יש בהם קדושה ו\u0003טעונים גניזה. ו\u0004אותם כתבי הקודש \u0003מפני מה אין קורין בהם\u0004 — \u0003מפני ביטול בית המדרש,\u0004 שהיה זמן קבוע בשבת לבוא לבית המדרש לשמוע דברי הלכה, ואסרו לעסוק בכל דבר אחר בשעה זו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר כתבי הקודש ש\u0003היו כתובים תרגום\u0004 ארמי \u0003או בכל לשון\u0004 אחרת. \u0003רב הונא אמר: אין מצילין אותן מפני הדליקה\u0004 בשבת. \u0003ורב חסדא אמר: מצילין אותן מפני הדליקה.\u0004 ומוסיפים: \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת\u0006 \u0005מי שאומר]\u0006 שכתבי הקודש הכתובים בשפות אחרות \u0003ניתנו לקרות בהן\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003מצילין\u0004 אותם. \u0003כי פליגי אליבא דמאן דאמר\u0004 \u0005[כאשר נחלקו\u0006 היה זה \u0005לשיטת מי שאומר]\u0006 \u0003לא ניתנו לקרות בהן.\u0004 ש\u0003רב הונא אמר: אין מצילין\u0004 אותם, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא ניתנו לקרות בהן.\u0004 ואילו \u0003רב חסדא אמר: מצילין משום בזיון כתבי הקדש. תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כל כתבי הקדש מצילין אותן\u0004 בשבת \u0003מפני הדליקה, בין שקורין בהן בין שאין קורין בהן, אף על פי שכתובין בכל לשון. מאי לאו\u0004 \u0005[האם לא\u0006 נפרש\u0005]\u0006 כי \u0003\"שקורין בהן\"\u0004 משמעו — ספרי ה\u0003נביאים, ו\"שאין קורין בהן\"\u0004 משמעו — \u0003כתובים, אף על פי שכתובין בכל לשון\u0004 ש\u0003לא ניתנו לקרות בהן, וקתני\u0004 \u0005[ו\u0006בכל זאת \u0005שנינו]:\u0006 \u0003מצילין, ו\u0004הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רב הונא!\u0004 \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא : ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שאפשר להוכיח מכאן? \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של משנה זו\u0005],\u0006 ששנינו \u0003בה: טעונין גניזה,\u0004 והדבר תמוה, שכן \u0003השתא אצולי מצילינן\u0004 \u0005[להציל\u0006 אותם מן הדליקה \u0005 אנו מצילים],\u0006 ואם כן לענין זה שטעונים \u0003גניזה מיבעי\u0004 \u0005[נצרך\u0006 לומר\u0005]?!\u0006 \u0003אלא\u0004 ודאי אין משנה זו נהירה כמות שהיא, ובהכרח עלינו להוסיף בה דברים כדי לבארה, ו\u0003רב הונא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 אותה \u0005לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003ורב חסדא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 אותה \u0005לטעמו,\u0006 לשיטתו\u0005].\u0006 ומפרטים, \u0003רב הונא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 אותה \u0005לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003\"בין שקורין בהן\"\u0004 — אלו ה\u0003נביאים, \"ובין שאין קורין בהן\"\u0004 — \u0003כתובים. במה דברים אמורים\u0004 — \u0003שכתובין בלשון הקדש, אבל\u0004 אינם כתובים בלשון הקודש אלא \u0003בכל לשון\u0004 אחרת — \u0003אין מצילין\u0004 אותם בשבת מפני הדליקה, \u0003ואפילו הכי\u0004 \u0005[כך],\u0006 אף על פי כן — \u0003גניזה בעו\u0004 \u0005[צריכים].\u0006 \u0003רב חסדא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 אותה \u0005לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003\"בין שקורין בהן\"\u0004 משמעו — \u0003נביאים, \"ובין שאין קורין בהן\"\u0004 — \u0003כתובים, אף על פי שכתובין בכל לשון\u0004 חוץ מלשון הקודש — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מצילין\u0004 אותם. \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003ו\u0004אף \u0003מקק\u0004 (רקבובית) \u0003שלהן טעונין גניזה.\u0004","","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003היו כתובים תרגום ו\u0004כן \u0003כל לשון\u0004 אחרת — שאינה לשון הקודש \u0003מצילין אותן\u0004 בשבת \u0003מפני הדליקה.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב הונא\u0004 האומר כי אין מצילים אותם! \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא : האי תנא סבר\u0004 \u0005[תנא זה סבור]\u0006 כי אף ספרים שאינם כתובים בלשון הקודש \u0003ניתנו לקרות בהן,\u0004 ואולם דעת רב הונא עצמו אינה כן, ולכן הוא סבור כי אף אין מצילים אותם. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו בברייתא אחרת: כתבי הקודש ש\u0003היו כתובין גיפטית\u0004 (מצרית) או \u0003מדית,\u0004 או \u0003עיברית\u0004 (בכתב העברי הקדום), או \u0003עילמית,\u0004 או \u0003יוונית, אף על פי שלא ניתנו לקרות בהן\u0004 — \u0003מצילין אותן\u0004 בשבת \u0003מפני הדליקה.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב הונא\u0004 הסובר שאין מצילים! \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בדבר זה, \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003היו כתובין תרגום ו\u0004כן \u0003בכל לשון\u0004 אחר שאינו לשון הקודש — \u0003מצילין אותן\u0004 בשבת \u0003מפני הדליקה. ר' יוסי אומר: אין מצילין אותן מפני הדליקה.\u0004","\u0003אמר ר' יוסי: מעשה באבא\u0004 (אבי), \u0003חלפתא, שהלך אצל רבן גמליאל בריבי\u0004 (הנכבד), הוא רבן גמליאל מיבנה, \u0003לטבריא\u0004 (טבריה), \u0003ומצאו שהיה יושב על שלחנו של יוחנן הנזוף, ובידו ספר איוב תרגום והוא קורא בו. אמר לו\u0004 יוחנן: \u0003זכור אני ברבן גמליאל אבי אביך, שהיה עומד על גב מעלה\u0004 (מדרגה) \u0003בהר הבית, והביאו לפניו ספר איוב תרגום ואמר לבנאי: שקעהו\u0004 את הספר הזה \u0003תחת הנדבך. אף הוא\u0004 רבן גמליאל מיבנה כששמע סיפור זה \u0003צוה עליו וגנזו. ר' יוסי בר' יהודה אומר:\u0004 שבהר הבית \u0003עריבה\u0004 (קערה גדולה) \u0003של טיט כפו\u0004 (הפכו) \u0003עליו. אמר רבי: שתי תשובות בדבר\u0004 להוכיח שלא כך היה: \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003וכי טיט בהר הבית מנין?\u0004 שבהר הבית היו בונים בחומרים אחרים, ולא בטיט. \u0003ועוד,\u0004 אפילו כתבי הקודש שאין קוראין בהם, \u0003וכי מותר לאבדן ביד? אלא\u0004 לכל היותר \u0003מניחן במקום התורפה\u0004 (מקום שבו הם עלולים להתבלות מהר) \u0003והן מרקיבין מאליהן.\u0004 ובאים לברר: \u0003מאן תנאי\u0004 \u0005[מי\u0006 הם ה\u0005תנאים]\u0006 שאמר רב הונא שנחלקו בהלכה זו"],["\u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שהוא ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שחלק עליו \u0003ר' יוסי\u0004 — אין זה הכרחי, \u0003ודילמא בהא קמיפלגי\u0004 \u0005[ושמא ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003ניתנו\u0004 ספרים בשפות אחרות \u0003לקרות בהן, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי \u0005סבור]:\u0006 \u0003לא ניתנו לקרות בהן,\u0004 ואין מחלוקתם שוה למחלוקת רב הונא ורב חסדא. \u0003אלא\u0004 יש לומר שמחלוקת זו היא בין \u0003ר' יוסי\u0004 ובין ה\u0003תנא\u0004 שדיבר על הספרים ב\u0003גיפטית,\u0004 שאותו תנא פירש שאף ספרים שאין קוראים בהם מצילים אותם, ור' יוסי סבור שאין מצילים אותם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הברכות\u0004 הכתובות \u0003והקמיעין, אף על פי שיש בהן אותיות של שם\u0004 השם \u0003ו\u0004מוזכרים בהם \u0003עניינות\u0004 (עניינים) \u0003הרבה שבתורה\u0004 — \u0003אין מצילין אותן מפני הדליקה, אלא\u0004 אם היתה במקומם דליקה בשבת הריהם \u0003נשרפים במקומן הן ואזכרותיהן\u0004 (שמות השם שבהם). \u0003מכאן אמרו: כותבי ברכות\u0004 הריהם \u0003כשורפי תורה,\u0004 שהרי אסור להצילם מן הדליקה בשבת, ויתכן איפוא שיבוא לידי שריפה. ומסופר \u0003מעשה באחד שהיה כותב בצידן\u0004 טופסי ברכות. \u0003באו והודיעו את ר' ישמעאל\u0004 על מעשיו. \u0003והלך ר' ישמעאל לבודקו\u0004 אם נכונה השמועה. \u0003כשהיה עולה\u0004 ר' ישמעאל \u0003בסולם\u0004 אליו, \u0003הרגיש בו\u0004 הכותב ו\u0003נטל טומוס\u0004 \u0005[כרך]\u0006 \u0003של ברכות ושקען בספל של מים\u0004 להסתירו מעיני ר' ישמעאל. \u0003ובלשון הזה אמר לו ר' ישמעאל: גדול עונש\u0004 העושה מעשה כעין \u0003האחרון מן\u0004 העושה כעין \u0003הראשון,\u0004 שאף שיש איסור בכתיבת הברכות ודאי האיסור לאבדן בידים גדול יותר.","\u0003בעא מיניה ריש גלותא\u0004 \u0005[שאל ממנו ראש הגולה]\u0006 \u0003מרבה בר רב הונא\u0004 שאלה זו: \u0003היו\u0004 ספרי קודש \u0003כתובין בסם ובסיקרא בקומוס ובקנקנתום\u0004 (מיני צבעים שאין כותבים בהם ספרי תורה), והיו הספרים כתובים כדינם \u0003בלשון הקדש,\u0004 האם \u0003מצילין אותן\u0004 בשבת \u0003מפני הדליקה או אין מצילין?\u0004 ומוסיפים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 שאלה \u0005זו\u0006 \u0003ל\u0004שיטת \u0005מי שאומר]\u0006 ש\u0003מצילין\u0004 כתבי הקודש שבשפות אחרות, \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 גם כן לשיטת \u0005מי שאומר]\u0006 ש\u0003אין מצילין.\u0004 ומפרטים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 שאלה \u0005זו\u0006 \u0003ל\u0004שיטת \u0005מי שאומר]\u0006 ש\u0003אין מצילין\u0004 — שמא \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דכתיבי\u0004 \u0005[היכן ש\u0006הם \u0005כתובים]\u0006 \u0003תרגום ובכל לשון, אבל הכא דכתיבי\u0004 \u0005[כאן ש\u0006הם \u0005כתובים]\u0006 \u0003בלשון הקדש\u0004 — \u0003מצילין, או דילמא\u0004 \u0005[שמא]\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מצילין\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דכתיבי\u0004 \u0005[היכן ש\u0006הם \u0005כתובים]\u0006 \u0003בדיו דמיקיים\u0004 \u0005[שמתקיימת],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דלא מיקיים\u0004 \u0005[שאין\u0006 הכתב \u0005מתקיים]\u0006 — \u0003לא\u0004 מצילים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא: \u0003אין מצילין.\u0004 אמר לו ראש הגולה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב המנונא תנא\u0004 \u0005[שנה]\u0006 בברייתא ש\u0003מצילין! אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא: \u0003אי תניא\u0004 \u0005[אם שנויה\u0006 ברייתא\u0005]\u0006 — \u0003תניא\u0004 \u0005[\u0006\u0005שנויה],\u0006 ואני חוזר בי מדברי. ושואלים: \u0003מאי תניא\u0004 \u0005[מה\u0006 היא ברייתא זו \u0005השנויה\u0006 בענין זה\u0005]?\u0006 \u0003אמר רב אשי, כדתניא\u0004 \u0005[כ\u0006מה \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין\u0004 הבדל \u0003בין ספרים למגילה אלא שהספרים נכתבים בכל לשון\u0004 והם כשרים, \u0003ומגילה\u0004 אינה כשרה \u0003עד שתהא כתובה אשורית\u0004 (בכתב העברי המרובע), \u0003על הספר\u0004 (הקלף הגלול), \u0003ובדיו,\u0004 ומכאן למדנו ששאר ספרים אין חייבים להכתב בדיו.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב הונא בר חלוב מרב נחמן: ספר תורה שאין בו\u0004 כדי \u0003ללקט שמונים וחמש אותיות\u0004 שלמות הכתובות כראוי וכסדרו שהוא השיעור שקבעו חכמים, שעדיין יש בספר קדושת התורה עד שיהיה כגודל \u0003כגון פרשת \"ויהי בנסע הארן\"\u0004 (במדבר י, לה–לו), \u0003מצילין אותה\u0004 בשבת \u0003מפני הדליקה או אין מצילין? אמר\u0004 ליה \u0005[לו]:\u0006 רב נחמן: \u0003ותיבעי\u0004 \u0005[ותישאל]\u0006 \u0003לך פרשת \"ויהי בנסע הארן\" גופה\u0004 \u0005[עצמה]\u0006 אם חסרה בה אות אחת, אם מצילים אותה או אין מצילים? ענה לו: \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003חסר פרשת \"ויהי בנסע\"\u0004 — \u0003לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 השאלה, שמ \u0003כיון דאית ביה\u0004 \u0005[שיש בה]\u0006 \u0003הזכרות\u0004 שם השם — \u0003אף על גב דלית ביה\u0004 \u0005[אף על פי שאין בה]\u0006 \u0003שמונים וחמש אותיות\u0004 ש\u0003מצילין\u0004 אותה. ואולם \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 השאלה הרי זה ב\u0003ספר תורה שאין בו\u0004 כדי \u0003ללקט מאי\u0004 \u0005[מה\u0006 דינו\u0005],\u0006 האם מצילים אותו מהדליקה בשבת, או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מצילין.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו \u0003תרגום\u0004 ארמי \u0003שכתבו\u0004 בלשון \u0003מקרא, ומקרא שכתבו\u0004 בלשון \u0003תרגום, ו\u0004תורה הכתובה ב\u0003כתב עברית\u0004 (הקדום) — \u0003מצילין\u0004 אותם בשבת \u0003מפני הדליקה. ואין צריך לומר\u0004 שמצילים \u0003תרגום שב\u0004ספרי \u0003עזרא ושבדניאל ושבתורה.\u0004 ומעתה \u0003תרגום שבתורה מאי ניהו\u0004 \u0005[מה הוא]?\u0006 — הרי זה האמור \"ויקרא לו לבן \u0003יגר שהדותא\u0004 ויעקב קרא לו גלעד\" (בראשית לא, מז), \u0003ו\u0004נמצא שמצילים אותו \u0003אף על גב דלית\u0004 \u0005[אף על פי שאין]\u0006 \u0003בה שמונים וחמש אותיות!\u0004 ענה לו: אין מכאן ראיה, שכן \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 — היה זה \u0003להשלים,\u0004 שתרגום זה מצטרף לשמונים וחמש אותיות, אבל אינו נחשב בפני עצמו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003הני\u0004 \u0005[אותן]\u0006 \u0003שמונים וחמש אותיות\u0004 שמצילין בגללן ספר תורה שלם, האם דווקא כשהיו \u0003מכונסות\u0004 וכתובות במקום אחד \u0003או\u0004 אף כשהן \u0003מפוזרות? רב הונא אמר:\u0004 רק כשהן \u0003מכונסות. רב חסדא אמר: אפילו\u0004 שכשהן \u0003מפוזרות. מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003ספר תורה שבלה, אם יש בו\u0004 כדי \u0003ללקט שמונים וחמש אותיות כגון פרשת \"ויהי בנסע הארן\"\u0004 — \u0003מצילין, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מצילין.\u0004 ולשון \"ללקט\" משמעה שאין האותיות כנוסות במקום אחד, והרי זו אם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב הונא! תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב חסדא אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003רב הונא :\u0004 כוונת הברייתא ההיא שהם אכן מפוזרות ואולם כ\u0003תיבות\u0004 (מילים), שאותיות אלה היו מצורפות למילים שלימות, ורב הונא רואה בהן מכונסות ולא נחלקו אלא באותיות המפוזרות כל אחת לעצמה.","כיון שהוזכרה פרשת \"ויהי בנסוע הארון\" מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בעניינה: נאמר \u0003\"ויהי בנסע הארן ויאמר משה\u0004 קומה ה' ויפוצו אויבך וינוסו משנאיך מפניך \u0003\"\u0004ו\u0003פרשה זו עשה לה הקדוש ברוך הוא\u0004 בתורה \u0003סימניות מלמעלה ולמטה,\u0004 כלומר, לפניה ואחריה, וזאת כדי \u0003לומר\u0004"],["\u0003שאין זה מקומה,\u0004 שהרי הפרשה שלפניה אינה עוסקת במסע העם. \u0003רבי אומר: לא מן השם הוא זה,\u0004 כלומר, לא זה הוא הטעם. \u0003אלא\u0004 נעשו הסימניות \u0003מפני ש\u0004קטע זה \u0003ספר חשוב הוא בפני עצמו.\u0004","ומעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 אמרה \u0005זו]\u0006 ש\u0003אמר ר' שמואל בר נחמן\u0004 שכך \u0003אמר ר' יונתן\u0004 שמה שנאמר \u0003\"\u0004חכמות בנתה ביתה \u0003חצבה עמודיה שבעה\"\u0004 (משלי ט, א), אותם \"שבעה\" \u0003אלו שבעה ספרי תורה?\u0004 — \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003כ\u0004שיטת \u0003רבי,\u0004 שלפי שיטתו שבעה ספרים בתורה: ספר בראשית, שמות, ויקרא, ספר במדבר עד \"ויהי בנסוע הארון\", פרשת \"ויהי בנסוע הארון\" הנחשבת לספר בפני עצמו, ספר במדבר מפרשה זו והלאה, וספר דברים — הרי שבעה.","\u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[החולק עליו]\u0006 על \u0003רבי\u0004 בענין זה — \u0003רבן שמעון בן גמליאל הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבן שמעון בן גמליאל אומר: עתידה פרשה זו שתיעקר מכאן,\u0004 מהמקום בו היא כתובה, \u0003ותכתב במקומה\u0004 הראוי לה. \u0003ולמה כתבה כאן\u0004 אף שהיא עוסקת בענין מסע בני ישראל והפרשה שלפניה אינה עוסקת בענין זה — \u0003כדי להפסיק בין פורענות ראשונה לפורענות שנייה. פורענות שנייה מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — הכתובה מיד אחר כך \u0003\"ויהי העם כמתאננים\u0004 רע באזני ה' וישמע ה' ויחר אפו ותבער בם אש ה' ותאכל בקצה המחנה\u0003\"\u0004 (במדבר יא, א). \u0003פורענות ראשונה\u0004 — מה שנאמר: \u0003\"ויסעו מהר ה'\u0004 דרך שלושת ימים\u0003\"\u0004 (במדבר י, לג) \u0003ואמר ר' חמא בר' חנינא: שסרו מאחרי ה'\u0004 ומיהרו לברוח מהר סיני. ושואלים: \u0003ו\u0004אם כן — \u0003היכן מקומה\u0004 הנכון של פרשה זו? \u0003אמר רב אשי: ב\u0004פרשת ה\u0003דגלים,\u0004 ששם מופיע תיאור דרך מסע בני ישראל במדבר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הגליונין\u0004 (קטעי הקלף החלק) \u0003של ספר תורה,\u0004 האם \u0003מצילין אותן\u0004 בשבת \u0003מפני הדליקה או אין מצילין אותן מפני הדליקה? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003ספר תורה שבלה, אם יש בו ללקט שמונים וחמש אותיות, כגון פרשת \"ויהי בנסע הארן\"\u0004 — \u0003מצילין\u0004 אותו \u0003בשבת מן הדליקה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מצילין. ו\u0004מעתה, אם \u0003מצילים גם את הגליון אם כן אמאי\u0004 \u0005[ומדוע]\u0006 לא יצילו גם כשאין אותיות? \u0003תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד \u0005לו]\u0006 הלכה זו \u0003משום\u0004 עצם ה\u0003גליון דידיה\u0004 \u0005[שלו]!\u0006 ומשיבים: ספר \u0003בלה שאני\u0004 \u0005[שונה],\u0006 שכיון שבלה הספר אפשר לומר שקדושתו בטלה ממנו, ואף גליונו אינו מקודש, ולכן אין מצילים אותו אלא אם כן יש בו כדי ללקט שמונים וחמש אותיות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו בברייתא אחרת: \u0003ספר תורה שנמחק, אם יש בו\u0004 עדיין כדי \u0003ללקט שמונים וחמש אותיות\u0004 — \u0003כגון פרשת \"ויהי בנסע הארן\"\u0004 — \u0003מצילין\u0004 אותו מפני הדליקה בשבת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין מצילין, ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד \u0005לו]\u0006 הלכה זו \u0003משום\u0004 ה\u0003גיליון דידיה\u0004 \u0005[שלו],\u0006 ולא יהא המקום המחוק גרוע מגליון הספר! ומשיבים: אין הדבר כן, \u0003מקום הכתב\u0004 שנמחק \u0003לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 בו השאלה, \u0003דכי קדוש\u0004 \u0005[שכאשר מתקדש]\u0006 — \u0003אגב\u0004 ה\u0003כתב הוא דקדוש\u0004 \u0005[שנתקדש],\u0006 ואם \u0003אזל\u0004 \u0005[הלך]\u0006 ה\u0003כתב\u0004 — \u0003אזלא\u0004 \u0005[הלכה]\u0006 \u0003לה קדושתיה\u0004 \u0005[קדושתו].\u0006 \u0003כי קמיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 השאלה היה זה ביחס לגליון הנקי \u0003של מעלה ושל מטה,\u0004 בדף \u0003שבין פרשה לפרשה, שבין דף לדף, שבתחלת הספר,\u0004 ו\u0003שבסוף הספר.\u0004 ועדיין שואלים: אם כן \u0003ותיפוק ליה\u0004 \u0005[ותצא,\u0006 תילמד \u0005לו]\u0006 חובה להציל ספר שבלה או שנמחק \u0003משום\u0004 החלק \u0003ההוא\u0004 של הגליון, שאם יש בו קדושה נשארה קדושתו! ומשיבים: שם מדובר כגון \u0003דגייז ושדי\u0004 \u0005[שנגזז\u0006 הגליון \u0005ונזרק]\u0006 ונשאר רק מקום הכתב לבדו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו במשנה: \u0003הגליונין של מעלה ושל מטה, שבין פרשה לפרשה, שבין דף לדף, שבתחלת הספר, שבסוף הספר\u0004 — \u0003מטמאין\u0004 מדברי סופרים \u0003את הידים\u0004 הנוגעות בהם. ונמצא אם כן שיש בגליונות קדושת ספר תורה! ומשיבים: אין זו ראיה, אלא \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003אגב ספר תורה שאני\u0004 \u0005[שונה],\u0006 ונתפסת קדושה אף בגליון, אבל כשהם לבד אין בהם קדושה.","על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו בברייתא אחרת: \u0003הגיליונין וספרי\u0004 ה\u0003מינין\u0004 (ספרי תורה שכתבו מינים) \u0003אין מצילין אותן מפני הדליקה אלא נשרפין במקומן הן ואזכרותיהן. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003גליונין\u0004 של \u0003ספר תורה?\u0004 ודוחים: \u0003לא,\u0004 דובר ב\u0003גליונין\u0004 של \u0003ספרי מינין.\u0004 על כך תוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ספרי מינין גופייהו\u0004 \u0005[עצמם]\u0006 \u0003אין מצילין\u0004 אותם, \u0003גליונין\u0004 שלהם \u0003מבעיא\u0004 \u0005[נצרכה]\u0006 לומר? אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וספרי מינין הרי הן כגליונים.\u0004","כיון שהוזכר הענין, מביאים הלכה זו \u0003גופא\u0004 \u0005[גופה].\u0006 ששנינו: \u0003הגליונים וספרי\u0004 ה\u0003מינין אין מצילין אותם מפני הדליקה. ר' יוסי אומר: ב\u0004יום \u0003חול\u0004 — \u0003קודר\u0004 (חותך) ומוציא \u0003את האזכרות\u0004 של שם השם \u0003שבהן וגונזן, והשאר\u0004 — \u0003שורפן. אמר ר' טרפון\u0004 בלשון שבועה: \u0003אקפח\u0004 (אאבד) \u0003את בני\u0004 אם לא אנהג כך, \u0003שאם יבאו\u0004 ספרים אלה \u0003לידי שאני אשרוף אותם ואת האזכרות שבהן. שאפילו\u0004 היה \u0003אדם רודף אחריו להורגו, ונחש רץ להכישו,\u0004 מוטב שיהא \u0003נכנס לבית עבודה זרה ואין נכנס לבתיהן של אלו\u0004 המינים. והטעם: \u0003שהללו,\u0004 המינים, \u0003מכירין\u0004 בגדולת הבורא בתורה ומצוותיה \u0003ו\u0004עם כל זה הם \u0003כופרין, והללו\u0004 הגויים עובדי עבודה זרה \u0003אין מכירין ו\u0004לכן הם \u0003כופרין. ועליהן,\u0004 על המינים \u0003הכתוב אומר: \"ואחר הדלת והמזוזה שמת זכרונך\"\u0004 (ישעיה נז, ח). כלומר, אף שדבר ה' זכור להם, מכל מקום הם מתייחסים אליו בכל זאת בזלזול וכאילו אחרי הדלת.","\u0003אמר ר' ישמעאל: קל וחומר\u0004 הוא שמותר לשרוף ולאבד את האזכרות שבספרי המינים; \u0003ומה\u0004 אם כדי \u0003לעשות שלום בין איש לאשתו אמרה\u0004 ה\u0003תורה: שמי שנכתב בקדושה ימחה על המים\u0004 בבדיקת הסוטה שמוחים בגללה פרשה מן התורה על אזכרותיה, \u0003הללו שמטילין קנאה ואיבה ותחרות בין ישראל לאביהן שבשמים\u0004 — \u0003על אחת כמה וכמה\u0004 שראוי לאבד בשבילם את האזכרות. \u0003ועליהם אמר דוד: \"הלא משנאיך ה' אשנא ובתקוממיך אתקוטט תכלית שנאה שנאתים לאויבים היו לי\"\u0004 (תהלים קלט, כא–כב). \u0003וכשם שאין מצילין אותן מפני הדליקה, כך אין מצילין אותן לא מן המפולת ולא מן המים ולא מ\u0004כל \u0003דבר\u0004 אחר \u0003המאבדן.\u0004","\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003יוסף בר חנין מר' אבהו\u0004 שאלה זו: \u0003הני ספרי דבי\u0004 \u0005[אותם ספרים של בית]\u0006 \u0003אבידן,\u0004 שהיו בבית זה גם ספרי קודש יהודיים, ובו היו נועדים לוויכוחים ולדיונים בעניני אמונה, האם \u0003מצילין אותן מפני הדליקה או אין מצילין?\u0004 ולא ענה ר' אבהו תשובה ברורה, אלא \u0003אין ולאו ורפיא בידיה\u0004 \u0005[כן ולא, ורופף בידו\u0006 הדבר\u0005].\u0006 \u0003רב לא אזיל לבי\u0004 \u0005[היה הולך לבחית]\u0006 \u0003אבידן\u0004 לשיחה, \u0003וכל שכן לבי נצרפי\u0004 (מקום מקדש־האש הפרסי). \u0003שמואל לבי נצרפי לא אזיל\u0004 \u0005[הלך],\u0006 \u0003לבי\u0004 \u0005[לבית]\u0006 \u0003אבידן אזיל\u0004 \u0005[היה הולך].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 חכמי הגויים \u0003לרבא: מאי טעמא לא אתית לבי\u0004 \u0005[מדוע אינך בא לבית]\u0006 \u0003אבידן?\u0004 השתמט מהם בתירוץ ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דיקלא פלניא איכא באורחא, וקשי לי\u0004 \u0005[דקל מסויים עומד בדרך, וקשה עלי\u0006 הדרך בגללו\u0005].\u0006 אמרו לו: \u0003ניעקריה\u0004 \u0005[נעקרנו].\u0006 אמר להם: אם כן, \u0003דוכתיה קשי לי\u0004 \u0005[מקומו,\u0006 הגומה שתיווצר \u0005קשה עלי].\u0006 \u0003מר בר יוסף אמר: אנא מינייהו אנא, ולא מסתפינא מינייהו\u0004 \u0005[אני מהם אני,\u0006 שאני בידידות עמם, \u0005ואיני חושש מהם],\u0006 ואף על פי כן, \u0003זימנא חדא אזיל, בעו לסכוניה\u0004 \u0005[פעם אחת הלך\u0006 והתווכח אתם, ו\u0005רצו לסכן אותו,\u0006 את חייו\u0005].\u0006 \u0003ר' מאיר קרי ליה\u0004 היה קורא לספר הדת הנוצרית (האוונגליון) \u0003אוון\u0004 (רשע, או אסון) \u0003גליון, ר' יוחנן הוה קרי ליה\u0004 \u0005[היה קורא להם]\u0006 \u0003עוון גליון.\u0004","מסופר: \u0003אימא שלום דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' אליעזר אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003רבן גמליאל הואי\u0004 \u0005[היתה].\u0006 \u0003הוה ההוא פילוסופא בשבבותיה\u0004 \u0005[היה פילוסוף אחד\u0006 נוצרי \u0005בשכנותם]\u0006"],["\u0003דהוה שקיל שמא דלא מקבל שוחדא\u0004 \u0005[שהוציא שם\u0006 על עצמו \u0005שאיננו מקבל שוחד].\u0006 \u0003בעו לאחוכי ביה\u0004 \u0005[רצו לצחק בו]\u0006 ולגלות את טיבו האמיתי. \u0003אעיילא ליה שרגא דדהבא, ואזול לקמיה\u0004 \u0005[הכניסה לו\u0006 בסתר \u0005מנורה של זהב, ובאו לפניו]\u0006 היא ואחיה, כאילו על מנת להתדיין. \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לאותו פילוסוף: \u0003בעינא דניפלגי\u0004 \u0005[רוצה אני שיחלקו]\u0006 \u0003לי בנכסי דבי נשי\u0004 \u0005[ב\u0006ירושת \u0005נכסי אבותי].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פלוגו\u0004 \u0005[חלוקו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003כתיב לן\u0004 \u0005[כתוב לנו]\u0006 בתורה: \u0003במקום\u0004 שיש \u0003ברא\u0004 \u0005[בן],\u0006 \u0003ברתא\u0004 \u0005[הבת]\u0006 \u0003לא תירות\u0004 \u0005[תירש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הפילוסוף: \u0003מן יומא דגליתון מארעכון, איתנטלית אורייתא\u0004 \u0005[מיום שגליתם מארצכם, ניטלה תורת]\u0006 \u0003משה ואיתיהיבת\u0004 \u0005[וניתן]\u0006 \u0003עוון גליון\u0004 (אוונגליון), \u0003וכתיב ביה\u0004 \u0005[וכתוב בו]:\u0006 \u0003ברא וברתא כחדא ירתון\u0004 \u0005[הבן והבת ירשו כאחת].\u0006","\u0003למחר הדר עייל ליה איהו חמרא לובא\u0004 \u0005[למחר הכניס לו הוא,\u0006 רבן גמליאל, לפילוסוף \u0005חמור לובי].\u0006 אחר כך באו לפניו שוב להתדיין. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שפילית לסיפיה\u0004 \u0005[עיינתי בסופו]\u0006 של \u0003עוון גליון, וכתיב ביה\u0004 \u0005[וכתוב בו]:\u0006 \u0003אנא\u0004 עוון גליון \u0003לא למיפחת מן אורייתא\u0004 \u0005[לפחות מתורת]\u0006 \u0003משה אתיתי\u0004 \u0005[באתי],\u0006 \u0003[ולא] לאוספי על אורייתא דמשה אתיתי , וכתיב ביה\u0004 \u0005[וכתוב בה,\u0006 בתורה\u0005]:\u0006 \u0003במקום\u0004 שיש \u0003ברא\u0004 \u0005[בן]\u0006 — \u0003ברתא\u0004 \u0005[הבת]\u0006 \u0003לא תירות\u0004 \u0005[תירש].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003נהור נהוריך כשרגא\u0004 \u0005[יאיר אורך כמנורה]\u0006 לרמז לו על המנורה שנתנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבן גמליאל: אתא חמרא ובטש לשרגא\u0004 \u0005[בא החמור ובעט במנורה]\u0006 וממילא נתגלה כל אותו מעשה.","שנינו במשנה: \u0003ומפני מה אין קורין\u0004 בכתובים בשבת — מפני ביטול בית המדרש. \u0003אמר רב: לא שנו\u0004 שאסור לקרוא בכתובים בשבת \u0003אלא בזמן בית המדרש, אבל שלא בזמן בית המדרש\u0004 — \u0003קורין. ושמואל אמר: אפילו שלא בזמן בית המדרש אין קורין\u0004 בכתובים בשבת. ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003נהרדעא אתריה\u0004 \u0005[מקומו]\u0006 של \u0003שמואל הוה\u0004 \u0005[היתה]\u0006 והוא היה רבו של המקום, \u0003ובנהרדעא פסקי סידרא\u0004 \u0005[היו\u0006 רגילים \u0005להפטיר לאחר\u0006 הלימוד\u0005]\u0006 \u0003בכתובים במנחתא דשבתא\u0004 \u0005[במנחת שבת].\u0006 \u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 שיש מחלוקת בדבר, \u0005כך נאמר],\u0006 \u0003אמר רב: לא שנו\u0004 שיש איסור \u0003אלא במקום בית המדרש,\u0004 שיש באותו מקום בית מדרש שראוי לעם לבוא אליו. \u0003אבל שלא במקום בית המדרש\u0004 — \u0003קורין.\u0004","\u0003ושמואל אמר: בין במקום בית המדרש בין שלא במקום בית המדרש, בזמן בית המדרש\u0004 — \u0003אין קורין\u0004 בכל מקום, \u0003שלא בזמן בית המדרש\u0004 — \u0003קורין. ואזדא\u0004 \u0005[והולך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003בנהרדעא פסקי סידרא\u0004 \u0005[היו\u0006 רגילים \u0005להפטיר לאחר\u0006 הלימוד\u0005]\u0006 ב\u0003כתובים במנחתא דשבתא\u0004 \u0005[במנחת שבת].\u0006","\u0003רב אשי אמר: לעולם\u0004 תאמר \u0003כדאמרן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה]\u0006 את המחלוקת, \u0003ו\u0004מה שאמר \u0003שמואל\u0004 היה \u0003כ\u0004שיטת \u0003ר' נחמיה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אף על פי שאמרו\u0004 חכמים \u0003שכתבי הקדש אין קורין בהן\u0004 בשבת — \u0003אבל שונין בהן\u0004 במדרשי חכמים שבהם \u0003ודורשין בהן\u0004 בפני הקהל, ואם \u0003נצרך לפסוק\u0004 הכתוב בכתובים — \u0003מביא\u0004 ספר \u0003ורואה בו. אמר ר' נחמיה: מפני מה אמרו כתבי הקדש אין קורין בהן\u0004 בשבת — \u0003כדי שיאמרו\u0004 אנשים: \u0003בכתבי הקדש אין קורין, וכל שכן בשטרי הדיוטות\u0004 (שטרות ומכתבים), ואם כן לשיטת ר' נחמיה נאסרה בכלל קריאה בכתובים בשבת לא מטעם ביטול בית המדרש, אלא כדי שלא יקראו בדברי חול בשבת, ועל פי שיטה זו אמר שמואל שאסור אף שלא בזמן בית המדרש. אבל שמואל עצמו לא סבר כר' נחמיה.","\u0003מצילין\u0004 מן הדליקה בשבת את \u0003תיק הספר\u0004 (ספר תורה) \u0003עם הספר, ותיק התפילין עם התפילין, ואף על פי שיש בתוכן מעות. ולהיכן מצילין אותן\u0004 — \u0003למבוי שאינו מפולש,\u0004 שכיון שיש בו שלוש מחיצות הריהו מן התורה כרשות היחיד. \u0003בן בתירא אומר: אף ל\u0004מבוי \u0003מפולש.\u0004","בהקשר לנאמר במשנה מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003ארבעה עשר\u0004 בניסן \u0003שחל להיות בשבת,\u0004 והקריבו את קרבן הפסח ואין מתחילים בצלייתו עד צאת השבת — \u0003מפשיטין את\u0004 קרבן \u0003הפסח עד החזה\u0004 בלבד, כדי להוציא מתוכו את החלק שמקריבים על המזבח, וממתינים עד מוצאי שבת בהמשך הפשטתו, שכיון שאינה אלא לצורך אכילה — אינה דוחה שבת, אלו \u0003דברי ר' ישמעאל בנו של ר' יוחנן בן ברוקה. וחכמים אומרים: מפשיטין את כולו.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה\u0004 שאמר שאין להפשיט יותר מחלקו מובן הדבר, \u0003דהא איתעביד ליה\u0004 \u0005[שהרי נעשה לו,\u0006 בו\u0005]\u0006 כבר \u0003צורך גבוה,\u0004 צורך המזבח, בזריקת דם הקרבן. \u0003אלא לרבנן מאי טעמא\u0004 \u0005[ל\u0006שיטת \u0005חכמים מה טעם]\u0006 הדבר? \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כל פעל ה' למענהו\"\u0004 (משלי טז, ד), ואם יש כבוד ה' בדבר מותר לעשות מלאכה לצורך זה. ושואלים: \u0003והכא\u0004 \u0005[וכאן],\u0006 בהפשטת עור הפסח, \u0003מאי\u0004 \u0005[מה\u0006 צד\u0005]\u0006 של \u0003\"למענהו\",\u0004 כבוד שמים, \u0003איכא\u0004 \u0005[יש]\u0006 שבגללו מותר להפשיט? \u0003רב יוסף אמר:\u0004 התירו להפשיט את העור כולו כדי \u0003שלא יסריח\u0004 הקרבן. \u0003רבא אמר: שלא יהו קדשי שמים מוטלין\u0004 בבזיון \u0003כנבלה\u0004 שהפשיטוה למחצה ואין מטפלים בה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל מעשי\u0005]\u0006 באופן \u0003דמנח אפתורא דדהבא\u0004 \u0005[שמונח\u0006 הפסח \u0005על שולחן של זהב]\u0006 שאמנם יש לחשוש שמא יסריח, אבל אין כאן משום בזיון. \u0003אי נמי יומא דאסתנא\u0004 \u0005[או גם כן יום של רוח צפונית]\u0006 צוננת, שאין חשש לסרחון, אבל יש חשש לביזוי הקודש. ושואלים: \u0003ור' ישמעאל בנו של ר' יוחנן בן ברוקה, האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"\u0004כל \u0003פעל ה' למענהו\" מאי עביד ליה\u0004 \u0005[\u0006\u0005מה\u0006 הוא \u0005עושה בו]?\u0006 ומשיבים: אף הוא משתמש בכתוב זה כדי להתיר הפשטת מקצת העור, \u0003ש\u0004אם \u0003לא\u0004 כן הרי אפשר היה ש\u0003יוציא את האימורין\u0004 (החלקים המוקרבים על המזבח) \u0003קודם הפשטת העור,\u0004 שהרי יכול לנקוב בעור הבהמה ולהוציא משם את החלבים. ושואלים: לשיטתו, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין עושים בדרך זו? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן : משום נימין\u0004 (שערות) שלא יסתבכו באימורים ויפסידו את צורתם.","\u0003אמר רב חסדא\u0004 שכך \u0003אמר מר עוקבא: מאי אהדרו ליה חברייא\u0004 \u0005[מה החזירו לו בני החבורה]\u0006 \u0003לר' ישמעאל בנו של ר' יוחנן בן ברוקה? הכי קאמרי ליה\u0004 \u0005[כך אמרו לו]:\u0006 \u0003אם מצילין\u0004 את \u0003תיק הספר עם הספר,\u0004 מדוע אם כן \u0003לא נפשיט את הפסח מעורו?\u0004 שאף כאן, כיון שהותרה מקצת מלאכה — נעשה אותה כולה. ותוהים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בהוצאת תיק הספר — הלא רק \u0003טלטול\u0004 בלבד יש בכך, שאיסורו מדברי חכמים, ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 בהפשטת העור\u0005]\u0006 — \u0003מלאכה\u0004 גמורה היא! \u0003אמר רב אשי: בתרתי פליגי\u0004 \u0005[בשתי\u0006 בעיות \u0005נחלקו],\u0006 \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003ב\u0004ענין היתר \u0003טלטול\u0004 העור עם הבשר \u0003ופליגי\u0004 \u0005[ונחלקו]\u0006 \u0003ב\u0004ענין היתר \u0003מלאכה\u0004 של הפשטת העור, \u0003והכי קאמרי ליה\u0004 \u0005[וכך אמרו לו]:\u0006 \u0003אם מצילין\u0004 את \u0003תיק הספר עם הספר,\u0004 מדוע \u0003לא נטלטל\u0004 את \u0003עור\u0004 הפסח \u0003אגב בשר\u0004 הפסח, שבשל הקרבן יטלטלו אף אותו על עורו כדי שלא יתקלקל."],["\u0003מי דמי\u0004 \u0005[האם דומה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בתיק הספר — \u0003נעשה\u0004 התיק \u0003בסיס לדבר המותר,\u0004 שהרי הספר עצמו מותר בטלטול בשבת, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בעור הפסח — \u0003נעשה\u0004 העור \u0003בסיס לדבר האסור,\u0004 שהרי בשר קרבן הפסח אסור באכילה עד הערב, ולכן גם בטלטול אסור הוא עד הערב! \u0003אלא הכי קאמרי ליה\u0004 \u0005[כך אמרו לו]:\u0006 \u0003אם מצילין\u0004 את ה\u0003תיק של ספר עם הספר, ואף על פי שיש בתוכו מעות,\u0004 מדוע אם כן \u0003לא נטלטל\u0004 את ה\u0003עור אגב\u0004 ה\u0003בשר?!\u0004 ומקשים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בספר \u0003— נעשה\u0004 התיק \u0003בסיס לדבר האסור ולדבר המותר,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בעור — \u0003כולו נעשה בסיס\u0004 רק \u0003לדבר האסור. אלא הכי קאמרי ליה\u0004 \u0005[כך אמרו לון:\u0006 \u0003אם מביאין תיק שיש בתוכו מעות מעלמא\u0004 \u0005[מן החוץ]\u0006 כדי \u0003להציל בו ספר תורה,\u0004 מדוע \u0003לא נטלטל\u0004 את ה\u0003עור אגב\u0004 ה\u0003בשר?!\u0004","ושואלים: \u0003והיא,\u0004 הלכה זו \u0003גופה מנלן\u0004 \u0005[עצמה מניין לנו]?\u0006 מנין למדנו שמותר להביא בשבת מן החוץ תיק שיש בו מעות להציל בו ספר? והרי לא נאמר דבר זה במשנה! \u0003אילימא דמדהיכא דאית ביה לא שדי להו, איתויי נמי מייתינן\u0004 \u0005[אם תאמר\u0006 שמכיון \u0005שבמקום שיש בו\u0006 בתיק של הספר מעות \u0005אין אנו משליכים אותן,\u0006 אלא מוציאים אותו עמהם, ואם כן כשהתיק בחוץ ויש בו מעות \u0005להביא גם כן מביאים\u0006 אותו\u0005]\u0006 — \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בספר שיש בתיקו מעות — \u0003אדהכי והכי\u0004 \u0005[בין כה וכה]\u0006 אם יתמהמה כדי לזרוק את המעות ממנו יש לחשוש כי בינתיים \u0003נפלה דליקה\u0004 ושמא יישרף הספר, ואולם \u0003הכא\u0004 — \u0003אדהכא והכי לישדינן\u0004 \u0005[כאן\u0006 — \u0005בין כה וכה,\u0006 עד שהוא מביא את התיק, \u0005שישליכן].\u0006 \u0003אלא אמר מר בר רב אשי: לעולם כדאמרינן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה]\u0006 שהשוו חכמים טלטול תיק הספר להפשטת עור הפסח. \u0003ודקא קשיא\u0004 \u0005[ו\u0006זה \u0005שהיה קשה]\u0006 \u0003לך\u0004 כי \u0003הכא\u0004 \u0005[כאן]\u0006 בתיק הספר — \u0003טלטול\u0004 בלבד \u0003הוא, והכא\u0004 \u0005[ו\u0006אילו \u0005כאן]\u0006 — \u0003מלאכה\u0004 גמורה היא — אפשר לפרש זאת ב\u0003כגון דלא קבעי ליה\u0004 \u0005[שאינו צריך לו]\u0006 \u0003לעור,\u0004 וכיון שאינו מתכוין בהפשטה לעור עצמו — פטור על מלאכה זו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[ב\"חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 שאם יש תוצאה למעשהו, אף אם אינו מתכוון לה, אם היא הכרחית — אף ר' שמעון הפוטר במלאכה שאינו מתכוין לה — מחייב. אלא יש לומר: \u0003דשקיל ליה בברזי\u0004 \u0005[שמפשיט אותו רצועות\u0006 רצועות\u0005],\u0006 ואינו נהנה מן העור, ומאחר שכן אין זו נחשבת כמלאכת הפשטה.","שנינו במשנה: \u0003ולהיכן מצילין אותן\u0004 את תיק הספר — למבוי שאינו מפולש, ובן בתירא מתיר אף במפולש. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מפולש, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003שאינו מפולש? אמר רב חסדא:\u0004 מבוי שיש בו \u0003שלש מחיצות ושני לחיין\u0004 בפתחו — \u0003זהו מבוי שאינו מפולש. שלוש מחיצות ולחי אחד\u0004 — \u0003זהו מבוי המפולש. ותרוייהו אליבא\u0004 \u0005[ושניהם,\u0006 התנא הראשון ובן בתירא שנחלקו במשנתנו \u0005על פי שיטת]\u0006 \u0003ר' אליעזר\u0004 נחלקו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכשר מבוי,\u0004 שיהא מותר לטלטל בו בשבת — \u0003בית שמאי אומרים:\u0004 כשיש \u0003לחי\u0004 בצידו \u0003וקורה\u0004 מעליו. \u0003ובית הלל אומרים:\u0004 די באחד מהם, \u0003או לחי או קורה. ר' אליעזר אומר:\u0004 כדי שיהא מותר בטלטול צריך שיהיו לו \u0003שני לחיים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה:\u0004 מבוי שיש בו \u0003שלוש מחיצות ולחי אחד \"מפולש\" קרית ליה\u0004 \u0005[קורא אתה לו]?\u0006 שאף אם לא התיר ר' אליעזר טלטול בתוכו, מכל מקום אינו נחשב כמפולש אלא כסתום. \u0003ועוד, לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 אם כן \u0003נציל לתוכו אוכלין ומשקין!\u0004 שהרי התירו חכמים רק במבוי שאינו מפולש, ומבוי זה מותר בטלטול לדעת הכל, ואם כן נתיר להציל לתוכו גם אוכל ומשקה ולא רק ספר תורה. \u0003אלא אמר רבה:\u0004 מבוי שיש בו \u0003שתי מחיצות ושני לחיין\u0004 בשני פתחיו של המבוי — \u0003זהו מבוי שאינו מפולש. שתי מחיצות ולחי אחד\u0004 — \u0003זהו מבוי המפולש.\u0004","\u0003ותרוייהו אליבא\u0004 \u0005[ושניהם על פי שיטת]\u0006 \u0003ר' יהודה\u0004 הלכו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יתר על כן אמר ר' יהודה: מי שיש לו שני בתים בשני צדי רשות הרבים\u0004 ונמצא שיש לו שתי מחיצות — \u0003עושה לחי מיכן\u0004 (מכאן) ליד בית אחד \u0003ולחי מיכן, או קורה מיכן וקורה מיכן, ונושא ונותן באמצע\u0004 בין שני הבתים, שלדעתו שתי מחיצות הן רשות היחיד מן התורה, ועל ידי הלחיים נעשה המקום כמגודר מכל צד והוא רשות היחיד גמורה לשיטתו. \u0003אמרו לו\u0004 חכמים: \u0003אין מערבין רשות הרבים בכך.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003לדידך נמי\u0004 \u0005[לשיטתך גם כן],\u0006 \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 שבמשנתנו, כיון שהם סבורים כר' יהודה והתירו במבוי שאינו מפולש, מדוע לא \u0003נציל לתוכו\u0004 גם \u0003אוכלין ומשקין?\u0004"],["\u0003אלא אמר רב אשי:\u0004 החכמים במשנתנו על פי שיטת ר' אליעזר נחלקו. \u0003שלש מחיצות ולחי אחד\u0004 — \u0003זה מבוי שאינו מפולש. שלש מחיצות בלא לחי\u0004 כלל — \u0003זהו מבוי המפולש. ואפילו לר' אליעזר\u0004 ש\u0003אמר בעינן\u0004 \u0005[צריכים אנו]\u0006 שני \u0003לחיים\u0004 ולא די באחד, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 נאמרו להתיר \u0003ל\u0004טלטל \u0003אוכלין ומשקין, אבל ל\u0004צורך טלטול \u0003ספר תורה\u0004 — \u0003בחד לחי סגי\u0004 \u0005[בלחי אחד דיו].\u0006","\u0003מצילין\u0004 בשבת מן הדליקה \u0003מזון שלש סעודות.\u0004 מזון \u0003הראוי לאדם\u0004 — מצילים בשביל \u0003אדם, הראוי לבהמה\u0004 — \u0003לבהמה. כיצד? נפלה דליקה בלילי שבת\u0004 לפני סעודת ליל שבת — \u0003מצילין\u0004 ממנה \u0003מזון שלש סעודות.\u0004 נפלה הדליקה \u0003בשחרית\u0004 לאחר שכבר אכלו סעודה אחת בליל שבת ולפני סעודת יום השבת — \u0003מצילין\u0004 רק \u0003מזון שתי סעודות, במנחה\u0004 — \u0003מזון סעודה אחת. ר' יוסי אומר: לעולם מצילין מזון שלש סעודות\u0004 שהן השיעור שהתירו חכמים בשבת, ולא חלקו בדבר.","שואלים: \u0003מכדי בהיתרא קטרח, נציל טפי\u0004 \u0005[הלא ב\u0006טלטול של \u0005היתר הוא טורח,\u0006 ואם כן \u0005יציל יותר]!\u0006 ומדוע התירו רק מזון שלוש סעודות? \u0003אמר רבא: מתוך שאדם\u0004 כרגיל \u0003בהול על ממונו, אי שרית ליה\u0004 \u0005[אם תתיר לו]\u0006 להוציא הרבה — \u0003אתי לכבויי\u0004 \u0005[יבוא לכבות]\u0006 את הדליקה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]:\u0006 \u0003נשברה לו\u0004 בשבת \u0003חבית בראש גגו\u0004 — \u0003מביא כלי ומניח תחתיה\u0004 כדי לשמור את המצוי בחבית, \u0003ובלבד שלא יביא כלי אחר\u0004 בקרקע \u0003ויקלוט\u0004 את קילוח המשקה הנשפך מן החבית, וכן לא יביא \u0003כלי אחר, ויצרף,\u0004 שלא יעמידנו סמוך לגג שיכנסו לתוכו המשקים הנוזלים מן החבית. \u0003התם, מאי גזירה איכא\u0004 \u0005[שם, מה גזירה יש\u0006 בדבר\u0005],\u0006 ומדוע אסרו עליו להציל בדרך אחרת? אמר לו: \u0003הכי נמי\u0004 \u0005[כאן\u0006 \u0003גם כן] גזירה\u0004 היא שגזרו מתוך החשש \u0003שמא יביא\u0004 את ה\u0003כלי\u0004 הנוסף \u0003דרך רשות הרבים,\u0004 שהוא טלטול אסור.","כיון שהובאה אותה ברייתא דנים עתה \u0003גופא\u0004 \u0005[לגוף]\u0006 הדברים ששנינו בה: \u0003נשברה לו\u0004 בשבת \u0003חבית בראש גגו\u0004 — \u0003מביא כלי ומניח תחתיה, ובלבד שלא יביא כלי אחר ויקלוט, כלי אחר ויצרף. נזדמן לו אורחין\u0004 וצריך למשקים מרובים — \u0003מביא כלי אחר וקולט, כלי אחר ומצרף. ולא\u0004 ש\u0003יקלוט ואחר כך יזמין\u0004 אורחים, \u0003אלא\u0004 קודם \u0003יזמין\u0004 את האורחים \u0003ואחר כך יקלוט,\u0004 שהרי קודם שמזמינם אינו צריך לכך ועושה כך אם כן באיסור. \u0003ואין מערימין בכך\u0004 להזמין אורחים שלא התכוון להזמינם כדי שיוכל להציל את חביתו. \u0003משום\u0004 (בשם) \u0003ר' יוסי בר יהודה אמרו:\u0004 אף \u0003מערימין.\u0004","ומציעים: \u0003לימא בפלוגתא\u0004 \u0005[האם נאמר\u0006 כי חכמים ור' יוסי בר' יהודה \u0005במחלוקת]\u0006 \u0003ר' אליעזר ור' יהושע קמיפלגי\u0004 \u0005[נחלקו]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אותו ואת בנו\u0004 שתי בהמות, אם ובתה, או בנה, \u0003שנפלו לבור\u0004 ביום טוב, ואסור לשחוט את שתיהן ביום אחד כאמור: \"ושור או שה אותו ואת בנו לא תשחטו ביום אחד\" (ויקרא כב, כח), ורוצים להוציאן מן הבור, כיצד יעשו? — \u0003ר' אליעזר אומר: מעלה את הראשון על מנת לשוחטו, והשני עושה לו פרנסה\u0004 (מאכילו) \u0003במקומו\u0004 בבור \u0003בשביל שלא ימות. ר' יהושע אומר: מעלין את הראשון על מנת לשוחטו ואינו שוחטו. ומערים\u0004 ואומר שנמלך בדעתו והחליט לשחוט את השני, \u0003ומעלה את השני,\u0004 ואז אם \u0003רצה\u0004 לשחוט את \u0003זה,\u0004 הראשון — \u0003שוחט, רצה\u0004 לשחוט את \u0003זה,\u0004 השני — \u0003שוחט.\u0004","ודוחים: אין להשוות את המחלוקות, שכן \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק שיש דמיון? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 שאין מערימים בבהמות, כיון ש\u0003אפשר\u0004 שתחיה הבהמה בלא להערים ועל ידי \u0003פרנסה\u0004 שנותן לו מזון כדי צורכו שלא ימות בינתיים, \u0003אבל הכא דלא\u0004 \u0005[כאן שאי]\u0006 \u0003אפשר\u0004 באופן אחר — שמא \u0003לא\u0004 אמר כך, ומותר אף לדעתו להערים. וכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם],\u0006 שהתיר להערים אלא \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003צער בעלי חיים\u0004 בדבר, \u0003אבל הכא דליכא\u0004 \u0005[כאן, שאין]\u0006 \u0003צער בעלי חיים\u0004 שמא \u0003לא\u0004 התיר להערים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003הציל פת נקיה\u0004 כדי צורכו — \u0003אין\u0004 חוזר ו\u0003מציל פת הדראה\u0004 (פת מקמח מעורב בסובין), אבל אם הציל \u0003פת הדראה\u0004 — חוזר ו\u0003מציל פת נקיה. ומצילין מיום הכפורים ל\u0004צורך \u0003שבת, אבל לא משבת ל\u0004צורך \u0003יום הכפורים. ואין צריך לומר\u0004 שאין מצילים \u0003משבת ליום טוב, ולא משבת ל\u0004צורך ה\u0003שבת הבאה.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שכח פת בתנור\u0004 ולא הוציאה, \u0003ו\u0004כבר \u0003קידש עליו היום\u0004 של שבת — \u0003מצילין\u0004 מן התנור \u0003מזון שלש סעודות, ואומר לאחרים: בואו והצילו לכם\u0004 (עבורכם). \u0003וכשהוא רודה\u0004 מן התנור, \u0003לא ירדה\u0004 כדרכו \u0003במרדה, אלא\u0004 ירדה בשינוי, \u0003וכגון בסכין.\u0004 ומקשים: \u0003איני\u0004 \u0005[וכן היא]?!\u0006 \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"\u0004ויום השביעי שבת לה' אלהיך \u0003לא תעשה כל מלאכה\"\u0004 (שמות כ, י), ובשל הדגשת הכתוב לשון \"מלאכה\" \u0003יצא תקיעת שופר ורדיית הפת שהיא חכמה ואינה מלאכה\u0004 ולא נאסרה בשבת, ואם מדין תורה מותר לרדות בשבת, מדוע אמרו שלא ירדה כדרכו? ומשיבים: אף על פי כן, \u0003כמה\u0004 ש\u0003אפשר לשנויי משנינן\u0004 \u0005[לשנות משנים]\u0006 להדגיש ששבת היום.","\u0003אמר רב חסדא: לעולם ישכים אדם\u0004 בערב שבת \u0003ל\u0004הכין כל \u0003הוצאת שבת, שנאמר\u0004 בענין המן ולקיטתו: \u0003\"והיה ביום הששי והכינו את אשר יביאו\"\u0004 (שמות טז, ה), ומשמע שמכינים את המאכלים לצורך שבת \u0003לאלתר\u0004 עם ליקוט המן בבוקר. וכיון שהוזכר המן מביאים את מה שלמדו עוד מענין המן. ש\u0003אמר ר' אבא: בשבת חייב אדם לבצוע\u0004 בסעודתו \u0003על שתי ככרות, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ויהי ביום הששי לקטו \u0003לחם משנה\u0004 שני העומר לאחד\" (שמות טז, כב).","\u0003אמר רב אשי: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב כהנא דנקט תרתי\u0004 \u0005[ש\u0006הוא \u0005לוקח\u0006 את \u0005שתי\u0006 הככרות\u0005]\u0006 בידו \u0003ובצע חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 ולא את שתיהן יחד. שכן הוא \u0003אמר:\u0004 הרי לשון \u0003\"לקטו\u0004 לחם משנה \u0003\" כתיב\u0004 \u0005[נאמר]\u0006 שיש רק ללקוט, לאחוז, שתי ככרות, אבל לא לבצוע על שתיהם. \u0003ר' זירא הוה בצע אכולה שירותיה\u0004 \u0005[היה בוצע\u0006 פרוסה המספיקה \u0005לכל סעודתו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: והא מיחזי כרעבתנותא\u0004 \u0005[והרי\u0006 זה \u0005נראה כרעבתנות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003כיון\u0004 שב\u0003כל יומא לא עביד\u0004 \u0005[יום אינו עושה]\u0006 כן, \u0003והאידנא\u0004 \u0005[ועכשיו]\u0006 \u0003הוא דקעביד\u0004 \u0005[שעושה]\u0006 — \u0003לא מיחזי כרעבתנותא\u0004 \u0005[אינו נראה כרעבתנות].\u0006 \u0003ר' אמי ור' אסי כי מיקלע להו ריפתא דעירובא\u0004 — \u0003שרו עילויה\u0004 \u0005[כאשר היה מזדמן להם לחם של עירוב\u0006 חצרות — \u0005היו בוצעים עליו]\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 כהסבר לכך: \u0003הואיל ואיתעביד\u0004 \u0005[ונעשתה]\u0006 \u0003בה חדא מצוה\u0004 \u0005[מצוה אחת]\u0006 — \u0003ליתעביד\u0004 \u0005[תיעשה]\u0006 \u0003בה מצוה אחרינא\u0004 \u0005[אחרת,\u0006 נוספת\u0005].\u0006","שנינו במשנה שמצילים מזון שלש סעודות בשבת. \u0003כיצד? נפלה דליקה\u0004 לפני סעודת ליל שבת — מצילים ממנה מזון שלוש סעודות, ביום — מזון שתי סעודות, במנחה — סעודה אחת. ובענין מספר סעודות שבת \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כמה סעודות חייב אדם לאכול בשבת\u0004 — \u0003שלש. ר' חידקא אומר: ארבע. אמר ר' יוחנן: ושניהם מקרא אחד דרשו,\u0004 מן הפסוק \u0003\"ויאמר משה אכלהו היום כי שבת היום לה' היום לא תמצאהו בשדה\"\u0004 (שמות טז, כה). \u0003ר' חידקא סבר\u0004 \u0005[סבור]:\u0006 \u0003הני תלתא\u0004 \u0005[אותן שלוש\u0006 פעמים\u0005]\u0006 שנאמר \u0003\"היום\"\u0004 לרמז על מספר סעודות השבת באו, וכל זה \u0003לבר מאורתא\u0004 \u0005[חוץ\u0006 מסעודת \u0005הערב],\u0006 שהרי אמר משה דבר זה בבקרו של יום השבת. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 שהכוונה היא \u0003בהדי דאורתא\u0004 \u0005[עם,\u0006 כולל \u0005הערב].\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 אם \u0003נפלה\u0004 ה\u0003דליקה בלילי שבת\u0004"],["\u0003מצילין\u0004 ממנה \u0003מזון שלש סעודות, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003שעדיין לא אכל\u0004 מאומה, ונמצא שחייבים רק בשלוש סעודות ביום השבת! ודוחים: \u0003לא,\u0004 מדובר באופן ש\u0003אכל\u0004 כבר סעודה אחת ועדיין נשארו שלוש, וכר' חידקא. ועוד מקשים ממה ששנינו בהמשך: אם פרצה הדליקה בביתו ב\u0003שחרית\u0004 יום השבת — \u0003מצילין מזון שתי סעודות, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003שעדיין לא אכל\u0004 סעודת שחריתו, ונמצא אם כן שחייבים רק בשלוש סעודות, אחת בלילה ושתים ביום? ודוחים: \u0003לא,\u0004 מדובר באופן ש\u0003אכל\u0004 כבר את סעודת שחרית. ושוב מקשים ממה ששינו שם עוד: אם פרצה הדליקה \u0003במנחה\u0004 — \u0003מצילין מזון סעודה אחת, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003שעדיין לא אכל\u0004 את סעודת המנחה, ונמצא אם כן שהחובה היא בשלוש סעודות בלבד! ודוחים: \u0003לא,\u0004 מדובר באופן ש\u0003אכל\u0004 כבר.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו בסופה\u0006 של המשנה\u0005]\u0006 ש\u0003ר' יוסי אומר: לעולם מצילין מזון שלש סעודות, מכלל\u0004 הדברים אתה למד שאף ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ככלל \u0003שלש\u0004 סעודות \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שצריך, שהרי לא נחלקו במספר הסעודות לשבת! \u0003אלא מחוורתא, מתניתין דלא\u0004 \u0005[מחוור\u0006 ש\u0005משנתנו אינה]\u0006 \u0003כר' חידקא,\u0004 שלדעת התנאים במשנתנו צריך \u0003לאכול בשבת שלוש סעודות.\u0004","\u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003מי שיש לו מזון שתי סעודות\u0004 ברשותו — \u0003לא יטול מן התמחוי\u0004 שמחלקים ממנו מאכל לעניים, לפי שאינו נזקק עד כדי כך ונמצא שנוטל מן הנצרך יותר ממנו. ומי שיש לו \u0003מזון ארבע עשרה\u0004 סעודות שהן הסעודות המספיקות לשבוע שלם — \u0003לא יטול מן הקופה\u0004 של צדקה. ומעתה יש לשאול: \u0003מני\u0004 \u0005[\u0006של \u0005מי היא]\u0006 משנה זו? לכאורה \u0003לא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, \u0003ולא\u0004 שיטת \u0003ר' חידקא.\u0004 שכן \u0003אי רבנן\u0004 \u0005[אם\u0006 שיטת \u0005חכמים]\u0006 היא — הלא לדעתם \u0003חמסרי הויין\u0004 \u0005[חמש עשרה\u0006 סעודות \u0005הן]\u0006 בשבוע, שתי סעודות בכל יום, בערב ובבוקר, ובשבת סעודה נוספת. \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' חידקא\u0004 היא — הלא \u0003שית סרי הויין\u0004 \u0005[שש עשרה הן],\u0006 שתים עשרה של ימות השבוע וארבע של שבת. ודוחים: \u0003לעולם\u0004 תאמר שכשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא משנה זו, אלא \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]:\u0006 \u0003מאי דבעית למיכל באפוקי שבתא, אכליה בשבתא\u0004 \u0005[מה שרוצה אתה לאכול במוצאי השבת אכול אותו בשבת],\u0006 שאת סעודת הערב של יום ראשון יקדים במקצת, ונמצא שאכל שלוש סעודות בשבת.","ושואלים: \u0003לימא רבנן\u0004 \u0005[האם נאמר\u0006 שמשנה זו כשיטת \u0005חכמים]\u0006 \u0003היא ולא\u0004 כשיטת \u0003ר' חידקא?\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[\u0006יכול אתה \u0005לומר]\u0006 כי \u0003שיטת ר' חידקא\u0004 היא, \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]:\u0006 \u0003מאי דבעית למיכל במעלי שבתא, אכליה לאורתא\u0004 \u0005[מה שרוצה אתה לאכול בערב שבת\u0006 ביום, \u0005אכול אותו בערב]\u0006 בליל שבת, ונמצא שאכל ארבע סעודות בשבת. ומקשים: \u0003וכולי יומא דמעלי שבתא בתעניתא מותבינן ליה\u0004 \u0005[ו\u0006האם את \u0005כל היום של ערב שבת בתענית אנו מושיבים אותו]?!\u0006 שלפי הצעה זו לא יאכל בערב שבת כל היום כולו! \u0003אלא\u0004 יש לומר כי \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 של \u0005מי היא]\u0006 — כשיטת \u0003ר' עקיבא היא\u0004 ש\u0003אמר : עשה שבתך חול ואל תצטרך לבריות.\u0004 כלומר, מוטב שינהג אדם ביום השבת כביום חול ולא יזדקק לצדקה. ולכן, אדם שיש בידו מזון של שתי סעודות לשבת כביום חול — אין ראוי שיקח מן הצדקה לכבוד שבת.","\u0003והא דתנן\u0004 \u0005[ו\u0006משנה \u0005זו ששנינו]\u0006 בה: \u0003אין פוחתין\u0004 מליתן צדקה \u0003לעני העובר ממקום למקום מככר\u0004 השוה \u0003פונדיון\u0004 (אחד מארבעים ושמונה בסלע) כאשר שער התבואה הוא שנמכרים \u0003ארבע סאין בסלע. לן\u0004 במקום — \u0003נותנין לו פרנסת לינה, ואם שבת\u0004 באותה עיר — \u0003נותנין לו מזון שלש סעודות. לימא רבנן\u0004 \u0005[האם נאמר\u0006 כי שיטת \u0005חכמים]\u0006 \u0003היא ולא\u0004 שיטת \u0003ר' חידקא?!\u0004 ודוחים: \u0003לעולם\u0004 אפשר לומר ששיטת \u0003ר' חידקא\u0004 היא, ומה שנאמר שאם שבת בעיר נותנים לו מזון שלוש סעודות הרי זה מדובר ב\u0003כגון דאיכא\u0004 \u0005[שיש]\u0006 \u0003סעודה\u0004 אחת שהביא \u0003בהדיה\u0004 \u0005[עמו],\u0006 \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]:\u0006 \u0003הא דאיכא בהדך\u0004 \u0005[\u0006סעודה \u0005זו שישנה אתך]\u0006 — \u0003אכליה\u0004 \u0005[אכול אותה].\u0006 ותוהים: אם כן \u0003וכי אזיל\u0004 \u0005[וכאשר ילך]\u0006 \u0003בריקן אזיל\u0004 \u0005[ילך]\u0006 בלא אוכל?! ועונים: \u0003דמלווינן ליה\u0004 \u0005[שאנו נותנים לו]\u0006 עם צאתו \u0003סעודה\u0004 שיקח \u0003בהדיה\u0004 \u0005[אתו].\u0006 הוזכרה \u0003פרנסת לינה, אמר רב פפא:\u0004 משמעה שנותנים לו לצרכי לינה \u0003פוריא ובי סדיא\u0004 \u0005[מיטה וכרים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003קערות שאכל בהן ערבית\u0004 בשבת — \u0003מדיחן\u0004 כדי \u0003לאכול בהן שחרית.\u0004 אכל בהם \u0003שחרית\u0004 — \u0003מדיחן\u0004 כדי \u0003לאכול בהן בצהרים.\u0004 אכל \u0003בצהרים\u0004 — \u0003מדיחן לאכול בהן במנחה.\u0004 ואולם \u0003מן המנחה ואילך\u0004 — \u0003שוב אינו מדיח\u0004 כיון שאין צורך עוד בקערות אלה לשבת, ואין עושים הכנה משבת לחול. \u0003אבל כוסות וקיתוניות\u0004 (ספלים קטנים) \u0003וצלוחיות\u0004 שכולן כלי שתיה — \u0003מדיח והולך כל היום כולו, לפי שאין קבע לשתיה\u0004 ואין אדם יודע מתי יזדמן לו לשתות פעם נוספת אותו יום.","\u0003אמר ר' שמעון בן פזי\u0004 שכך \u0003אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: כל המקיים שלש סעודות בשבת ניצול משלש פורעניות: מחבלו של משיח\u0004 (היסורים הבאים לפני ביאת המשיח), \u0003ומדינה של גיהנם, וממלחמת גוג ומגוג.\u0004 ומקור לדברים: \u0003מחבלו של משיח\u0004 — דבר זה נלמד מהשוואת הכתובים, שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין שבת \u0003\"יום\",\u0004 כאמור: \"אכלוהו היום\", \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \"יום\", כאמור: \u0003\"הנה אנכי שלח לכם את אליה הנביא לפני בוא יום\u0004 ה' הגדול והנורא\u0003\"\u0004 (מלאכי ג, כג). \u0003מדינה של גיהנם\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בשבת \u0003\"יום\"\u0004 כאמור, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \"יום\", כאמור: \u0003\"יום עברה היום ההוא\u0004 יום צרה ומצוקה יום שואה ומשואה יום חושך ואפלה יום ענן וערפל\u0003\"\u0004 (צפניה א, טו), המתפרש כמכוון לעונש הגיהנם. \u0003ממלחמת גוג ומגוג\u0004 — שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין שבת \u0003\"יום\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \"יום\", כאמור: \"והיה ביום ההוא \u0003ביום בוא גוג\u0004 על אדמת ישראל\" (יחזקאל לח, יח).","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי: כל המענג את השבת נותנין לו נחלה בלי מצרים\u0004 (גבולות), כלומר, נחלה (שכר) גדולה מאד, \u0003שנאמר:\u0004 \"אם תשיב משבת רגליך עשות חפצך ביום קדשי וקראת לשבת עונג לקדוש ה' מכובד וכיבדתו מעשות דרכיך ממצוא חפצך ודבר דבר. \u0003אז תתענג על ה' והרכבתיך על במתי ארץ והאכלתיך\u0004"],["\u0003נחלת יעקב אביך\u0004 כי פי ה' דבר\" (ישעיה נח, יג-יד) ודוקא נחלת יעקב, \u0003לא כאברהם שכתוב בו: \"קום התהלך בארץ לארכה\u0004 ולרחבה כי לך אתננה\u0003\"\u0004 (בראשית יג, יז), כלומר, רק ארץ זו בגבולותיה. \u0003ולא כיצחק שכתוב בו: \"\u0004גור בארץ הזאת ואהיה עמך ואברכך \u0003כי לך ולזרעך אתן את כל הארצת האל\"\u0004 (בראשית כו, ג), שמשמעו — ארצות אלה ולא יותר. \u0003אלא כיעקב שכתוב בו:\u0004 \"והיה זרעך כעפר הארץ \u0003ופרצת ימה וקדמה וצפונה ונגבה\u0004 ונברכו בך כל משפחות האדמה ובזרעך\" (בראשית כח, יד) שהיא נחלה שלא ניתנו לה גבולות כלל.","\u0003רב נחמן בר יצחק אמר:\u0004 המענג את השבת \u0003ניצול משעבוד גליות.\u0004 ומנין? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בשבת: \u0003\"והרכבתיך על במתי ארץ\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"\u0004אשריך ישראל מי כמוך עם נושע בה' מגן עזרך ואשר חרב גאותך ויכחשו אויביך לך \u0003ואתה על במותימו תדרך\"\u0004 (דברים לג, כט). \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: כל המענג את השבת נותנין לו משאלות לבו,\u0004 וכפי \u0003שנאמר: \"והתענג על ה' ויתן לך משאלת לבך\"\u0004 (תהלים לז, ד), ועדיין \u0003עונג זה\u0004 על ה' שנאמר בפסוק \u0003איני יודע מהו,\u0004 ולכן \u0003כשהוא אומר \"וקראת לשבת ענג\"\u0004 — \u0003הוי אומר זה ענג שבת.\u0004 ושואלים: \u0003במה מענגו\u0004 ליום השבת? \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר: בתבשיל של תרדין, ודגים גדולים, וראשי שומין. רב חייא בר אשי אמר\u0004 בשם \u0003רב: אפילו דבר מועט\u0004 אם \u0003לכבוד שבת עשאו\u0004 — \u0003הרי זה עונג.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 דבר מועט זה? \u0003אמר רב פפא: כסא דהרסנא\u0004 \u0005[דגים קטנים מטוגנים].\u0006","\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: כל המשמר שבת כהלכתו, אפילו\u0004 הוא \u0003עובד עבודה זרה כדור אנוש\u0004 (שנאמר בו \"אז הוחל לקרוא בשם ה'\" — לחלל שמו) \u0003מוחלין לו,\u0004 וכפי \u0003שנאמר: \"אשרי אנוש יעשה זאת\u0004 ובן אדם יחזיק בה שומר שבת \u0003מחללו\u0004 ושומר ידו מעשות כל רע\u0003\"\u0004 (ישעיה נו, ב), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"מחללו\" אלא: \"מחול לו\".\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: אלמלי שמרו ישראל\u0004 כראוי את ה\u0003שבת\u0004 ה\u0003ראשונה\u0004 שניתנה להם, \u0003לא שלטה בהן אומה ולשון\u0004 מאז. \u0003שנאמר: \"ויהי ביום השביעי יצאו מן העם ללקט\u0004 ולא מצאו\u0003\"\u0004 (שמות טז, כז), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו],\u0006 אחר שיצאו ללקוט באיסור: \u0003\"ויבא עמלק\u0004 וילחם עם ישראל ברפידים\u0003\"\u0004 (שמות יז, ח). \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: אלמלי משמרין ישראל שתי שבתות כהלכתן\u0004 — \u0003מיד\u0004 הם \u0003נגאלים,\u0004 וכפי \u0003שנאמר: \"כה אמר ה' לסריסים אשר ישמרו את שבתותי\"\u0004 (ישעיה נו, ד), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"והביאותים אל הר קדשי\u0004 ושמחתים בבית תפילתי\u0003\"\u0004 (ישעיה נו, ז).","\u0003אמר ר' יוסי: יהא חלקי מאוכלי שלש סעודות בשבת.\u0004 וכיון שהוזכרו דברי ר' יוסי מביאים עוד כמה מדבריו שנאמרו בסגנון דומה. \u0003אמר ר' יוסי: יהא חלקי מגומרי הלל בכל יום.\u0004 ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003הקורא הלל בכל יום הרי זה מחרף ומגדף,\u0004 שמזלזל בהלל ומראה כאילו אין ההלל מיוחד ליום שנעשה בו נס! ומשיבים: \u0003כי קאמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 דברים אלה בשם ר' יוסי — ל\u0003פסוקי דזמרא\u0004 התכוונו. שאומרים בתפילת שחרית שיש בהם דברי הלל להשם, ולא ל\"הלל\" (תהילים קיג־קיח) שאומרים רק בימים המיוחדים.","ועוד \u0003אמר ר' יוסי: יהא חלקי ממתפללים\u0004 שחרית ומנחה \u0003עם דמדומי חמה,\u0004 כלומר, תפילת שחרית השכם בבוקר ותפלת מנחה קרוב ללילה. \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: מצוה להתפלל עם דמדומי חמה. אמר ר' זירא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 הרומז לכך? — \u0003\"ייראוך עם שמש ולפני ירח דור דורים\"\u0004 (תהלים עב, ה), כלומר, יראת השם (\"ייראוך\"), התפילה, תהא עם זריחת השמש ולפני הירח.","\u0003ואמר ר' יוסי: יהא חלקי ממתי\u0004 (מהמתים) \u0003בחולי מעיים.\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003רובן של\u0004 ה\u0003צדיקים מתים בחולי מעיים,\u0004 שמיתה זו אינה קלה ומתמרקים עוונותיהם לפני מיתתם, ועוד, שהם מתים בגוף נקי. \u0003ואמר ר' יוסי: יהא חלקי ממתי בדרך מצוה,\u0004 כלומר, כשהולך בשליחות לדבר מצוה. \u0003ואמר ר' יוסי: יהא חלקי ממכניסי שבת בטבריא\u0004 (טבריה), שכיון שהיא בעמק מעריב בה היום מוקדם יותר, \u0003וממוציאי שבת בצפורי,\u0004 שהיא בראש ההר והשמש נראית בה זמן רב יותר, ומשום כך יוצאת בה השבת יותר מאוחר מבשאר מקומות. \u0003ואמר ר' יוסי: יהא חלקי ממושיבי בית המדרש,\u0004 אותם האוספים את העם לבוא ולשבת ללמוד \u0003ולא ממעמידי בית המדרש,\u0004 אותם המודיעים שנגמרה שעת הלימוד, ואפשר ללכת לאכול.","\u0003ואמר ר' יוסי: יהא חלקי מגבאי צדקה ולא ממחלקי צדקה,\u0004 שהגובה את הצדקה עושה זאת לפי השיעור הראוי, ואילו מחלק הצדקה יתכן שלא יתן לכל עני כדי מחסורו. \u0003ואמר ר' יוסי: יהא חלקי ממי שחושדין אותו\u0004 ברע \u0003ואין בו. אמר רב פפא: לדידי חשדן\u0004 \u0005[בי חשדו]\u0006 \u0003ולא הוה\u0004 \u0005[היה]\u0006 \u0003בי.\u0004","ועוד \u0003אמר ר' יוסי: חמש בעילות בעלתי, ונטעתי חמשה ארזים בישראל. ומאן אינון\u0004 \u0005[ומי הם]\u0006 אותם ארזים גדולי ישראל — בניו של ר' יוסי, \u0003ר' ישמעאל בר' יוסי, ור' אלעזר בר' יוסי, ור' חלפתא בר' יוסי, ור' אבטילס בר' יוסי, ור' מנחם בר' יוסי.\u0004 ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם את בנו של ר' יוסי \u0003ורדימס!\u0004 ועונים: \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003ורדימס היינו\u0004 \u0005[זהו]\u0006 \u0003מנחם. ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"ורדימס\"?\u0004 — לפי \u0003שפניו דומין לורד\u0004 ביופיים. ומקשים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 ונלמד מדברים אלה ש\u0003ר' יוסי מצות עונה\u0004 עם אשתו לא קיים, אלא בעל רק חמש בעילות?! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003חמש בעילות בעלתי ושניתי,\u0004 ואמרו חכמים שהבועל ושונה יוולדו לו על ידי כך בנים זכרים.","ועוד \u0003אמר ר' יוסי\u0004 שדרכו בלשון נקיה: \u0003מימי לא קריתי לאשתי \"אשתי\" ולשורי \"שורי\", אלא\u0004 קראתי \u0003לאשתי\u0004 — \u0003\"ביתי\"\u0004 שהיא עיקרה של הבית, \u0003ולשורי\u0004 — \u0003\"שדי\"\u0004 שבכוחו עיקר עיבוד השדות.","\u0003אמר ר' יוסי: מימי לא נסתכלתי במילה שלי\u0004 מחמת צניעות. ושאלו: \u0003איני\u0004 \u0005[וכי כן הוא ]?\u0006 \u0003והאמרו ליה\u0004 \u0005[והרי אמרו לו]\u0006 \u0003לרבי,\u0004 ר' יהודה הנשיא: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003קראו לך \"רבינו הקדוש\"? אמר להו\u0004 \u0005[להם]:\u0006 \u0003מימי לא נסתכלתי במילה שלי.\u0004 ואם כן מדוע לא קראו גם לר' יוסי \"רבינו הקדוש\"? ועונים: \u0003ברבי מילתא אחריתי הוה ביה\u0004 \u0005[דבר אחר\u0006 של צניעות \u0005היה בו],\u0006 \u0003שלא הכניס ידו תחת אבנטו\u0004 מרוב צניעות. \u0003ואמר ר' יוסי:\u0004 מחמת צניעות \u0003מימי לא ראו קורות ביתי אימרי\u0004 (שולי) \u0003חלוקי,\u0004 שלא היה מתפשט בגלוי תחת קורת הגג אלא תחת מצעי המיטה.","\u0003ואמר ר' יוסי: מימי לא עברתי על דברי חברי. יודע אני בעצמי שאיני כהן,\u0004 ובכל זאת, \u0003אם אומרים לי חבירי: עלה לדוכן\u0004 עם הכהנים — \u0003אני עולה,\u0004 על אף החשש שבדבר. \u0003ואמר ר' יוסי: מימי לא אמרתי דבר, וחזרתי לאחורי,\u0004 כלומר מימי לא אמרתי דבר וחזרתי בי לאמור: לא אמרתיו, בין שהיה דבר טוב על אדם מסויים ובין שהיה דבר של גנאי.","\u0003אמר רב נחמן: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי,\u0004 כלומר, ישולם שכרי משום \u0003דקיימית\u0004 \u0005[שקיימתי]\u0006 בהידור \u0003שלש סעודות בשבת. אמר רב יהודה: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 שכרי \u0003דקיימית\u0004 \u0005[שקיימתי]\u0006 בהידור \u0003עיון תפלה,\u0004 שדקדקתי בדבר. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 שכרי משום ש\u0003לא סגינא\u0004 \u0005[הלכתי]\u0006 \u0003ארבע אמות בגילוי הראש. אמר רב ששת: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 שכרי \u0003דקיימית\u0004 \u0005[שקיימתי]\u0006 בהידור \u0003מצות תפילין. ואמר רב נחמן: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 שכרי \u0003דקיימית\u0004 \u0005[שקיימתי]\u0006 בהידור \u0003מצות ציצית.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לרב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה: אבוך, במאי\u0004 \u0005[אביך,\u0006 רבה, \u0005במה]\u0006 היה \u0003זהיר טפי\u0004 \u0005[ביותר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ב\u0004מצות \u0003ציצית.\u0004 ומסופר: \u0003יומא חד הוה קא סליק בדרגא\u0004 \u0005[יום אחד היה עולה במדרגות].\u0006 \u0003איפסיק ליה חוטא\u0004 \u0005[נפסק,\u0006 נקרע, \u0005לו חוט]\u0006 אחד מחוטי הציצית, \u0003ולא נחית ואתא, כמה\u0004 \u0005[ירד ובא \u0006, עד] ש\u0003לא רמיה\u0004 \u0005[הטיל\u0006 בו\u0005]\u0006 חוט ציצית חדש. \u0003ואמר אביי: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 שכרי משום \u0003דכי חזינא צורבא מרבנן דשלים מסכתיה\u0004 \u0005[שכאשר אני רואה תלמיד חכם המשלים את המסכת\u0006 שלמד\u0005]\u0006"],["\u0003עבידנא יומא טבא לרבנן\u0004 \u0005[עושה אני יום טוב\u0006 סעודה \u0005לחכמים].\u0006 \u0003אמר רבא תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 שכרי, \u0003דכי אתא צורבא מרבנן לקמאי לדינא\u0004 \u0005[שכאשר בא תלמיד חכם לפני לדין],\u0006 \u0003לא מזיגנא רישי אבי סדיא, כמה דלא מהפיכנא בזכותיה\u0004 \u0005[איני מניח ראשי על הכר, עד שאינני מהפך בזכותו]\u0006 עד כמה שאפשר, לפי התנאים ולפי טענותיו. \u0003אמר מר בר רב אשי: פסילנא ליה לצורבא מרבנן לדינא\u0004 \u0005[פסול אני לתלמיד חכם לדון\u0006 אותו\u0005].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 פסול אני? — לפי שהוא \u0003חביב עלי כגופאי\u0004 \u0005[כגופי],\u0006 \u0003ואין אדם רואה חובה לעצמו.\u0004","ומעתה חוזרים לענין עונג שבת וכיבודה. \u0003ר' חנינא מיעטף וקאי אפניא דמעלי שבתא\u0004 \u0005[היה מתעטף ועומד עם חשכה ערב שבת],\u0006 \u0003אמר\u0004 \u0005[\u0006ו\u0005היה אומר]:\u0006 \u0003\"בואו ונצא לקראת שבת המלכה\". ר' ינאי לביש מאניה מעלי\u0004 \u0005[היה לובש בגדיו\u0006 ב\u0005ערב]\u0006 \u0003שבת, ואמר\u0004 \u0005[והיה אומר]:\u0006 \u0003\"בואי כלה בואי כלה\".\u0004 ומסופר: \u0003רבה בר רב הונא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבה בר רב נחמן. קריבו ליה תלת סאוי טחיי\u0004 \u0005[הביאו לו,\u0006 לפניו \u0005שלושה סאים רקיקים משוחים].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי הוה ידעיתון דאתינא\u0004 \u0005[האם ידעתם שאני בא]\u0006 והכנתם כל זה לכבודי? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מי עדיפת לן מינה\u0004 \u0005[האם אתה עדיף לנו ממנה,\u0006 מן השבת\u0005]?\u0006 ורקיקים אלה לכבוד שבת הוכנו.","\u0003ר' אבא זבן בתליסר אסתירי פשיטי בישרא מתליסר טבחי\u0004 \u0005[קנה\u0006 לכבוד שבת \u0005בשלוש עשרה מעות בשר משלושה עשר טבחים]\u0006 כדי שיהיה לו בשר מכל הסוגים ומן המובחר, \u0003ומשלים להו אצינורא דדשא\u0004 \u0005[והיה מניח אותם\u0006 את מיני הבשר \u0005על פתח הבית]\u0006 וממהר להביא בשר אחר. \u0003ואמר להו\u0004 \u0005[להם]\u0006 למבשלים כדי \u0003לזרזם: \"אשור הייא, אשור הייא\"\u0004 \u0005[\u0006\"\u0005מהרו ועשו, מהרו ועשו\"].\u0006 ומסופר עוד: \u0003ר' אבהו הוה יתיב אתכתקא דשינא ומושיף נורא\u0004 \u0005[\u0006היה \u0005יושב על כסא שן ונופח באש]\u0006 לבישול מאכלי השבת כדי לשתף את עצמו בהכנות השבת. \u0003רב ענן לביש גונדא\u0004 \u0005[\u0006היה \u0005לובש בגד שחור\u0006 פשוט\u0005]\u0006 מיוחד לכבוד הכנות שבת, \u0003דתנא דבי\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בגדים שבישל בהן קדירה לרבו\u0004 — \u0003אל ימזוג בהן כוס לרבו,\u0004 ונמצא שבעת ההתעסקות במלאכות שאינן חשובות יש ללבוש בגדים מתאימים לכך.","\u0003רב ספרא מחריך רישא\u0004 \u0005[\u0006היה \u0005חורך ראש\u0006 בהמה\u0005]\u0006 שמכינים לאכילה בשבת. \u0003רבא מלח\u0004 לכבוד שבת את הדג הנקרא \u0003שיבוטא. רב הונא\u0004 היה \u0003מדליק שרגי\u0004 \u0005[נרות]\u0006 לכבוד שבת. \u0003רב פפא גדיל פתילתא\u0004 \u0005[\u0006היה \u0005טווה\u0006 את \u0005הפתילות]\u0006 לנרות שבת. \u0003רב חסדא פרים סילקא\u0004 \u0005[\u0006היה \u0005חותך\u0006 את \u0005התרד]\u0006 להכנת שבת. \u0003רבה ורב יוסף מצלחי ציבי\u0004 \u0005[\u0006היו \u0005חותכים עצים].\u0006 \u0003ר' זירא מצתת צתותי\u0004 \u0005[\u0006היה \u0005מכין עצים דקים\u0006 להדלקה\u0005].\u0006 \u0003רב נחמן בר יצחק\u0004 היה \u0003מכתף\u0004 על כתפו דברים \u0003ועייל\u0004 \u0005[ונכנס],\u0006 \u0003מכתף ונפיק\u0004 \u0005[ויוצא].\u0006 \u0003אמר: אילו מקלעין לי\u0004 \u0005[היו מזדמנים,\u0006 באים \u0005אלי]\u0006 \u0003ר' אמי ור' אסי מי\u0004 \u0005[האם]\u0006 \u0003לא מכתיפנא קמייהו\u0004 \u0005[הייתי מכתף לפניהם]?\u0006 וכן ראוי לעשות לכבוד שבת. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003ר' אמי ור' אסי מכתפי ועיילי, מכתפי ונפקי\u0004 \u0005[היו מכתפים\u0006 \u0003ונכנסים, מכתפים ויוצאים]. אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אילו איקלע לן\u0004 \u0005[הזדמן,\u0006 בא \u0005אלינו]\u0006 \u0003ר' יוחנן, מי\u0004 \u0005[האם]\u0006 \u0003לא מכתפינן קמיה\u0004 \u0005[היינו מכתפים לפניו]?!\u0006","מסופר: \u0003יוסף מוקיר שבי\u0004 \u0005[מכבד השבתות],\u0006 \u0003הוה ההוא גוי בשבבותיה דהוה נפישי נכסיה טובא\u0004 \u0005[היה גוי אחד בשכנותו שהיו מרובים נכסיו ביותר].\u0006 \u0003אמרי ליה כלדאי\u0004 \u0005[אמרו לו החוזים בכוכבים]\u0006 לאותו גוי: \u0003כולהו נכסי\u0004 \u0005[כל הכנסים\u0006 שלך\u0005]\u0006 — \u0003יוסף מוקר שבי אכיל להו\u0004 \u0005[מכבד השבתות יאכל,\u0006 יקבל \u0005אותם].\u0006 \u0003אזל זבנינהו לכולהו ניכסי\u0004 \u0005[הלך\u0006 הגוי \u0005ומכר את כל נכסיו],\u0006 ובכסף שקיבל תמורתם \u0003זבן בהו מרגניתא, אותבה בסייניה\u0004 \u0005[קנה בהם מרגלית,\u0006 ו\u0005הניחה בכובעו].\u0006 \u0003בהדי דקא עבר מברא\u0004 — \u0003אפרחיה זיקא, שדייה במיא, בלעיה כוורא\u0004 \u0005[כאשר עבר במעבורת הפריח אותו,\u0006 את כובעו, \u0005הרוח, השליכו במים,\u0006 ו\u0005בלעו דג].\u0006 \u0003אסקוה, אייתוה אפניא דמעלי שבתא\u0004 \u0005[הוציאוהו,\u0006 ו\u0005הביאוהו\u0006 לאותו דג \u0005עם חשיכה בערב שבת].\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003מאן זבין כי השתא\u0004 \u0005[מי קונה\u0006 בשעה \u0005כמו זו]?\u0006 \u0003אמרי להו\u0004 \u0005[אמרו להם]\u0006 לדייגים: \u0003זילו אמטיוהו לגבי\u0004 \u0005[לכו הביאוהו אצל]\u0006 \u0003יוסף מוקר שבי\u0004 \u0005[מכבד השבתות]\u0006 שהוא \u0003רגיל דזבין\u0004 \u0005[לקנות]\u0006 הרבה לכבוד שבת. \u0003אמטיוה ניהליה, זבניה\u0004 \u0005[הביאוהו אליו,\u0006 ו\u0005קנאו],\u0006 \u0003קרעיה אשכח ביה מרגניתא\u0004 \u0005[קרע אותו,\u0006 ו\u0005מצא בו מרגלית].\u0006 \u0003זבניה בתליסר עיליתא דדינרי דדהבא\u0004 \u0005[מכר אותה בשלושה עשר כלים מלאים דינרי זהב]\u0006 (תוספות). \u0003פגע ביה ההוא סבא\u0004 \u0005[פגש בו זקן אחד]\u0006 ו\u0003אמר: מאן דיזיף שבתא\u0004 — \u0003פרעיה שבתא\u0004 \u0005[מי שלווה לשבת\u0006 — \u0005השבת פורעת לו].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבי מר' ישמעאל בר' יוסי: עשירים שבארץ ישראל במה הן זוכין\u0004 לעושרם? \u0003אמר לו: בשביל שמעשרין,\u0004 וכפי \u0003שנאמר: \"עשר תעשר\u0004 את כל תבואת זרעך היוצא השדה שנה שנה\u0003\"\u0004 (דברים יד, כב), ודרשו חכמים: \u0003עשר בשביל שתתעשר.\u0004 ושאל: עשירים \u0003שבבבל\u0004 שאין בה חובת מעשר מן התבואה \u0003במה הן זוכין? אמר לו: בשביל שמכבדין את התורה\u0004 ואת החכמים שבבבל.","\u0003ו\u0004עשירים \u0003שבשאר ארצות\u0004 שאין חכמי תורה מצויים בהן \u0003במה הן זוכין? אמר לו: בשביל שמכבדין את השבת.\u0004 וכפי ש\u0003אמר ר' חייא בר אבא: פעם אחת נתארחתי אצל בעל הבית בלודקיא, והביאו לפניו שלחן של זהב\u0004 כבד מאד כדי \u0003משוי\u0004 (משא) \u0003ששה עשר בני אדם, ושש עשרה שלשלאות של כסף קבועות בו, וקערות וכוסות וקיתוניות וצלוחיות קבועות בו, ועליו כל מיני מאכל וכל מיני מגדים ובשמים. וכשמניחים אותו\u0004 היו \u0003אומרים: \"לה' הארץ ומלואה\u0004 תבל ויושבי בה\u0003\"\u0004 (תהילים כד, א), \u0003וכשמסלקין אותו\u0004 היו \u0003אומרים: \"השמים שמים לה' והארץ נתן לבני אדם\"\u0004 (תהלים קטו טז). \u0003אמרתי לו: בני במה זכית לכך? אמר לי: קצב\u0004 (שוחט) \u0003הייתי, ומכל בהמה שהיתה נאה, אמרתי: זו תהא לשבת. אמרתי לו: אשריך שזכית, וברוך המקום\u0004 (השם) \u0003שזיכך לכך.\u0004","\u0003אמר לו קיסר לר' יהושע בן חנניא: מפני מה תבשיל של שבת ריחו נודף\u0004 וערב? \u0003אמר לו: תבלין אחד יש לנו ושבת שמו, שאנו מטילין לתוכו וריחו נודף. אמר לו: תן לנו הימנו. אמר לו: כל המשמר את השבת\u0004 — \u0003מועיל לו\u0004 תבלין זה, \u0003ושאינו משמר את השבת\u0004 — \u0003אינו מועיל לו.\u0004","\u0003אמר ליה ריש גלותא\u0004 \u0005[אמר לו ראש הגולה]\u0006 \u0003לרב המנונא: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 \u0003ו\"לקדוש ה' מכבד\"\u0004 (ישעיה נח, יג)? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב המנונא: \u0003זה יום הכפורים, שאין בו לא אכילה ולא שתיה,\u0004 ומאחר וכן \u0003אמרה\u0004 ה\u0003תורה: כבדהו\u0004 אם כן \u0003בכסות נקיה.\u0004 ומה שנאמר בשבת \u0003\"וכבדתו\", רב אמר: להקדים\u0004 סעודת השבת מבשאר ימים כדי להראות שהוא מתענג באכילה, \u0003ושמואל אמר: לאחר\u0004 את סעודת השבת כדי שיגבר תיאבונו. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003בני רב פפא בר אבא לרב פפא: כגון אנן דשכיח לן בישרא וחמרא כל יומא, במאי נישנייה\u0004 \u0005[אנחנו שמצוי לנו בשר ויין כל יום, במה נשנה אותו\u0006 בשבת\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי רגיליתו לאקדומי\u0004 \u0005[אם רגילים אתם\u0006 כרגיל \u0005להקדים]\u0006 את סעודתכם — בשבת \u0003אחרוה\u0004 \u0005[אחרו אותה],\u0006 \u0003אי רגיליתו לאחרוה\u0004 \u0005[אם רגילים אתם\u0006 כרגיל \u0005לאחר אותה]\u0006 — בשבת \u0003אקדמוה\u0004 \u0005[הקדימוה],\u0006 ויהא שבכך שינוי ניכר ביום השבת. ומסופר: \u0003רב ששת בקיטא מותיב להו לרבנן היכא דמטיא שימשא\u0004 \u0005[בקיץ היה מושיב את החכמים\u0006 השומעים דבריו \u0005במקום שמגיעה אליהם השמש].\u0006 \u0003בסיתוא מותיב להו לרבנן היכא דמטיא טולא\u0004 \u0005[בחורף היה מושיב את החכמים במקום שמגיע הצל]\u0006 \u0003כי היכי דליקומו הייא\u0004 \u0005[כדי שיקומו בזריזות]\u0006 לאחר גמר שיעורם, ולא יתעכבו לשאת ולתת בדברים וייבטלו מעונג שבת. \u0003ר' זירא\u0004"],["\u0003מהדר אזוזי זוזי דרבנן\u0004 \u0005[היה מחזר אחר זוגות זוגות חכמים]\u0006 המשוחחים ביניהם בשבת ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003במטותא מינייכו לא תחללוניה\u0004 \u0005[בבקשה מכם אל תחללוהו]\u0006 את יום השבת, שאין ראוי לבטל את עונג השבת.","\u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: אפילו יחיד המתפלל בערב שבת צריך לומר \"ויכלו\"\u0004 (בראשית ב, א־ג), וכפי ש\u0003אמר רב המנונא : כל המתפלל בערב שבת ואומר \"ויכלו\" מעלה עליו הכתוב כאילו נעשה שותף להקדוש ברוך הוא במעשה בראשית,\u0004 וכפי \u0003שנאמר: \"ויכלו\", אל תקרי\u0004 \u0005[אל תקרא]\u0006 \u0003\"ויכלו\" אלא \"ויכלו\",\u0004 כלומר: שניהם, הקדוש ברוך הוא והמזכיר ואומר דבר זה, נעשו בו שותפים כאילו שניהם יחד כילו את המלאכה. \u0003אמר ר' אלעזר: מניין שהדיבור כמעשה\u0004 — \u0003שנאמר: \"בדבר ה' שמים נעשו\u0004 וברוח פיו כל צבאם\u0003\"\u0004 (תהלים לג, ו).","\u0003אמר רב חסדא\u0004 שכך \u0003אמר מר עוקבא: כל המתפלל בערב שבת ואומר \"ויכלו\", שני מלאכי השרת המלוין לו לאדם\u0004 בכל עת \u0003מניחין\u0004 את \u0003ידיהן על ראשו ואומרים לו \"וסר עונך וחטאתך תכפר\"\u0004 (ישעיהו ו, ז). \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר יהודה אומר: שני מלאכי השרת מלוין לו לאדם בערב שבת מבית הכנסת לביתו,\u0004 מלאך \u0003אחד טוב ואחד רע. וכשבא לביתו ומצא נר דלוק ושלחן ערוך ומטתו מוצעת, מלאך טוב אומר: \"יהי רצון שתהא לשבת אחרת כך\", ומלאך רע עונה \"אמן\" בעל כרחו. ואם לאו\u0004 \u0005[לא]\u0006 מצא כאמור, \u0003מלאך רע אומר: \"יהי רצון שתהא לשבת אחרת כך\", ומלאך טוב עונה \"אמן\" בעל כרחו.\u0004","\u0003אמר ר' אלעזר: לעולם יסדר אדם שלחנו בערב שבת\u0004 בכל ההכנות לסעודה חשובה \u0003אף על פי שאינו צריך\u0004 לאכילה \u0003אלא לכזית. ואמר ר' חנינא: לעולם יסדר אדם שלחנו במוצאי שבת\u0004 לסעודה לכבוד שבת היוצאת, \u0003אף על פי שאינו צריך\u0004 לאכילה \u0003אלא לכזית.\u0004 ובסעודת מוצאי שבת אמרו: \u0003חמין במוצאי שבת מלוגמא\u0004 (רפואה), \u0003פת חמה במוצאי שבת\u0004 — \u0003מלוגמא.\u0004 ומסופר: \u0003ר' אבהו הוה עבדין ליה באפוקי שבתא עיגלא תילתא, הוה אכיל מיניה כולייתא\u0004 \u0005[ר' אבהו היו עושים לו במוצאי שבת עגל משולש\u0006 ו\u0005היה אוכל ממנו כליה\u0006 אחת\u0005].\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003גדל אבימי בריה\u0004 \u0005[בנו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבימי לאביו: \u0003למה לך לאפסודי כולי האי\u0004 \u0005[להפסיד כל כך],\u0006 \u0003נשבוק כולייתא ממעלי שבתא\u0004 \u0005[נניח כליה מערב שבת]\u0006 ולא יצטרכו לשחוט עגל שלם רק לצורך זה. ואכן \u0003שבקוהו ואתא אריא אכליה\u0004 \u0005[הניחוהו\u0006 לעגל זה ולא שחטוהו \u0005ובא אריה ואכלו],\u0006 ללמד שאין לו לאדם לקמץ בדבר שהוא לכבוד השבת.","ואגב הדברים בשכר המענג את השבת, מביאים בדומה לכך מה שאמרו בשכר אמירת \"אמן\". \u0003אמר ר' יהושע בן לוי: כל העונה \"אמן יהא שמיה רבא מברך\" בכל כחו,\u0004 כלומר, בכל לבו, \u0003קורעין לו גזר דינו, שנאמר: \"בפרע פרעות בישראל בהתנדב עם ברכו ה'\"\u0004 (שופטים ה, ב), \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003\"בפרע פרעות\",\u0004 שמתפרש כאן, ביטול (פריעה) פורענויות — \u0003משום\u0004 ש\u0003ברכו ה',\u0004 והאומר \"אמן יהא שמיה רבא\" ומברך את השם, קורעים לו גזר דינו. \u0003ר' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן: אפילו יש בו\u0004 באומר ה\"אמן\" \u0003שמץ\u0004 (משהו, פגם) \u0003של עבודה זרה\u0004 — \u0003מוחלין לו.\u0004 וראיה לדבר: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"בפרע פרעות\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במעשה העגל: \"וירא משה את העם \u0003כי פרע הוא\u0004 כי פרעה אהרן לשמצה בקמיהם\" (שמות לב, כה), ומהשוואה זו למדים שאף מי שיש בו פרעות כענין עבודה זרה — מוחלים לו. \u0003אמר ריש לקיש: כל העונה \"אמן\" בכל כחו פותחין לו שערי גן עדן, שנאמר: \"פתחו שערים ויבא גוי צדיק שמר אמנים\"\u0004 (ישעיה כו, ב) \u0003אל תיקרי \"שומר אמנים\" אלא: שאומרים \"אמן\".\u0004 שקוראים \"שומר אמונים\" כמו \"שאומר אמנים\". \u0003מאי\u0004 \u0005[מה]\u0006 אפשר לדרוש במלה \u0003\"אמן\"? אמר ר' חנינא:\u0004 היא ראשי תיבות של \u0003\"אל מלך נאמן\".\u0004","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב : אין הדליקה מצויה אלא במקום שיש\u0004 בו \u0003חילול שבת, שנאמר: \"ואם לא תשמעו אלי לקדש את יום השבת ולבלתי שאת משא\u0004 ובא בשערי ירושלים ביום השבת \u0003והצתי אש בשעריה ואכלה ארמנות ירושלים ולא תכבה\"\u0004 (ירמיהו י״ז:כ״ז, בז). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ולא תכבה\"? אמר רב נחמן בר יצחק:\u0004 שתהא הדליקה \u0003בשעה שאין בני אדם מצויין לכבותה. אמר אביי: לא חרבה ירושלים אלא בשביל שחללו בה את השבת, שנאמר: \"ומשבתותי העלימו עיניהם ואחל בתוכם\"\u0004 (יחזקאל כב, כו) וכעונש על כך נאמרו כמה דברי פורענויות על ירושלים.","ומכאן להסברים אחרים על סיבת החורבן. \u0003אמר ר' אבהו: לא חרבה ירושלים אלא בשביל שביטלו\u0004 בה \u0003קריאת שמע שחרית וערבית, שנאמר: \"הוי משכימי בבקר שכר ירדפו\u0004 מאחרי בנשף יין ידליקם. \u0003והיה כנור ונבל תף וחליל ויין משתיהם ואת פעל ה' לא יביטו\u0004 ומעשה ידיו לא ראו\u0003\"\u0004 (ישעיה ה, יא־יב), כלומר, בבוקר ובערב כשראוי לקרוא קריאת שמע היו עסוקים בשתיית יין או בנשפים, ונאמר: \u0003\"לכן גלה עמי מבלי דעת\u0004 וכבודו מתי רעב והמונו צחה צמא\u0003\"\u0004 (ישעיה ה, יג).","\u0003אמר רב המנונא: לא חרבה ירושלים אלא בשביל שביטלו בה תינוקות של בית רבן\u0004 מלימוד תורה, \u0003שנאמר:\u0004 \"ואת חמת ה' מלאתי נלאיתי הכיל \u0003שפך על עולל בחוץ\u0004 ועל סוד בחורים יחדיו כי גם איש עם אשה ילכדו זקן עם מלא ימים\u0003\"\u0004 (ירמיה ו, יא). והוא מסביר: \u0003מה טעם שפך\u0004 החימה — \u0003משום\u0004 ש\u0003עולל בחוץ\u0004 ברחובות ואינו לומד תורה. \u0003אמר עולא: לא חרבה ירושלים אלא מפני שלא היה להם בושת פנים זה מזה, שנאמר: \"הובישו כי תועבה עשו גם בוש לא יבושו\u0004 גם הכלים לא ידעו לכן יפלו בנופלים בעת פקדתים יכשלו אמר ה'\u0003\"\u0004 (ירמיה ו, טו). \u0003אמר ר' יצחק: לא חרבה ירושלים אלא בשביל שהושוו\u0004 בה \u0003קטן וגדול\u0004 ולא העריכו כראוי את גדולי הדור, \u0003שנאמר: \"והיה כעם ככהן\u0004 כעבד כאדוניו כשפחה כגבירתה כקונה כמוכר כמלווה כלווה כנושה כאשר נושא בו\u0003\"\u0004 (ישעיה כד, ב), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחר כך]:\u0006 \u0003\"הבוק תבוק הארץ\u0004 והבוז תבוז כי ה' דבר את הדבר הזה\" (ישעיה כד, ג).","\u0003אמר רב עמרם בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בר אבא\u0004 שכך \u0003אמר ר' שמעון בר אבא\u0004 שכך \u0003אמר ר' חנינא: לא חרבה ירושלים אלא בשביל שלא הוכיחו זה את זה, שנאמר: \"היו שריה כאילים לא מצאו מרעה\u0004 וילכו בלא כח לפני רודף\u0003\"\u0004 (איכה א, ו), והוא מסביר: \u0003מה איל זה\u0004 דרכו בעת רעייתם, להפנות \u0003ראשו של זה בצד זנבו של זה\u0004 וכל אחד רועה לעצמו, \u0003אף ישראל שבאותו הדור כבשו\u0004 את \u0003פניהם בקרקע ולא הוכיחו זה את זה. אמר ר' יהודה: לא חרבה ירושלים אלא בשביל שביזו בה תלמידי חכמים,\u0004 וכפי \u0003שנאמר: \"ויהיו מלעבים במלאכי האלהים ובוזים דבריו ומתעתעים בנביאיו עד עלת חמת ה' בעמו עד לאין מרפא\"\u0004 (דברי הימים ב', לו טז). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד לאין מרפא \"? אמר רב יהודה אמר רב:\u0004 ששמעו ש\u0003כל המבזה תלמידי חכמים אין לו רפואה למכתו.\u0004","\u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אל תגעו במשיחי ובנביאי אל תרעו\"\u0004 (דברי הימים א', טז, כב) \u0003\"אל תגעו במשיחי\"\u0004 — \u0003אלו תינוקות של בית רבן,\u0004 שהם יקרים וחשובים כמלכים וכהנים (מהרש\"א), \u0003\"ובנביאי אל תרעו\"\u0004 — \u0003אלו תלמידי חכמים. אמר ריש לקיש משום\u0004 (בשם) \u0003ר' יהודה נשיאה: אין העולם מתקיים אלא בשביל הבל\u0004 דברי תורה של \u0003תינוקות של בית רבן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 למוד התורה \u0003דידי ודידך מאי\u0004 \u0005[שלי ושלך מהו],\u0006 כלומר, מדוע יגרע ערך דברי התורה שאנו המבוגרים לומדים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו דומה הבל\u0004 פה של מבוגרים \u0003שיש בו חטא, להבל\u0004 פה של ילדים \u0003שאין בו חטא. ואמר ריש לקיש משום ר' יהודה נשיאה: אין מבטלין תינוקות של בית רבן\u0004 מלימודם \u0003אפילו לבנין בית המקדש. ואמר ריש לקיש לר' יהודה נשיאה: כך מקובלני מאבותי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר לו: כך מקובלני \u0003מאבותיך: כל עיר שאין בה תינוקות של בית רבן\u0004 לומדי תורה \u0003מחריבין אותה, רבינא אמר: מחרימין אותה.\u0004","\u0003ואמר רבא: לא חרבה ירושלים אלא בשביל שפסקו ממנה אנשי אמנה\u0004 (אנשים נאמנים), \u0003שנאמר: \"שוטטו בחוצות ירושלים וראו נא [ודעו ובקשו ברחובותיה אם תמצאו איש] (אם יש איש) עושה משפט מבקש אמונה ואסלח לה\"\u0004 (ירמיהו ה, א). ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב קטינא: אפילו בשעת כשלונה של ירושלים לא פסקו ממנה אנשי אמנה, שנאמר: \"כי יתפש איש באחיו בית אביו לאמר שמלה לכה קצין תהיה לנו\u0004 והמכשלה הזאת תחת ידך\u0003\"\u0004 (ישעיה ג, ו). כלומר, \u0003דברים שבני אדם מתכסין בהן כשמלה\u0004 שהם דברים נעלמים \u0003ישנן בידיך\u0004 ואתה יודע בהם, לכן ראוי אתה להיות ממונה על הצבור. ומה שנאמר: \u0003\"והמכשלה הזאת תחת ידך\",\u0004"],["\u0003דברים\u0004 של תורה \u0003שאין בני אדם עומדין עליהם אלא אם כן נכשלים בהן ישנן תחת ידיך,\u0004 על כן \u0003\"קצין תהיה לנו \".\u0004 ומה שנאמר: \u0003\"ישא ביום ההוא לאמר לא אהיה חבש\u0004 ובביתי אין לחם ואין שמלה לא תשימוני קצין עם\u0003\"\u0004 (ישעיהו ג, ז), \u0003אין \"ישא\" אלא לשון שבועה, וכן הוא אומר: \"לא תשא את שם ה'\u0004 אלהיך לשוא\u0003\"\u0004 (שמות כ, יז). \u0003\"לא אהיה חבש\"\u0004 — כוונתו: \u0003לא אהיה מחובשי עצמן בבית המדרש,\u0004 ואין אני רגיל בכך, \u0003\"ובביתי אין לחם ואין שמלה\"\u0004 — \u0003שאין בידי לא מקרא ולא משנה ולא גמרא.\u0004 ואם כן היו אנשי אמנה שהודו שלא למדו תורה, אפילו בשעת חורבנה של ירושלים. ודוחים: \u0003וממאי\u0004 \u0005[וממה]\u0006 מסיק אתה שהיה זה מחמת נאמנות? \u0003דילמא שאני התם, דאי אמר להו גמירנא, אמרו ליה: אימא לן\u0004 \u0005[שמא שונה שם, ש\u0006כן \u0005אם יאמר להם למדתי, יאמרו לו: אמור לנו],\u0006 וכיון שאינו יודע, בעל כורחו עליו להודות שלא למד! ודוחים: אין זו קושיה, שכן \u0003הוה ליה למימר\u0004 \u0005[היה\u0006 \u0003לו לומר]\u0004 לפחות כי \u0003גמר\u0004 \u0005[למד]\u0006 \u0003ושכח.\u0004 ושואלים: אם כן הרי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא אהיה חבש\"\u0004 — משמעו: \u0003כלל,\u0004 שמעולם לא למד, והוא מודה על האמת, ולא ששכח! ומשיבים: מעיקרו של דבר \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ויש לחלק ולומר כי \u0003כאן\u0004 ששנינו שהם נאמנים — הרי זה \u0003בדברי תורה,\u0004 ואילו \u0003כאן\u0004 ששנינו שבטלו אנשי אמנה בירושלים — הרי זה \u0003במשא ומתן.\u0004","\u0003מצילין\u0004 בשבת מן הדליקה וכיוצא בה \u0003סל מלא ככרות,\u0004 ו\u0003אף על פי שיש בו\u0004 מזון המספיק ל\u0003מאה סעודות, ו\u0004כן מצילים \u0003עיגול של דבילה\u0004 אף על פי שהוא גדול מאד, \u0003ו\u0004כן \u0003חבית\u0004 שלמה \u0003של יין. ו\u0004אף \u0003אומר לאחרים: בואו והצילו לכם. ואם היו\u0004 המצילים \u0003פיקחין, עושין עמו חשבון אחר השבת\u0004 לקבל שכר על הדברים שהצילו.","\u0003להיכן מצילין אותן\u0004 את הדברים שמוצאים מן הדליקה — \u0003לחצר המעורבת\u0004 שמותר לטלטל לתוכה, \u0003בן בתירה אומר: אף לשאינה מעורבת. ולשם מוציא\u0004 את \u0003כל כלי תשמישו, ולובש כל מה שיכול ללבוש, ועוטף כל מה שיכול לעטוף\u0004 כדי להציל בדרך זו. \u0003ר' יוסי אומר:\u0004 מותר לאדם ללבוש בבת אחת רק \u0003שמונה עשר כלים\u0004 (בגדים), שכן נוהגים כך לפעמים ללבוש ולא יותר. \u0003ו\u0004אולם \u0003חוזר ולובש\u0004 בגדים במספר הזה \u0003ומוציא\u0004 אותם, \u0003ו\u0004כן \u0003אומר לאחרים: בואו והצילו עמי.\u0004","ומקשים: \u0003והא תנא ליה רישא\u0004 \u0005[והרי שנה בתחילה,\u0006 במשנה הקודמת\u0005]\u0006 שמצילים \u0003שלש סעודות ותו\u0004 \u0005[ויותר]\u0006 \u0003לא! אמר רב הונא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן,\u0004 שהתירו הרבה — הרי זה \u0003בבא להציל\u0004 שיש לו לקחת סל אחד או עיגול אחד, ואילו \u0003כאן\u0004 שהתירו רק מזון שלוש סעודות — הרי זה \u0003בבא לקפל\u0004 (לאסוף) את הדברים. שאם \u0003בא להציל\u0004 — \u0003מציל את כולן\u0004 הנמצאים במקום אחד. ואם \u0003בא לקפל\u0004 — \u0003אינו מקפל אלא מזון שלש סעודות.\u0004 ואילו \u0003ר' אבא בר זבדא אמר\u0004 בשם \u0003רב: אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003בבא לקפל, ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003כאן\u0004 שהתירו הרבה — הרי זה כשמעביר אותם \u0003לאותה חצר, כאן\u0004 שהתירו רק מזון שלש סעודות — הרי זה כשמעביר אותם \u0003לחצר אחרת. בעי\u0004 \u0005[שאל]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: פירש טליתו\u0004 על הארץ \u0003וקיפל, והניח וקיפל, והניח\u0004 הדברים לתוך הטלית, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005],\u0006 האם \u0003כבא להציל דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003או כבא לקפל דמי\u0004 \u0005[\u0006הוא \u0005נחשב]?\u0006","ומנסים לפתור זאת \u0003מ\u0004מה ש\u0003אמר רבא: אטעיה\u0004 \u0005[הטעה אותו]\u0006 \u0003רב שיזבי לרב חסדא, ודרש\u0004 רב חסדא (ר\"\"ח) בהלכה בענין שבירת חבית בראש הגג, והוסיף: \u0003ובלבד שלא יביא כלי שהוא מחזיק יותר משלש סעודות.\u0004 וכיון שאמר רבא שטעות היא, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שהלוקח בבת אחת כמות גדולה \u0003כבא להציל דמי, ושפיר דמי\u0004 \u0005[\u0006הוא \u0005נחשב, ויפה\u0006 הדבר, מותר\u0005נחשב].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: מאי טעותא\u0004 \u0005[מה הטעות]\u0006 בדברי רב חסדא, שמא באמת יש בכך איסור? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003ובלבד שלא יביא כלי אחר ויקלוט,\u0004 או \u0003כלי אחר ויצרף.\u0004 משמע מדברים אלה: דווקא \u0003כלי אחר הוא\u0004 ש\u0003לא\u0004 יביא, \u0003אבל בההוא מנא\u0004 \u0005[באותו כלי]\u0006 — \u0003כמה דבעי\u0004 \u0005[שרוצה]\u0006 \u0003מציל,\u0004 ולא נתנו חכמים שיעור לכלי.","\u0003ו\u0004עוד שנינו במשנה שיכול להציל מן הדליקה \u0003עיגול של דבילה,\u0004 ואומר לאחרים שיבואו ויצילו להם, ואם רצו עושים עמו חשבון אחר השבת. ותוהים: \u0003חשבון מאי עבידתיה\u0004 \u0005[מה מעשיו]\u0006 כאן? והלא \u0003מהפקירא קזכו\u0004 \u0005[מן ההפקר הם זוכים],\u0006 כלומר, לשם מה צריכים אותם אנשים לעשות חשבון, ומה חשבון יש בדבר? הלא זכו אותם אנשים מן ההפקר, וכל מה שהצילו — הצילו לעצמם, ואינם צריכים להחזיר לבעלים! \u0003אמר רב חסדא: מדת חסידות שנו כאן.\u0004 ואותם חסידים רוצים להחזיר את החפצים לבעליהם, אף שאינם חייבים לעשות כן מן הדין, ולהם התירו לקבל שכר טרחתם. על כך \u0003אמר רבא: חסידי אגרא דשבתא שקלי\u0004 \u0005[\u0006וכי \u0005חסידים נוטלים שכר\u0006 בעד עבודה בשבת\u0005]?!\u0006 \u0003אלא אמר רבא: הכא\u0004 \u0005[כאן]\u0006 \u0003בירא שמים\u0004 שאינו חסיד גמור \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ולא ניחא ליה דליתהני\u0004 \u0005[ואין\u0006 זה \u0005נוח\u0006 \u0005לו להנות]\u0006 \u0003מאחרים, ובחנם נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניחא ליה דליטרח\u0004 \u0005[נוח לו לטרוח].\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003ואם היו פיקחין, דידעי דכהאי גוונא לאו\u0004 \u0005[ש\u0006הם \u0005יודעים\u0006 שבכגון זה לא] \u0003שכר שבת הוא,\u0004 ומעיקר הדין מותר לקחת שכר כזה, שהרי אינם מקבלים אלא מקצת מערך הדברים שהם נותנים בחינם, \u0003עושין עמו חשבון לאחר השבת.\u0004","שנינו במשנה שאומר לאחרים: בואו והצילו לכם. ועוד שנינו: \u0003ולהיכן מצילין?\u0004 לדעת התנא קמא — לחצר המעורבת, ולדעת בן בתירה אף לחצר שאינה מעורבת. ושואלים: \u0003מאי שנא הכא\u0004 \u0005[מה שונה כאן]\u0006 לענין הצלת מזון \u0003דקתני\u0004 \u0005[ששנינו\u0006 בתחילת המשנה\u0005]\u0006 שאומר לאחרים \u0003\"\u0004בואו והצילו \u0003לכם\", ומאי שנא הכא\u0004 \u0005[ומה שונה כאן]\u0006 לענין הצלת בגדים \u0003דקתני\u0004 \u0005[ששנינו\u0006 בסוף המשנה\u0005]\u0006 שאומר לאחרים \u0003\"\u0004בואו והצילו \u0003עמי\"?\u0004 ומשיבים: \u0003גבי\u0004 \u0005[אצל]\u0006 ענין \u0003מזונות קתני\u0004 \u0005[שנינו]\u0006 בלשון \u0003\"לכם\", משום דלא קא חזו\u0004 \u0005[שאינו ראוי]\u0006 לו \u0003אלא מזון שלש סעודות,\u0004 ומכל השאר יכולים רק אחרים ליהנות. \u0003אבל גבי\u0004 \u0005[אצל]\u0006 ענין \u0003לבושים קתני\u0004 \u0005[שנה]\u0006 לשון \u0003\"עמי\", משום דקחזי ליה לכולי יומא\u0004 \u0005[שראוי לו לכל היום],\u0006 שהרי מותר לו ללבוש בגדים אחרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: הרוצה להציל מן הדליקה ומונחה במקומה הרבה בגדים, הריהו \u0003לובש\u0004 מהם ו\u0003מוציא\u0004 אותם למקום בטוח, \u0003ופושט\u0004 אותם שם, \u0003וחוזר\u0004 למקום הדליקה \u0003ולובש\u0004 מהם שוב \u0003ומוציא ופושט, ואפילו כל היום כולו,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: שמנה עשר כלים\u0004 בלבד, \u0003ואלו הם שמנה עשר\u0004 ה\u0003כלים: מקטורן\u0004 (מעיל), \u0003אונקלי\u0004 (כעין כיסוי רחב על הכתפיים), \u0003ופונדא\u0004 (אזור גדול חלול על הבגדים), \u0003קלבוס\u0004 (בגד רחב) \u0003של פשתן, וחלוק\u0004 הצמוד לבשרו, \u0003ואפיליות\u0004 שמתעטפים בהן מלמעלה, \u0003ומעפורת\u0004 על הראש, \u0003ושני ספרקין\u0004 (רצועות, חגורות קטנות), \u0003ושני מנעלים, ושני אנפילאות\u0004 (גרביים) \u0003ושני פרגד\u0004 (כעין מגפים גבוהים) \u0003וחגור שבמתניו\u0004 שעל החלוק, \u0003וכובע שבראשו, וסודר שבצוארו.\u0004","\u0003ר' שמעון בן ננס אומר: פורסין עור של גדי\u0004 שהוא לח \u0003על גבי שידה תיבה ומגדל\u0004 (ארון) \u0003שאחז בהן את האור\u0004 (אש) \u0003מפני שהוא מחרך,\u0004 שהאש אינה שורפת את עור הגדי הלח אלא רק חורכת אותו, ועל ידי כך יישמרו כלי העץ. \u0003ועושין מחיצה\u0004 לשריפה \u0003בכל הכלים, בין מלאין בין ריקנים, בשביל שלא תעבור הדליקה. ר' יוסי אוסר בכלי חרס חדשים מלאין מים, לפי שאין יכולין לקבל את האור\u0004 (לסבול את חום האש) \u0003והן מתבקעין ומכבין את הדליקה\u0004 ואסור אף לגרום לכיבוי ביום השבת.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: טלית שאחז בה האור מצד אחד\u0004 — \u0003נותנין עליה מים מצד אחר, ואם\u0004 בשל \u0003כך כבתה\u0004 האש — \u0003כבתה. מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003טלית שאחז בה האור מצד אחד\u0004 — \u0003פושטה\u0004 (מותח אותה לכל אורכה) \u0003ומתכסה בה, ואם כבתה\u0004 — \u0003כבתה. וכן ספר תורה שאחז בו האור\u0004 — \u0003פושטו\u0004 (פותחו) \u0003וקורא בו, ואם כבה\u0004 — \u0003כבה.\u0004 נמצא שאסור לשפוך מים ממש, אלא רק לעשות מעשה של היתר, שעל ידו אולי תכבה האש!"],["\u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003ר' שמעון בן ננס\u0004 במשנתינו.","ושואלים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' שמעון בן ננס \"מפני שהוא מחרך\",\u0004 והתיר לשים עור גדי משום שאינו נשרף, אולם \u0003גרם\u0004 (דבר הגורם) \u0003כיבוי מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אכן גם לכך נתכוון ר' שמעון בן ננס, ולמדנו זאת \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו בסוף\u0006 המשנה\u0005]\u0006 ש\u0003ר' יוסי אוסר בכלי חרס חדשים מלאים מים,\u0004 לפי \u0003שאינן יכולים לקבל את האור\u0004 (האש) \u0003והן מתבקעין ומכבין את הדליקה.\u0004 ו\u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ר' שמעון, \u0003שרי\u0004 \u0005[מתיר].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נר ש\u0004היה מונח \u0003על גבי טבלא\u0004 — \u0003מנער את הטבלה והיא,\u0004 הנר, \u0003נופלת. ואם כבתה\u0004 — \u0003כבתה. אמרי דבי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: לא שנו\u0004 היתר זה \u0003אלא בשוכח\u0004 את הנר על הטבלה בכניסת השבת, \u0003אבל במניח\u0004 אותו מתחילה עליה — \u0003נעשה\u0004 הטבלה \u0003בסיס לדבר האסור,\u0004 ואף היא עצמה אסורה בטלטול.","\u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003נר ש\u0004היה עומד \u0003אחורי הדלת\u0004 — \u0003פותח ונועל\u0004 את הדלת \u0003כדרכו, ואם כבתה\u0004 — \u0003כבתה. לייט עלה\u0004 \u0005[מקלל\u0006 וגוער \u0005עליה,\u0006 על העושה כן\u0005]\u0006 \u0003רב. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מאי טעמא לייט עלה\u0004 \u0005[מה טעם קילל\u0006 וגער \u0005עליה]\u0006 \u0003רב? אילימא\u0004 \u0005[אם תאמר]\u0006 שהטעם הוא \u0003משום\u0004 ש\u0003רב סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 שכל מלאכה שאינו מתכוין לעשותה אסורה, \u0003ו\u0004ה\u0003תנא קתני\u0004 \u0005[שנה]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שמלאכה שאין מתכוין לה מותרת. ואולם \u0003משום\u0004 ש\u0003רב סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה, כל דתני\u0004 \u0005[השונה]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון מילט לייט ליה\u0004 \u0005[הריהו מקלל אותו]?!\u0006 והרי נסמך על דברי תנא ואי אפשר לבטל את דבריו לגמרי.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בהא\u0004 \u0005[ב\u0006מקרה \u0005זה]\u0006 \u0003אפילו ר' שמעון מודה\u0004 שאסור. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 כלומר, בכל פעולה המתחייבת מן המעשה ואפילו איננו מתכוון לה, שאף לדעת ר' שמעון העושה אותה חייב.","\u0003אמר רב יהודה: פותח אדם דלת כנגד מדורה בשבת.\u0004 ומסופר: \u0003לייט עלה\u0004 \u0005[מקלל\u0006 היה \u0005עליה,\u0006 על העושה כן\u0005]\u0006 \u0003אביי.\u0004 ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם מדובר]\u0006 \u0003ב\u0004אופן שבחוץ מנשבת \u0003רוח מצויה\u0004 — \u0003מאי טעמיה דמאן\u0004 \u0005[מה הטעם של מי]\u0006 ש\u0003אסר,\u0004 שהרי רוח כזו אינה מבעירה או מכבה מדורה. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 מדובר \u0003ב\u0004אופן שבחוץ מנשבת \u0003רוח שאינה מצויה\u0004 — \u0003מאי טעמא דמאן דשרי\u0004 \u0005[מה הטעם של מי שהתיר]?!\u0006 ומשיבים: \u0003לעולם\u0004 תאמר שמדובר \u0003ברוח מצויה,\u0004 ואולם \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, אביי, \u0005סבור]\u0006 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 משום רוח שאינה מצויה, \u0003ומר סבר לא גזרינן\u0004 \u0005[וחכם זה,\u0006 רב יהודה, \u0005סבור\u0006 ש\u0005אין אנו גוזרים].\u0006","שנינו במשנה ש\u0003עושין מחיצה\u0004 בכל מיני כלי חרס, ור' יוסי אסר בכלי חרס חדשים. ושואלים: \u0003למימרא דרבנן סברי\u0004 \u0005[האם נאמר שחכמים סבורים]\u0006 כי \u0003גרם\u0004 (דבר הגורם) \u0003כבוי מותר\u0004 בשבת, \u0003ור' יוסי סבר\u0004 \u0005[סבור]\u0006 כי \u0003גרם כבוי אסור? והא איפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שמענו אותם]\u0006 אומרים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עושין מחיצה בכלים ריקנין, ובמלאין שאין דרכן להשתבר. ואלו מלאין שאין דרכן להשתבר\u0004 — \u0003כלי מתכות. ר' יוסי אומר: אף כלי\u0004 חרס של \u0003כפר שיחין וכלי כפר חנניה אין דרכן להשתבר.\u0004 ונמצא שר' יוסי מתיר יותר משאר חכמים! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003איפוך מתניתין\u0004 \u0005[הפוך\u0006 את \u0005משנתנו]\u0006 ותייחס את דעת ר' יוסי לחכמים, \u0003ו\u0004תאמר כי \u0003ר' יוסי\u0004 המוזכר ב\u0003ברייתא לדבריהם,\u0004 לשיטתם של חכמים \u0003קאמר\u0004 \u0005[אמר]\u0006 והוא עצמו אינו סבור כן, אלא התיר בכל הכלים. ואולם \u0003ומי מצית אפכת לה\u0004 \u0005[והאם יכול אתה להפוך אותה,\u0006 את המשנה\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: מאן תנא\u0004 \u0005[מיהו\u0006 התנא הסבור \u0005ו\u0006\u0005שונה]\u0006 \u0003גרם כבוי אסור\u0004 — \u0003ר' יוסי!\u0004","אלא \u0003לעולם לא תיפוך\u0004 \u0005[תהפוך],\u0006 \u0003ו\u0004ה\u0003ברייתא כולה\u0004 שיטת \u0003ר' יוסי היא. וחסורי מחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 הברייתא \u0005וכך יש לשנותה]:\u0006 \u0003עושין מחיצה בכלים ריקנין ובמלאים שאין דרכן להשתבר. ואלו הן כלים שאין דרכן להשתבר: כלי מתכות, וכלי כפר שיחין, וכלי כפר חנניה נמי\u0004 \u0005[גם כן]\u0006 \u0003אין דרכן להשתבר, שר' יוסי אומר: אף כלי כפר שיחין וכלי כפר חנניה אין דרכן להשתבר.\u0004","סיכמנו איפוא שר' יוסי סבור שגרם כיבוי אסור, וחכמים מתירים. \u0003ורמי דרבנן אדרבנן\u0004 \u0005[משליכים,\u0006 מראים סתירה \u0005מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים\u0006 עצמם\u0005],\u0006 \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי \u0003ר' יוסי\u0004 במקום אחר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה שם\u0004 של קדושה, אחד משמות ה', \u0003כתוב לו\u0004 לאדם \u0003על בשרו\u0004 — \u0003הרי זה לא ירחוץ\u0004 במים שמא ימחק, \u0003ולא יסוך\u0004 בשמן, \u0003ולא יעמוד במקום הטינופת\u0004 שאין זה לכבוד השם. \u0003נזדמנה לו טבילה של מצוה\u0004 — \u0003כורך עליה\u0004 על חלק גופו שכתוב עליו השם \u0003גמי\u0004 (פיסת גומא), \u0003ויורד וטובל. ר' יוסי אומר: לעולם יורד וטובל כדרכו\u0004 אף כשאין זו טבילה של מצווה, \u0003ובלבד שלא ישפשף\u0004 וימחוק בידים ממש. נמצא שר' יוסי מקיל יותר מחכמים בגרימת איסור!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004ונתצתם את מזבחותם ושיברתם את מצבותם ואשריהם תשרפון באש ופסילי אלהיהם תגדעון \u0003ואבדתם את שמם מן המקום ההוא לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ג־ד), ומן הלשון \"לא תעשון\" למד ר' יוסי: \u0003עשייה\u0004 ממש \u0003הוא\u0004 ש\u0003אסור,\u0004 ואולם \u0003גרמא שרי\u0004 \u0005[גרם\u0006 מלאכה \u0005מותר].\u0006","ומקשים: \u0003אי הכי, הכא נמי\u0004 \u0005[אם כן, כאן גם כן]\u0006 בענין שבת, \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"\u0004ויום השביעי שבת לה' אלהיך \u0003לא תעשה כל מלאכה\"\u0004 (שמות כ, י), ואף כאן תלמד מן הלשון \u0003שעשייה הוא\u0004 ש\u0003אסור,\u0004 ואולם \u0003גרמא שרי\u0004 \u0005[גרם\u0006 מלאכה \u0005מותר]!\u0006 ומתרצים: באמת סבור ר' יוסי שאין איסור מהותי בגרם כיבוי, אלא \u0003מתוך שאדם בהול על ממונו, אי שרית ליה\u0004 — \u0003אתי לכבויי\u0004 \u0005[אם תתיר לו\u0006 גרם כיבוי — \u0005יבוא לכבות]\u0006 בידים, ולכן אסרו גרימת כיבוי.","ואומרים: \u0003אי הכי קשיא דרבנן אדרבנן\u0004 \u0005[אם כן קשה\u0006 מדברי \u0005חכמים\u0006 על דברי \u0005חכמים]:\u0006 \u0003ומה התם\u0004 \u0005[שם]\u0006 בשריפה ש\u0003אדם בהול על ממונו\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 במחיקת \u0003השם — לא כל שכן\u0004 שמותר לגרום למחיקה שלא בידים, ומדוע החמירו חכמים בברייתא בענין זה?!","ודוחים: \u0003ותסברא\u0004 \u0005[והאם סבור אתה]\u0006 וכיצד אתה חושב \u0003האי גמי היכי דמי\u0004 \u0005[גמי זה\u0006 שאמרו חכמים לכסות בו בעת הטבילה \u0005איך הוא בדיוק],\u0006 באיזה אופן מדובר? \u0003אי דמיהדק\u0004 \u0005[אם ש\u0006הוא \u0005מהודק]\u0006 — \u0003קא הוי\u0004 \u0005[\u0006הרי \u0005זו]\u0006 \u0003חציצה\u0004 גמורה, \u0003אי לא מיהדק\u0004 \u0005[אם אינו מהודק]\u0006 — הלא \u0003עיילי ביה מיא\u0004 \u0005[נכנסים בו מים]\u0006 ומוחקים! ודוחים: אם חוששים ל\u0003חציצה, תיפוק ליה\u0004 \u0005[תצא לו]\u0006 שיש חציצה בין כה וכה \u0003משום\u0004 ה\u0003דיו\u0004 עצמה בה רשום שם ה' על בשרו! ומתרצים: מדובר כאן \u0003ב\u0004דיו \u0003לחה,\u0004 שאינה חוצצת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הדם והדיו\u0004 ו\u0003הדבש והחלב\u0004 שהיו על בשר אדם, אם היו \u0003יבשין\u0004 — \u0003חוצצין,\u0004 בשעת טבילה, \u0003לחים\u0004 — \u0003אין חוצצין.\u0004 ולענייננו, \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 לשם מה צריכים חכמים כריכת גמי?","\u0003אלא אמר רבא בר רב שילא: היינו טעמייהו דרבנן\u0004 \u0005[זהו טעמם של חכמים]:\u0006 \u0003דקסברי\u0004 \u0005[שסבורים הם]\u0006 ש\u0003אסור\u0004 לאדם \u0003לעמוד בפני השם\u0004 כשהוא \u0003ערום,\u0004 ומשום כך צריך שתהיה מחיצה בין בשרו הערום ובין השם. ומקשים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' יוסי סבר\u0004 \u0005[סבור]\u0006 ש\u0003מותר לעמוד בפני השם ערום?\u0004 ומתרצים: לא, הוא אינו סבור כן, אלא אינו מצריך גמי, וסבור כי די יהיה \u0003דמנח ידיה עילויה\u0004 \u0005[שמניח\u0006 את \u0005ידו עליו\u0006 ומכסהו\u0005].\u0006","ומקשים: \u0003לרבנן נמי דמנח ידיה עילויה\u0004 \u0005[ל\u0006דעת \u0005חכמים גם כן\u0006 יהא מספיק \u0005שמניח ידו עליו]!\u0006 ומסבירים: חכמים חוששים לכך ש\u0003זימנין דמשתלי ושקיל ליה\u0004 \u0005[פעמים ש\u0006הוא \u0005שוכח ומוריד אותה,\u0006 את ידו\u0005].\u0006 ומקשים: ו\u0003ל\u0004דעת \u0003ר' יוסי נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש ש\u0003זימנין דמשתלי ושקיל ליה\u0004 \u0005[\u0006\u0005פעמים שישכח ויסיר אותה,\u0006 את ידו\u0005]?\u0006 \u0003אלא\u0004 יש לומר: \u0003אי דאיכא\u0004 \u0005[אם,\u0006 כאשר \u0005יש]\u0006 \u0003גמי\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 מודה ר' יוסי שיש לכרוך, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה,\u0006 באיזה מקרה \u0005אנו עוסקים]\u0006 — שיש צורך \u0003לאהדורי\u0004 \u0005[לחזר,\u0006 ולחפש\u0005]\u0006 אחר \u0003גמי,\u0004 ובכגון זה \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006"],["\u0003טבילה בזמנה לאו\u0004 \u0005[לא]\u0006 \u0003מצוה\u0004 היא, \u0003ומהדרינן\u0004 \u0005[ומחזרים]\u0006 אחר גמי כדי לכרוך על מקום הטבילה, \u0003ור' יוסי סבר\u0004 \u0005[סבור]\u0006 כי \u0003טבילה בזמנה מצוה ו\u0004משום כך \u0003לא מהדרינן\u0004 \u0005[אין אנו מחזרים]\u0006 אחרי הגמי, כיון שחשובה מצות הטבילה בזמנה.","ומקשים: \u0003וסבר\u0004 \u0005[וכי סבור]\u0006 \u0003ר' יוסי\u0004 כי \u0003טבילה בזמנה מצוה\u0004 היא? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הזב והזבה, המצורע והמצורעת, בועל נדה וטמא מת,\u0004 כל אלה \u0003טבילתן\u0004 צריכה \u0003להיות ביום,\u0004 ואף אם היה זה ביום הכיפורים שאסורה בו הרחיצה — טובל בו ביום. \u0003נדה ויולדת\u0004 — \u0003טבילתן בלילה. בעל קרי\u0004 — \u0003טובל והולך כל היום כולו\u0004 אחר שראה קרי. \u0003ר' יוסי אומר: מן המנחה ולמעלה\u0004 (והלאה) \u0003אינו צריך לטבול,\u0004 שכיון שהתפלל כבר תפילת מנחה ימתין עד הערב ויטבול ויוכל להתפלל מעריב בטהרה. נמצא שסבור ר' יוסי שטבילה בזמנה אינה מצוה! ודוחים: בברייתא \u0003ההיא\u0004 אין הכוונה לסתם ר' יוסי (בן חלפתא), אלא כשיטת \u0003ר' יוסי בר' יהודה היא,\u0004 ש\u0003אמר : דייה טבילה באחרונה,\u0004 שאשה שנסתפקה בזמן הראוי לטבילתה, אינה חייבת לטבול בכל פעם, ומותר לה לדחות את הטבילה עד לתאריך שתצא ידי חובה לדעת הכל, אף כי אולי לא תהא זו טבילה בזמנה.","\u0003גוי שבא לכבות\u0004 דליקה אצל ישראל — \u0003אין אומרים לו: \"כבה\" ו\u0004אין אומרים לו \u0003\"אל תכבה\", מפני שאין\u0004 חובת \u0003שביתתו עליהן,\u0004 על ישראל, \u0003אבל\u0004 ילד \u0003קטן\u0004 ישראל \u0003שבא לכבות\u0004 בשבת — \u0003אין שומעין לו\u0004 שיכבה, אף שעדיין אינו מחוייב במצוות, \u0003מפני ששביתתו עליהן.\u0004","\u0003אמר ר' אמי: ב\u0004שעת \u0003דליקה התירו לומר\u0004 בפני גוים: \u0003\"כל המכבה אינו מפסיד\",\u0004 שיבואו גויים ויכבו, שלא נאסר אלא לומר להם במפורש. ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 לשיטה זו, ממה ששנינו במשנתנו: \u0003גוי שבא לכבות\u0004 — \u0003אין אומרים לו \"כבה\", ו\u0004כן \u0003\"אל תכבה\" מפני שאין שביתתו עליהן.\u0004 ונדייק מלשון המשנה: \u0003\"כבה\" הוא דלא אמרינן ליה\u0004 \u0005[שאין אנו אומרים לו],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"כל המכבה אינו מפסיד\"\u0004 — \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 וראיה היא אם כן לדברי ר' אמי? ודוחים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]\u0006 \u0003\"אל תכבה\" לא אמרינן ליה\u0004 \u0005[אין אנו אומרים לו],\u0006 ומכאן נלמד כי \u0003\"כל המכבה אינו מפסיד\" נמי לא אמרינן ליה\u0004 \u0005[גם כן אין אנו אומרים לו],\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין ללמוד ממנה]\u0006 דברים בדרך הדיוק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מעשה ונפלה דליקה\u0004 בשבת \u0003בחצירו של יוסף בן סימאי ב\u0004מקום \u0003שיחין, ובאו אנשי גיסטרא\u0004 \u0005[המבצר]\u0006 \u0003של ציפורי לכבות\u0004 את הדליקה, \u0003מפני שאפוטרופוס של מלך היה\u0004 ורצו לעזור לו, \u0003ולא הניחן\u0004 יוסף בן סימאי בעל החצר לכבותה \u0003מפני כבוד השבת, ונעשה לו נס וירדו גשמים וכיבו. לערב\u0004 במוצאי שבת \u0003שיגר\u0004 \u0005[שלח]\u0006 \u0003לכל אחד מהן\u0004 מן החיילים שבאו לעזרתו \u0003שתי סלעין, ולאפרכוס\u0004 \u0005[ולמפקד]\u0006 \u0003שבהן\u0004 — \u0003חמשים. וכששמעו חכמים בדבר, אמרו: לא היה צריך לכך,\u0004 למנעם מלכבות, \u0003שהרי שנינו\u0004 במשנתנו: \u0003גוי שבא לכבות\u0004 — \u0003אין אומרים לו \"כבה\" ו\u0004כן \u0003\"אל תכבה\",\u0004 אלא יעשה הגוי כרצונו.","שנינו במשנה: \u0003אבל קטן שבא לכבות אין שומעין לו\u0004 שיכבה \u0003מפני ששביתתו עליהן \u0004. ורוצים להסיק: \u0003שמעת מינה\u0004 \u0005[שומע אתה\u0006 מהלכה \u0005זו]\u0006 כי \u0003קטן\u0004 ש\u0003אוכל נבלות\u0004 או עושה שאר איסורים, \u0003בית דין מצווין עליו להפרישו\u0004 ונפתור על ידי כך בעיה שנתעוררה בנושא זה. ודוחים: \u0003אמר ר' יוחנן:\u0004 כאן מדובר \u0003בקטן העושה לדעת אביו\u0004 ולכן מצווים אנו להפרישו, אבל קטן החוטא מדעתו אין חייבים להפרישו מן האיסור. ושואלים: ואם כן \u0003דכוותה גבי\u0004 \u0005[בדומה לזה אצל,\u0006 בענין\u0005]\u0006 \u0003גוי\u0004 צריך לומר שמדובר באופן \u0003דקא עביד לדעתיה\u0004 \u0005[שעושה לדעתו]\u0006 של \u0003ישראל,\u0004 ו\u0003מי שרי\u0004 \u0005[\u0006ו\u0005כי\u0006 \u0005מותר]\u0006 הדבר?! והרי אסור ליהנות ממה שעשה גוי עבור ישראל, בשבת! ודוחים: אין הדבר כן, אלא \u0003גוי לדעתיה דנפשיה עביד\u0004 \u0005[לדעת עצמו\u0006 הוא \u0005עושה]\u0006 שהוא נשכר בכיבוי הדליקה ואינו עושה משום דעת ישראל.","\u0003כופין\u0004 בשבת \u0003קערה על גבי הנר בשביל שלא תאחוז\u0004 האש \u0003בקורה. ו\u0004כן כופים קערה \u0003על צואה של קטן\u0004 שעשה צרכיו בתוך הבית, שלא יגע בה ולא ילכלך עצמו. \u0003ו\u0004כן \u0003על עקרב שלא תישך. אמר ר' יהודה: מעשה בא לפני רבן יוחנן בן זכאי\u0004 בכפרו \u0003בערב\u0004 שכיסה אדם עקרב בשבת, \u0003ואמר\u0004 רבן יוחנן: \u0003חוששני לו מחטאת\u0004 שמא יש בכך איסור מן התורה.","מסופר: \u0003רב יהודה ורב ירמיה בר אבא ורב חנן בר רבא איקלעו לבי\u0004 \u0005[הזדמנו לבית]\u0006 \u0003אבין\u0004 ש\u0003מן\u0004 המקום \u0003נשיקיא. לרב יהודה ורב ירמיה בר אבא\u0004"],["\u0003אייתו להו פורייתא\u0004 \u0005[הביאו להם מיטות]\u0006 לשבת עליהן, ואילו \u0003לרב חנן בר רבא לא אייתו ליה\u0004 \u0005[הביאו לו],\u0006 ונעלב רב חנן, וכעס על מארחו. \u0003אשכחיה מתני ליה לבריה\u0004 \u0005[מצא אותו\u0006 את ר' אבין \u0005מלמד לבנו]\u0006 במשנתנו זו: \u0003ועל צואה של קטן מפני קטן\u0004 שלא יגע בה ולא ילכלך עצמו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אבין שטיא\u0004 \u0005[השוטה]\u0006 \u0003מתני שטותא לבניה\u0004 \u0005[שונה שטות לבנו],\u0006 \u0003והלא היא,\u0004 הצואה \u0003עצמה מוכנת ל\u0004אכילת \u0003כלבים,\u0004 ודבר הראוי לאכילת כלב מותר לטלטלו, ולמה יש לכסות את הצואה אם אפשר להוציאה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003לא חזיא ליה\u0004 \u0005[היתה ראויה לו]\u0006 \u0003מאתמול,\u0004 שהרי מאתמול לא הכין צואה זו עבור הכלבים — הרי זה אינו מעכב, \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005הרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נהרות המושכין\u0004 מים \u0003ומעיינות הנובעין\u0004 — אין אנו אומרים שיש להם תחום שבת מסויים, אלא \u0003הרי הן\u0004 מותרים לשימוש בכל מקום ותחומם \u0003כרגלי כל אדם\u0004 ששואב מהם, כיון שדרכן לעבור ממקום למקום והרי זה כאילו הכינום לצורך זה. ואף כאן, כיון שדרך הקטן לעשות צרכיו בכל מקום, הרי זה כמוכן מערב שבת.","ושאל ר' אבין: \u0003ואלא היכי אתנייה\u0004 \u0005[כיצד אשנה לו]?\u0006 ענה לו, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003על צואה של תרנגולים\u0004 שמים קערה \u0003מפני קטן\u0004 והקשו:","\u0003ותיפוק ליה דהוי גרף של רעי\u0004 \u0005[ותצא לו,\u0006 ימצא בדבר היתר, מפני \u0005שהוא\u0006 כ\u0005כלי של צואה]\u0006 שהתירו לטלטלו מפני המיאוס! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003גרף של רעי\u0004 \u0005[כלי של צואה]\u0006 \u0003אגב מנא\u0004 \u0005[כלי]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 מותר לטלטלו, ואולם \u0003איהו גופיה\u0004 \u0005[הוא עצמו],\u0006 כלומר הצואה — \u0003לא\u0004 הותר לטלטלה, \u0003והא ההוא\u0004 \u0005[והרי אותו]\u0006 \u0003עכבר דאישתכח באיספרמקי\u0004 \u0005[שנמצא בין הבשמים]\u0006 של \u0003רב אשי, ואמר להו\u0004 \u0005[להם]\u0006 למשמשיו: \u0003נקוטו בצוציתיה ואפקוה\u0004 \u0005[אחזו בזנבו והוציאוהו],\u0006 נמצא שדבר שיש בו מיאוס מותר לטלטלו אף בלא כלי! אלא יש לומר שהצואה היתה \u0003באשפה,\u0004 וכיון שאינה בפני בני הבית לא התירו לטלטלה אלא רק לכסותה מפני הקטן. ושאלו: \u0003וקטן באשפה מאי בעי ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005שם],\u0006 שהרי ריכוז האשפה הגדול הוא ברשות הרבים ואינו קרוב לבית, וכיצד יגיע לשם הקטן? ועונים שלא היתה הצואה באשפה אלא \u0003בחצר.\u0004 ודוחים: והלא ב\u0003חצר נמי גרף של רעי\u0004 \u0005[גם כן כלי של צואה]\u0006 \u0003הוא\u0004 ומותר להוציאו! אלא יש לומר כי מדובר \u0003באשפה שבחצר,\u0004 ולעתים מגיע לשם הקטן, אך כיון שהמקום מיוחד לאשפה אין בו משום מיאוס, ואסור לטלטל את הצואה מטעם זה.","\u0003ו\u0004עוד שנינו במשנה שכופים בשבת קערה \u0003על עקרב\u0004 כדי \u0003שלא תישך. אמר ר' יהושע בן לוי: כל המזיקין נהרגין בשבת. מתיב\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף\u0004 ממה ששנינו בברייתא: \u0003חמשה\u0004 בעלי חיים \u0003נהרגין\u0004 אף \u0003בשבת, ואלו הן: זבוב\u0004 ארסי \u0003שבארץ מצרים, וצירעה שבנינוה, ועקרב שבחדייב, ונחש שבארץ ישראל, וכלב שוטה בכל מקום.\u0004 ונברר את הדברים, \u0003מני\u0004 \u0005[\u0006ברייתא זו \u0005של מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שכשיטת \u0003ר' יהודה\u0004 היא — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 כי \u0003מלאכה שאינה צריכה לגופה חייב עליה\u0004 ואסור להרוג אף בעלי חיים אלה. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003ר' שמעון, והני הוא דשרי\u0004 \u0005[ואלה הם שמותר]\u0006 להורגם, אבל \u0003אחריני\u0004 \u0005[אחרים]\u0006 — \u0003לא!\u0004","\u0003אמר ר' ירמיה: ומאן נימא לן דהא מתרצתא\u0004 \u0005[ומי יאמר\u0006 \u0003לנו ש\u0004ברייתא \u0005זו מיושבת]\u0006 \u0003היא? דילמא משבשתא\u0004 \u0005[שמא משובשת]\u0006 \u0003היא\u0004 ואין להקשות ממנה? \u0003אמר רב יוסף: אנא מתנינא לה, ואותיבנא לה, ואנא מתריצנא לה\u0004 \u0005[אני שניתי אותה, ו\u0006אני \u0005הקשיתי ממנה, ואני אתרץ אותה]\u0006 כך: מה שהתיר ר' יהושע בן לוי להרוג בשבת את כל המזיקים הרי זה \u0003ברצו אחריו,\u0004 שכאשר הם רצים אחריו יש בכך חשש סכנה, \u0003ו\u0004לכן ל\u0003דברי הכל\u0004 מותר.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רבא בר רב הונא: ההורג נחשים ועקרבים בשבת\u0004 — \u0003אין רוח חסידים נוחה הימנו\u0004 (ממנו). \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בר רב הונא: \u0003ואותן חסידים אין רוח חכמים נוחה מהם,\u0004 שהם גורמים על ידי כך להזיק את הבריות, ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 אימרה זו על שיטת \u0003רב הונא.\u0004 ש\u0003רב הונא חזייה לההוא גברא דקא קטיל זיבורא\u0004 \u0005[ראה אדם אחד שהוא הורג צרעה]\u0006 בשבת. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שלימתינהו לכולהו\u0004 \u0005[וכי השלמת,\u0006 גמרת, \u0005להרוג את\u0006 כל הצרעות \u0005כולן]?\u0006 והרי שלא היתה דעתו נוחה ממנו.","\u0003תנו רבנן\u0004 \u0005[שנו\u0006 חכמים] בברייתא: מי ש\u0003נזדמנו לו נחשים ועקרבים,\u0004 אם \u0003הרגן\u0004 — \u0003בידוע שנזדמנו לו\u0004 שיזכה \u0003להורגן. לא הרגן\u0004 — \u0003בידוע שנזדמנו\u0004 הם \u0003כדי להורגו ו\u0004אולם \u0003נעשה לו נס מן השמים\u0004 וניצל. \u0003אמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן:\u0004 המדובר \u0003בנישופין\u0004 (נוגעים ומתחככים) (ר\"ח) \u0003בו,\u0004 שאם לא פגעו בו אז, \u0005ודאי הוא משום שאירע לו נס.\u0006","\u0003אמר ר' אבא בר כהנא: פעם אחת נפל\u0004 נחש \u0003אחד בבית המדרש,\u0004 בשבת, \u0003ועמד ניותי\u0004 (על שם מקומו) \u0003אחד והרגו. אמר רבי: פגע בו כיוצא בו!\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם נבין \u0003ש\"פגע בו כיוצא בו\"\u0004 כוונתו \u0003דשפיר עביד\u0004 \u0005[שיפה עשה],\u0006 \u0003או לא? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה שמסופר ש\u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא ור' זירא הוו יתבי אקילעא דבי\u0004 \u0005[היו יושבים בחצר בית]\u0006 \u0003ר' ינאי. נפק מילתא מבינייהו\u0004 \u0005[יצא הדבר מביניהם],\u0006 כלומר, שוחחו בו, ו\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מר' ינאי\u0004 שאלה זו: \u0003מהו\u0004 הדין, האם מותר \u0003להרוג נחשים ועקרבים בשבת? אמר להו\u0004 \u0005[להם]:\u0006 \u0003צירעה\u0004 — \u0003אני הורג, נחש ועקרב\u0004 — \u0003לא כל שכן,\u0004 שסכנתם מרובה ומותר להרגם. ודוחים: ראייה גמורה אין כאן, \u0003דילמא\u0004 \u0005[שמא]\u0006 לא הותר אלא כשרומסו \u0003לפי תומו,\u0004 בתוך דרך הילוכו, שאינו נראה לאחרים כמתכוון לדריסה. וכפי ש\u0003אמר רב יהודה: רוק דורסו\u0004 בשבת \u0003לפי תומו\u0004 ואינו חושש משום ממחק או משוה גומות. \u0003ואמר רב ששת: נחש דורסו לפי תומו. ואמר רב קטינא: עקרב דורסו לפי תומו.\u0004","מסופר: \u0003אבא בר מרתא\u0004 ש\u0003הוא אבא בר מניומי הוה מסקי ביה דבי ריש גלותא זוזי\u0004 \u0005[היו נושים בו\u0006 בני \u0005בית ראש הגולה כסף].\u0006 \u0003אייתיוהו, קא מצערי ליה\u0004 \u0005[הביאוהו\u0006 לבית ראש הגולה \u0005ו\u0006\u0005ציערו אותו]\u0006 כדי להכריחו לשלם, ואותו יום שבת היה. \u0003הוה שדי רוקא\u0004 \u0005[היה מוטל רוק\u0006 שם\u0005].\u0006 \u0003אמר להו ריש גלותא\u0004 \u0005[להם ראש הגולה]\u0006 לבני ביתו: \u0003אייתו מאנא סחיפו עלויה\u0004 \u0005[הביאו כלי ושימו עליו]\u0006 כדי שלא ידרסו אנשים את הרוק, \u0003אמר להו\u0004 \u0005[להם]\u0006 אבא בר מניומי: \u0003לא צריכיתו\u0004 \u0005[אין אתם צריכים\u0006 לכך\u0005],\u0006 שכן \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה: רוק דורסו\u0004 בשבת \u0003לפי תומו. אמר להו\u0004 \u0005[להם]\u0006 ראש הגולה: לבני ביתו: \u0003צורבא מרבנן\u0004 \u0005[תלמיד חכם]\u0006 \u0003הוא, שבקוהו\u0004 \u0005[הניחוהו].\u0006","וכיון שהוזכרו דברי ר' אבא בר כהנא מביאים עוד מדבריו. \u0003אמר ר' אבא בר כהנא\u0004 שכך \u0003אמר ר' חנינא: פמוטות של בית רבי מותר לטלטלן בשבת,\u0004 ואולם לא היה ברור מה טיבם של פמוטות אלה, ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא:\u0004 האם מדובר כאן \u0003ב\u0004פמוטות ה\u0003ניטלין בידו אחת\u0004 שקטנים הם, \u0003או\u0004 אף הניטלים \u0003בשתי ידים?\u0004"]]};
